INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6a8f9a3b', 't-mm-01-008', 'html', '<ul><li><strong>Ovarian Cancer:</strong></li><li>(Avoid)</li><li><strong>Endometrial Cancer:</strong></li></ul>
<p>Type 1: Stage 1 and 2</p>
<p>E only if no chance of malignant focus</p>
<p>Type 1: Stage 3 and 4 avoid.</p>
<p>Type 2: Avoid.</p>
<ul><li><strong>C</strong><strong>ervical</strong><strong> Cancer</strong><strong>: </strong></li><li>squamous cell carcinoma</li><li>stage 1 and 2</li><li>Continuous combined therapy (CCT) or Estrogen (according to status of uterus)</li><li>stage 3 &amp; 4 – Avoid.</li><li>Adenocarcinoma (avoid)</li><li><strong>Vaginal + vulval Cancer: </strong></li><li>Seq cell = Estrogen or CCT.</li><li>non seq – avoid</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
