INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b84118cc', 't-mm-01-015', 'html', '<table><tbody><tr><td><strong>xx</strong></td><td><strong>xy</strong></td></tr><tr><td><strong>1.</strong><strong>TURNER:</strong><br/>Typical =&gt; p0 Amenorrhea, subfertility<br/>Atypical =&gt; 15% (menses, fertility, SSC Normal<br/>Incidence = 1/200<br/>Streak gonads<br/>Risk of cataract, leukemia<br/>Life expectancy 55 years.<br/>Ovum donation – 27.5% pregnancy rate<br/><strong>RISK OF PREGNACY – MDT:</strong><br/>HTN – 15-17%<br/>Aortic dissection 1-2%<br/>CS- 80-100%<br/>PTB – 12-38%<br/>Low birth 18-57%<br/>Typhoid problem<br/>DM<br/><strong>Management of Turner</strong><strong>:</strong><br/>Puberty induction: done in collaboration with paedsS endocrinologist.<br/>Breast development: in 2 stages.<br/>1st stage = low dose estrogen to avoid irregular breast development either oral or transdermal.<br/>2nd stage = progesterone after 2 years of estrogen.<br/>Fertility option:<br/>Fertility preservation if ovulating like in mosaic.<br/>Ovum donation.<br/>Adoption.<br/><strong>Fertility options:Surrogacy.Adoption.Fertility options:Surrogacy.Adoption.</strong><strong>Fertility options:</strong>Surrogacy.Adoption.<strong>Fertility options:</strong>Surrogacy.Adoption.<strong>2.</strong><strong>MRKH: </strong><br/><strong>Fertility options:</strong><br/>Surrogacy.<br/>Adoption.<br/><strong>Fertility options:</strong><br/>Surrogacy.<br/>Adoption.<br/>P0 Amenorrhea<br/>20 SSC are normal<br/><strong>MRI: is gold standard Test</strong><br/>Uterus absent<br/>Ovaries present<br/>No need of HRT.</td><td><strong>1.</strong><strong>CAIS: </strong>complete androgen insensitivity syndrome.<br/>Absent uterus<br/>Breast developed.<br/>Public/Axillary sparse – Tanner stage 2,3.<br/><strong>Treatment:</strong><br/>ERT (no need of progestogen) after gonadectomy<br/>Gonadectomy after puberty at 18yrs, risk of malignancy 2%<br/><strong>2.S</strong><strong>WYer’s Syndrome:</strong><br/>Absent SRY gene on Y Chromosome<br/>External genitalia phenotypically – Female<br/>Ambiguous Gentelia, clitoromegaly<br/>Infantile uterus<br/>SSC =&gt; underdeveloped.<br/>t/m =&gt; Gonadectomy:<br/>Immediately due to risk of malignancy<br/>=&gt; HRT NO ERT<br/>=&gt; Surrogacy /Adoption<br/>=&gt; Vaginoplasty</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a87d0bae', 't-mm-01-015', 'html', '<table><tbody><tr><td><strong>DSD</strong></td><td><strong>Karyotype</strong></td><td><strong>Ex-Genitalia</strong></td><td><strong>Internal</strong><strong> genitalia</strong></td><td><strong>Special factors</strong></td></tr><tr><td>CAH<br/>Commonest autosomal recessive<br/>Classical type:<br/>11- Hydroxy deficiency = HTN + hypokalemia<br/>21- Hydroxy deficiency = hypotension + Hyperkalemia</td><td>XX</td><td>Masculinized ambiguous Gentelia</td><td>Uterus + ovary<br/>present</td><td>Glucocorticoids + Mineralocorticoid deficiency<br/><strong>Types:</strong><br/>1. Salt wasting type15%<br/>2. Non salt wasting type 25%<br/>(hyponatremia, hyperkalemia)<br/>Treated with glucocorticoids + Mineralocorticoid</td></tr><tr><td>Late onset<br/>Non classical mild</td><td>XX</td><td>Feminized but hirsutism<br/><strong>D/D:</strong><br/>Cushing<br/>PCOD<br/>Thyroid<br/>Androgen<br/>Sec tumor</td><td>Uterus + ovary<br/>present</td><td>Late onset/ Non-classic<br/>Treated by hydrocortisone</td></tr><tr><td>CAIS</td><td>XY</td><td>Female</td><td>Testes</td><td>&nbsp;</td></tr><tr><td>Swyer</td><td>XY</td><td>Female</td><td>Streak gonad</td><td>&nbsp;</td></tr><tr><td>5α-Reductase deficiency</td><td>XY</td><td>Female /ambiguous @ birth<br/>Male @ puberty</td><td>Testes<br/>present</td><td>60-80% transform from female to male @ some point</td></tr><tr><td>17α-Hydroxy steroid Dehydrogenase<br/>Type 3 deficiency</td><td>XY</td><td>Fe/ambiguous @ birth<br/>male @ puberty</td><td>Tests</td><td>60-80% transform from male to female @ some point</td></tr><tr><td>46XX/XX Ovo-testicular DSD</td><td>71% XX<br/>20% XX/XX<br/>7% XY</td><td>Ambiguous</td><td>Ovo-testes or male ducts</td><td>Fertility described<br/>Male-Fathering<br/>Female-carrying pregnancy</td></tr></tbody></table>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
