INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-48b882cc', 't-mm-01-017', 'html', '<h3><strong>OBS</strong><strong>TETRIC </strong><strong>RISK</strong><strong>:</strong></h3>
<ul><li>miscarriage</li><li>PTB</li><li>Malpresentation</li><li>Pre-eclampsia</li><li>IUGR</li><li>Still birth</li><li>Septate =&gt; worse obstetric outcome</li></ul>
<h3><strong>Diagnosis of CUA</strong></h3>
<ul><li><strong>3D TVs </strong></li><li>Look for external indentation</li><li>internal indentation</li><li>septal length</li><li>Gold standard. (in luteal phase)</li><li><strong>MRI</strong> in complex CUA</li><li><strong>Renal Track </strong></li><li>investigate in all women with CUA by</li><li>MRI, USG, IVU, - depends upon Scenario.</li></ul>
<h3><strong>Management @:</strong></h3>
<h3><strong>Absent vagina, uterus, Cervix</strong><strong>:</strong></h3>
<p>at tertiary care level</p>
<p>Under MDT cover</p>
<h3><strong>Rudimentary hor</strong><strong>n:</strong></h3>
<p>at either secondary or tertiary care levels according to expertise available.</p>
<h3><strong>Septate uterus</strong><strong>:</strong></h3>
<h3><em>Treatment:</em></h3>
<ul><li>Hysteroscopic septal resection</li></ul>
<h3><em><strong> </strong></em><em>indication: </em></h3>
<ul><li>P` subfertility, recurrent miscarriages.</li><li>Adhesion formation prevention by</li><li>Estrogen</li><li>IUD</li><li>Adhesive gel</li><li>Residual septum at least 1cm</li><li>look for both Ostia</li><li>2nd look Hysteroscopy: 1 – 3 months later.</li></ul>
<h3><strong>Role of psychological t/m:</strong></h3>
<ul><li>Improve results.</li><li>Better sexual outcomes &amp; satisfaction.</li></ul>', 18) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-01-018', 'chap-mm-01-01', '17. OUTFLOW TRACK DISORDERS OF VAGINA', 'Detailed medical reference and study guide on 17. OUTFLOW TRACK DISORDERS OF VAGINA.', 18, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-fd090746', 't-mm-01-018', 'html', '<ul><li><em><strong>Imperforate Hymen:</strong></em></li><li>Bluish Bulge</li><li>Treated by General gynaecologists @ secondary care level.</li><li><em><strong>Treatment: </strong></em></li><li>Cruciate incision, margins either timed or left as it is.</li><li>Complete drainage @ 3-5 days.</li><li><em><strong>Transverse vaginal septum</strong></em><em> </em>(1/30,000 – 1/50,000)</li><li><strong>Upper</strong><strong> (</strong><strong>A)</strong> most common 46%</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ddb002a6', 't-mm-01-018', 'image', '/uploads/content-images/maternal_mind_book/image8.jpeg', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2c7809da', 't-mm-01-018', 'html', '<h3><strong>Treatment:</strong></h3>
<ul><li>Resection +end to end anastomosis followed by insertion of moulds for 3-6months (risk of damage to bladder and rectum)</li><li>Risk of stenosis if moulds are not used or sexually inactive</li><li>Pregnancy rate only 20% following t/m due to tubal damage that has been occurred by hematosalpinx and endometriosis d/t Backflow of blood</li><li>c-section is recommended</li><li><strong>Middle</strong><strong> (B)</strong></li><li>30-40% of transverse septum</li><li>Pregnancy rate 40%</li><li>c/s is recommended</li><li><strong>Lower</strong><strong> (C)</strong></li><li><strong> </strong>15-20% of septum</li><li>Pregnancy rate 100%</li><li>Pinkish bulge</li><li><strong>t/m: </strong></li><li>Resection + Anastomosis + Moulds for 10days</li><li>Normal delivery is recommended</li></ul>
<p>All the vaginal septa are managed @ tertiary care level</p>
<h3><strong>Longitudinal Vaginal Septum:</strong></h3>
<ul><li>Longitudinal fusion defects.</li><li>Can be partial or complete</li><li>Can be high or low</li></ul>
<h3><strong>Presentation:</strong></h3>
<ul><li>abdominal pain</li><li>Worsening dysmenorrhea</li><li>Menstruation can be present – from communicating hemi-vaginum.</li><li>Haematocolpus + hematometra – from closed side</li><li>Uterus Didelphys =&gt; obstetric complications.</li></ul>
<p><strong>t/m:</strong> Excision</p>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-57939c15', 't-mm-01-018', 'image', '/uploads/content-images/maternal_mind_book/image9.jpg', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-01-019', 'chap-mm-01-01', '18. MRKH', 'Detailed medical reference and study guide on 18. MRKH.', 19, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c0564927', 't-mm-01-019', 'html', '<ul><li>-46 XY</li><li>Normal secondary sexual characters.</li><li>1 in 4000 – 5000.</li><li>Sporadic – Multifactorial inheritance</li><li>Autosomal dominant</li><li>Single gene defect HOX gene</li><li><em><strong>Classification:</strong></em></li><li><strong>Type </strong><strong>I</strong><strong>: (64%)</strong></li><li>Typical, symmetrical uterovaginal aplasia/Hypoplasia</li><li>Tubes + ovaries Normal, uterine buds Present</li><li><strong>Type II: (24%)</strong></li><li>Atypical, Asymmetrical UV aplasia/hypoplasia</li><li>Tubal Hypoplasia/Aplasia one or both</li><li>Ovarian malformation one or both</li><li>+ Renal Anomalies</li><li><strong>Type III: 12% MURCS Syndrome: </strong></li><li>Mullerian aplasia</li><li>Renal dysplasia</li><li>Cervical somite anomalies =&gt; Skeletal system and cardiac abnormality, muscular Weakness.</li><li><em><strong>Other organs involvement:</strong></em></li><li>Renal 40% – 12% absent kidney</li><li>Skeletal 12 – 20%</li><li>Auditory 10 – 25%</li><li>Cardiac Rarely</li><li>Sensory neural deafness</li><li><em><strong>Clinical presentation:</strong></em></li><li>P0 amenorrhea 70 – 80%</li><li>Cyclical abd pain – if functional endometrium in uterine bud, needs to be removed</li><li>Dyspareunia</li><li>Subfertility</li><li><em><strong>On Examination:</strong></em></li><li>Normal ssc</li><li>Ovaries – present</li><li>Uterus – absent</li><li>Vagina – blind</li><li><em><strong>Diagnostic tests:</strong></em></li><li>2D USG – initial</li><li>3D USG</li><li>MRI – Gold standard</li><li>IUV</li><li>Karyotyping to exclude CAIS</li><li>X ray spine + limbs</li><li>Echocardiogram</li><li><em><strong>D/D</strong></em></li><li>CAIS</li><li>Imperforate Hymen.</li></ul>
<h3><strong>MANAGEMENT:</strong></h3>
<ul><li><em><strong>Psychological support:</strong></em></li><li><em><strong>Fertility:</strong></em></li><li>Surrogacy (partial surrogacy) - egg retrieval via abdominal route</li><li><em><strong>Adoption</strong></em></li><li><em><strong>Uterine transplant</strong></em></li><li><em><strong>Creation of neo-vagina – </strong></em>timing depend on sexual activity.</li><li><em><strong>Surgical:</strong></em></li><li>(Out dated procedures)</li><li><strong>McIndoe procedure – </strong>postponed until sexually active.</li><li>Split skin graft between rectum and bladder over a Mould for 3 months.</li><li>Risk of stenosis, scaring @ Graft site</li><li>Graft failure, Bowel and bladder injury.</li><li><strong>Da</strong><strong>vydov</strong><strong> procedure:</strong></li><li>good anatomical and functional success</li><li>laparoscopically Peritoneum is mobilized to introitus to create vagina - post OP Molds r inserted for 6m0.</li><li><strong>Vecchietti procedure:</strong></li><li>Done laparoscopically - 98% Anatomical success 97% - functional success</li><li>olive shaped Beed placed over vaginal dimple, traction devices are attached over thread to Abdominal cavity 1.0 - 1.5cm traction is</li><li>given daily over 7-9 days, till vaginal length is 7-8cm.</li><li>regular sexual intercourse is suggested.</li><li><strong>William Vulvovaginoplasty:</strong></li><li>labial suturing to create pouch horizontal to perineum.</li><li><strong>Sigmoid vaginoplasty:</strong></li><li>Sigmoid colon is mobilized along with vessels @ introitus.</li><li><em><strong>Non-surgical:</strong></em></li><li>Glass dilators (1st line) 20- 30min for 3 times a day + lubricants or Analgesics</li><li>Success 81 - 88% up to - 91%.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-01-020', 'chap-mm-01-01', '19. DYSMENORRHEA', 'Detailed medical reference and study guide on 19. DYSMENORRHEA.', 20, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3dce81fe', 't-mm-01-020', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>Primary Dysmenorrhea</strong><br/>No underlying pathology</td><td><strong>Secondary Dysmenorrhea</strong><br/>Pain manifests underlying pathology</td></tr><tr><td>Age<br/>Onset<br/>Duration<br/>Nature</td><td>16-25<br/>Menarche<br/>8-72 hrs.<br/>Cramping pain<br/>+ vomiting<br/>Radiates to back<br/>Or upper legs</td><td>30 – 45<br/>After menarche<br/>Prior to onset &amp; throughout cycles<br/>Variable number of days<br/>Non cyclic/ cyclical episodes</td></tr><tr><td>Comorbidity</td><td>No</td><td>HMB, vaginal discharge, IMB, PCB, CPP, Bowel or urological symptoms</td></tr><tr><td>Response to NSAIDS</td><td>Yes</td><td>Yes, but may require further t/m</td></tr><tr><td>Examination</td><td>Normal</td><td>Fixed R/V Uterus<br/>Thickened Uterosacral ligaments<br/>Endometriotic nodules<br/>Adnexal mass<br/>Enlarge tender uterus.</td></tr><tr><td>Investigation</td><td>normal USG</td><td><strong>USG:</strong><br/>Adenomyosis<br/>Fibroids<br/>Endometriosis<br/><strong>Swabs:</strong><br/>PiD</td></tr></tbody></table>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
