INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-01-024', 'chap-mm-01-01', '23. PRECOCIOUS PUBERTY', 'Detailed medical reference and study guide on 23. PRECOCIOUS PUBERTY.', 24, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-90b3e5e0', 't-mm-01-024', 'html', '<ul><li>1:5000 – 1:10000</li><li>Female to male ratio 10:1</li><li>Development of SSC before age 8</li><li>Development of breast or Pubic hair before age 7 in white girls and before age 6 in black girls.</li><li><strong>Puberty:</strong> is a complex process consisting of:</li><li>Maturation of hypothalamic – pituitary – gonadal (HPO) axis.</li><li>Appearance of SSC</li><li>Growth spurt.</li><li>Capacity for fertility.</li><li>Puberty can be:</li><li><em><strong>Consonant </strong></em>– if it follows normal sequence.</li><li><em><strong>Disconsonant</strong></em> – if it is abnormal.</li><li>Puberty consists of physical changes.</li><li>Adolescence consists of psychological and social changes.</li><li>Puberty comes form 10 years onwards and usually takes 3 – 4 years with passage from one stage to another stage approximately every year.</li><li><strong>Thelarche:</strong> usually 1st sign of Puberty.</li><li>Development of breast bud – tanner stage (2).</li><li>Pubertal growth spurt occurs with breast budding, with peak velocity at mid puberty.</li><li>Menarche occurs within 2 – 3years of thelarche median age for menarche 13 years.</li><li><strong>Pubarche:</strong> development of pubic hair followed by axillary hair. Pubarche follows thelarche.</li></ul>
<h3><strong>Types of precocious Puberty:</strong></h3>
<ul><li><strong>Central precocious </strong><strong>puberty </strong>CPP</li><li><strong>Peripheral precocious </strong><strong>puberty </strong>PPP</li><li>Isolated variants</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ca5aedc1', 't-mm-01-024', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>CPP</strong></td><td><strong>PPP</strong></td></tr><tr><td><strong>HPO Axis</strong></td><td>Pre – mature activation</td><td>Not involved</td></tr><tr><td><strong>SSC</strong></td><td>Isosexual</td><td>Isosexual or can be contra sexual</td></tr><tr><td><strong>Pathology</strong></td><td><strong>CNS pathology:</strong><br/>Tumors<br/>Trauma<br/>Infections.<br/>Chemotherapy<br/>Radiotherapy<br/>Congenital lesions<br/><strong>Secondary to PPP</strong><br/><strong>Idiopathic 74%</strong></td><td><strong>1. </strong><strong>Ovarian causes:</strong><br/>EST<br/>Androgen secreting tumors (can cause contra sexual puberty).<br/>Functional ovarian cyst.<br/><strong>2. </strong><strong>Adrenal causes:</strong><br/>CAH (Contra sexual)<br/>Cushing syndrome (contra sexual)<br/>Neoplasm (iso or contra)<br/><strong>3. </strong><strong>Exogenous hormones:</strong><br/>COCP<br/>Skin creams<br/>Anabolic steroids.<br/><strong>McCune – Albright syndrome.</strong><br/><strong>Severe </strong><strong>long-standing</strong><strong> hypothyroidism.</strong></td></tr><tr><td><strong>Investigations:</strong><br/>Bone age</td><td>Advanced &gt; 2 years</td><td>Usually advance except in hypothyroidism</td></tr><tr><td>Estradiol</td><td>Variable</td><td>Very high (EST).</td></tr><tr><td>GnRH stimulation test<br/>Normally in pre – pubertal children FSH exceeds LH.<br/>In pubertal children LH exceeds FSH.<br/>Isolated thelarche FSH exceeds.</td><td>Gold standard Test<br/>LH: FSH ratio &gt; 1</td><td>Flat response.</td></tr><tr><td>Prolactin levels</td><td>Not elevated routinely<br/>When observed can be due to compression tumors</td><td>Can be elevated in McCune-Albright Syndrome (MAS) and chronic Hypothyroidism.</td></tr><tr><td>TFT’S</td><td>&nbsp;</td><td>T4,     TSH</td></tr><tr><td>Androgens<br/>DHEA, Androstenedione DHEA sulphate, 17α hydroxy progesterone.</td><td>&nbsp;</td><td>Increase in androgen secreting tumors.<br/>Urinary 17 – ketosteroid very high in adrenal tumors.</td></tr><tr><td>Pelvic USG + Abdominal USG.</td><td>Endometrial thickening + uterine volume &gt; 2ml or length &gt; 34mm and pear-shaped uterus is associated with progressive CPP</td><td>Functional cysts.<br/>Ovarian tumors.<br/>Adrenal tumors.</td></tr><tr><td>CT cranium</td><td>Tumors of head</td><td>normal</td></tr><tr><td>CT Adrenals</td><td>-</td><td>Tumors of adrenals</td></tr><tr><td>Skeletal Survey Bone scan</td><td>-</td><td>Polyostotic<br/>Fibrous dysplasia</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e8797edf', 't-mm-01-024', 'html', '<h3><strong>Evaluation of child with precocious puberty:</strong></h3>
<h3><strong>History:</strong></h3>
<ul><li>Age of onset</li><li>Sequence of events.</li><li>Family history, mother, sisters.</li><li>Neurological symptoms.</li><li>Exogenous steroids.</li></ul>
<h3><strong>Clinical Examination:</strong></h3>
<ul><li>Height, weight using age specific charts.</li><li>BMI.</li><li>Pubertal tanner stages.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f60bdc0c', 't-mm-01-024', 'image', '/uploads/content-images/maternal_mind_book/image12.jpg', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0984792a', 't-mm-01-024', 'html', '<ul><li>Neurological examination.</li><li>Fundoscopy, visual fields.</li><li>Skin lesions.</li><li>Abdominal examination.</li><li>External genitalia examination.</li><li>Signs of virilization.</li></ul>
<h3><strong>Biochemical tests and imaging:</strong></h3>
<ul><li>Given in table of comparison between CPP, PPP.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li><em><strong>Goals:</strong></em></li><li>Halt or regression of SSC.</li><li>Prevent early menarche.</li><li>Retard skeletal maturation and improve height – growth hormone can be added.</li><li>Avoid psychological/ Behavioral/ sexual sequence.</li></ul>
<p><em><strong>Referral to:</strong></em> pediatric Endocrinologist.</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
