INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-02-006', 'chap-mm-02-01', '1.5.IUI', 'Detailed medical reference and study guide on 1.5.IUI.', 6, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d2a6c8c8', 't-mm-02-006', 'html', '<h3><em><strong>Indications </strong></em>(unstimulated):</h3>
<ul><li>Same sex couples.</li><li>Unable to do sex.</li><li>Sperm washing is required.</li><li>Offer for 6 cycles.</li><li>Don’t conceive</li><li>Another 6 cycles.</li></ul>
<h3><strong>Don’t offer IUI</strong> (Stimulated or unstimulated):</h3>
<ul><li>Offer IVF after 2 years.Offer IVF after 2 years.Offer IVF after 2 years.Offer IVF after 2 years.Mild male factors</li><li>Endometriosis</li><li>Unexplained</li><li><strong>Except</strong> people have social, cultural &amp; religious objections to IVF.</li></ul>
<h3><strong>Donor insemination:</strong></h3>
<h3><em><strong>Indications:</strong></em></h3>
<ul><li>Obstructed Azoospermia</li><li>Non obstructed azoospermia.</li><li>Severe male factor.</li><li>Risk of transmission of genetic disorder</li><li>Risk of transmission of infection to women/offspring from male.</li><li>Severe isoimmunization RH incompatibility</li></ul>
<h3><strong>Steps in IUI:</strong></h3>
<ul><li>Screening of sperms.</li><li>Assessment of women.</li><li>Ovulation Assessment</li><li>Tubal assessment after 3 cycles.</li><li>Ovulating women =&gt; unstimulated IUI for 6 cycles.</li><li>Total 6 cycles are offered</li></ul>
<p><strong>Counselling </strong>by independent person.</p>
<h3><strong>Oocyte Donation:</strong></h3>
<h3><em><strong>Indications:</strong></em></h3>
<ul><li>POF</li><li>Gonadal dysgenesis turner syndrome</li><li>Bilateral oophorectomy</li><li>POF after chemo/Radio</li><li>Certain cases of IVF failure.</li><li><strong>Screening </strong>– genetic/infections disease.</li></ul>
<h3><strong>Genetics issues in ICSI:</strong></h3>
<ul><li>Appropriate genetic counselling</li><li>Severe male factor – offer karyotyping.</li><li>Non obstructive azoospermia – karyotyping.</li><li>Y – microdeletion testing X.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
