INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-03-005', 'chap-mm-03-01', '5. OVARIAN CYST IN CHILDREN AND ADOLESANTS (TEENS 13 – 15 YEARS)', 'Detailed medical reference and study guide on 5. OVARIAN CYST IN CHILDREN AND ADOLESANTS (TEENS 13 – 15 YEARS).', 5, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0f42ac5a', 't-mm-03-005', 'html', '<p><strong>Peak incidence:</strong> 1st year of life or around menarche.</p>
<ul><li>Commonest cause of abdominal cyst in fetus and Neonates. More common in 3rd due to   maternal Estrogen, fetal Gonadotropin, placental HCG.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
