INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bcd551a7', 't-mm-03-009', 'html', '<ul><li>Chromosome 17</li><li>Autosomal dominant gene defect.</li><li>Prophylactic BSO halves the risk.</li><li>OCP no role</li><li>If Pt refuses prophylactic BSO, 6 monthly CA 125 and TVS.</li><li>Daughter of BRA positive mother.</li><li>Negative then 10% risk only.</li><li>Positive then 40% risk.</li><li>Associated with fallopian tube cancer 16%</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
