INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-702b79cc', 't-mm-03-012', 'html', '<table><tbody><tr><td>1A<br/>micro invasive</td><td>&nbsp;</td><td><strong>MANAGEMENT</strong></td><td><strong>LND</strong></td><td><strong>5 YEARS</strong><br/><strong>SURVIVAL</strong></td><td><strong>1 YEAR survival</strong></td></tr><tr><td>&nbsp;</td><td>1A1: up to 3mm</td><td>Cone biopsy/ simple trachelectomy/ simple hysterectomy</td><td>_</td><td>79%</td><td>96%</td></tr><tr><td>&nbsp;</td><td>1A2: 3.1 – 5mm.</td><td>Cone biopsy/simple trachelectomy / simple hysterectomy</td><td>+</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>A1 + A2 + Lymph vascular space invasion</td><td>Cone biopsy simple trachelectomy simple hysterectomy. Fertility sparing surgery can be done up to low volume B1.</td><td>+</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>1B<br/>Macro invasive</td><td>1B1: &gt;5mm – 20mm</td><td>B1 – low volume simple trachelectomy/simple hysterectomy</td><td>+</td><td>&nbsp;</td><td>79%</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>Radical trachelectomy /Radical hysterectomy</td><td>+</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>1B2 &gt;2cm – &lt;4cm</td><td>Radical hysterectomy even fertility wishes</td><td>+</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>1B3: &gt; 4cm</td><td>Chemo Radiation/ Radical hysterectomy</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>STAGE II:</strong><strong> BEYOND C</strong><strong>ERVIX</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>2A<br/>Upper 3rd vagina</td><td>2A1: up to 4cm</td><td>Chemo Radiation/ Radical hysterectomy</td><td>49%</td><td>92%</td></tr><tr><td>&nbsp;</td><td>2A2: &gt; 4cm in dimension</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>2B involving parametria but not up to the pelvic wall</td><td>Chemo Radiation/ palliative surgery</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>STAG