INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-da34d442', 't-mm-03-014', 'html', '<table><tbody><tr><td><strong>SATGE I:</strong></td><td>&nbsp;</td><td><strong>MANAGEMENT</strong></td><td><strong>5 YEARS </strong><br/><strong>SURVIVAL</strong></td><td><strong>1 YEAR</strong></td></tr><tr><td><strong>  </strong>             <strong>A</strong><br/><strong>B</strong></td><td>Lesion &lt; 2cm no node involvement invasion &lt; 1mm.</td><td>Wide local excision.</td><td>95%</td><td>96%</td></tr><tr><td>&nbsp;</td><td>&gt; 2cm (2.1cm) invasion 1.1mm, no node involvement</td><td>Ipsilateral: Radical vulvectomy + ipsilateral L node dissection.<br/>Central or lesion lateral &gt; 4cm Radical vulvectomy + Bilateral lymph node dissection.</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>STAGE II:</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>Lower 1/3</strong><strong>rd</strong><strong> of urethra</strong><strong> or</strong><strong> vagina </strong><strong>or</strong><strong> Anus.</strong></td><td>Radiotherapy</td><td>85%</td><td>89%</td></tr><tr><td><strong>STAGE III:</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>  </strong>            <strong>A</strong><br/><strong>              </strong><strong>B</strong><br/><strong>              </strong><strong>C</strong></td><td>1. LN &gt; 5mm A1<br/>2. LN &lt; 5mm A2</td><td>Radiotherapy</td><td>75%</td><td>78%</td></tr><tr><td>&nbsp;</td><td>&gt; 2 LN &gt; 5mm OR<br/>&gt; 3 LN &lt;5mm.</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>Positive LN with extra capsular spread.</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>STAGE IV:</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>A</strong><br/><strong>                 </strong><strong>B</strong></td><td>- upper 3rd of urethra.<br/>- vagina, Bladder/ Rectum, mucosa<br/>- mucous, fixed o pelvic bone or fixed/ ulcerated inguinal L.N.</td><td>Radio</td><td>30%</td><td>43%</td></tr><tr><td>&nbsp;</td><td>Distant Mets * pelvic N.</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>Unknown stage 81%.</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-beb009f0', 't-mm-03-014', 'html', '<p>Table 11. CA – Vulva</p>
<ul><li><strong>Incisional Biopsy</strong>: for diagnosis of malignancy.</li><li><strong>Excisional Biopsy:</strong> where low suspicion of invasive CA and operator wishes to limit the cosmetic harm.</li><li><strong>Radical Excision:</strong>  At least 1cm clear margins.</li><li><strong>Wide/ local Excision:</strong> Margins of 15mm.</li><li><strong>Triple incision/ Butterfly incision:</strong></li><li><strong>Ipsilateral L nodes dissection</strong> =&gt; positive on biopsy =&gt; do contralateral dissection as interval procedure</li></ul>
<h3><strong>Wide local excision (no LND)</strong><strong> indications</strong></h3>
<ul><li>Stage 1a SCC.</li><li>Verrucous</li><li>VIN</li><li>Basel cell carcinoma</li><li>Melanoma</li><li><strong>Reconstructive surgery.</strong></li></ul>
<h3><strong>5 years’ </strong><strong>survival</strong><strong> ac</strong><strong>cording</strong><strong> to LN – diagnos</strong><strong>is</strong><strong>:</strong></h3>
<ul><li>Negative 92%.</li><li>Ipsilateral75%.</li><li>B/L30%.</li><li>2 nodes25%.</li><li>6 nodes0%.</li><li><strong>Multimodal Therapy:</strong></li><li>Tumor &gt;2cm + close to vital organs (urethra/Anus) + &gt;1mm invasion.</li><li>Radio =&gt; to reduce size =&gt; then surgery.</li><li>Recurrent Bartholin Abscess:</li><li>Biopsy to exclude CA.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
