INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ed10e4c5', 't-mm-05-002', 'html', '<table><tbody><tr><td><strong>Infection</strong></td><td><strong>%ages</strong></td><td><strong>Diagnosis</strong></td><td><strong>T/m</strong></td><td><strong>Alternative</strong></td><td><strong>Recurrent</strong></td><td><strong>TOC</strong></td><td><strong>Partner screening</strong></td><td><strong>Special note</strong></td></tr><tr><td><strong>Bacterial vagino</strong><strong>sis:</strong><br/>- Common cause of discharge<br/>- 20-40 years of age<br/>- fishy odor after intercourse because semen is alkaline.</td><td>5-50%<br/>TOP 30%<br/>Pregnancy 12%</td><td>Hay Ison<br/>Amsel’s<br/>G staining</td><td>*metronidazole 400mg, B.D, 5-7days, P/O  or 0.75% IV, 5day<br/>* clindamycin= 2% P/V for 7D</td><td>Tinidazole 2g<br/>OR<br/>Clinda 30mg P/O x 7days</td><td>Metronidazole 0.75 I/V x OD for 16D</td><td>Not recommended</td><td>Not recommended</td><td>*HIV – same t/m<br/>*TOP – same t/m<br/>*Pregnancy – I/V<br/>*Lactation – I/V<br/>Avoid oral</td></tr><tr><td><strong>Trichomonas</strong><br/>*Sexually transmitted<br/>*frothy discharge 20-40yrs of age</td><td>Asymptomatic 10-15%<br/>- Discharge 70%<br/>- Frothy 30%<br/>- Strawberry cervix 2%<br/>- urethral dx 20%</td><td><strong>Microscopy</strong> – initial HVS, VVS<br/><strong>Culture</strong> high sensitivity<br/><strong>NAAT</strong> gold std<br/>- VVS<br/>- HVS<br/>- Urine samples</td><td>Metronidazole<br/>400mg BD 5-7days<br/>OR<br/>2g Stat P/O or P/R</td><td>Tinidazole 2g stat</td><td><strong>Tinidazole</strong><br/>- expensive<br/>- Long t/2<br/>- Remain in tissues<br/>- more tissue penetration<br/><strong>Non Responders</strong><br/>- repeat regimen<br/>- High dose<br/>- Metronidazole 2g 0D for<br/>5 – 7D or 800TDS 7D<br/>- Tinidazole 1g TDS 14D, 2G B.D 14days</td><td>Recommended If<br/>- symptoms after t/m or<br/>- Recurrence.</td><td>Any partner within 4weeks tested for STI.</td><td><strong>HIV:</strong> B.D regimen for 7days<br/>2g dose not effective<br/><strong>Pregnancy </strong>– I/V<br/>Tind C/I in 1st<br/><strong>Lactation </strong>12 weeks<br/>Avoid lactation</td></tr><tr><td><strong>VVC</strong><br/>- 20-40yrs<br/>Low immunity<br/>=&gt;vulval + under Breast = candiasis<br/>=&gt;vulval + intra Breast pargets</td><td>90-90% candida Albicans<br/>*75% women @ least single episode<br/>*45%@ least (2) episode<br/>20% asymptomatic with colonization<br/>(absence of neutrophils on microscopy)</td><td><strong>Microscopy</strong> wet film<br/>HVS<br/>No pseudohyphea in candida Glabrata<br/>Neutrophils – candida albicans<br/>Blastophores – Candida Albicans<br/>Psendo hyphae – Candida Albicans<br/><strong>Culture</strong><br/>Sabouraud media</td><td>*Fluconazole 150 P/O or *clotrimazole 500mg p/v<br/>*<strong>Severe</strong> Fluconazole D1 &amp; D4 or clotrimazole 500 D1 &amp; D4</td><td>Clotrimazole cream 5g stat or clotrimazole pessary 200mg 3 nights.</td><td>*Fluconazole daily for 72 hours then weekly for 6m0 or *clotrimazole or topical imidazole daily 7 – 14days till response then 6m0 *or clotrimazole 500 weekly or * 50 – 100/day.</td><td>Not recommended</td><td>Not recommended</td><td><strong>Pregnancy</strong><br/>- topical or I/V<br/>- longer course clotrimazole 500 for 7ays</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>Non Albicans</strong><br/>Nystatin 100000 p/v 12-14nights.<br/>Boric acid or amphotericin B or flucytosine cream</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
