INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5e22d01b', 't-mm-05-002', 'html', '<table><tbody><tr><td><strong>Infection</strong></td><td><strong>%ages</strong></td><td><strong>Diagnosis</strong></td><td><strong>T/m</strong></td><td><strong>Alternative</strong></td><td><strong>Recurrence</strong></td><td><strong>TOC</strong></td><td><strong>Partner screening</strong></td><td><strong>Special note</strong></td></tr><tr><td><strong>Neisseria</strong><strong> </strong><strong>Gonorrhea</strong><br/>- mucopurulent dx<br/>- Major cause of testicular system.<br/>- Affecting urethra<br/>- Urinary symptoms.</td><td>- 50% asymptomatic.<br/>- 90% symptoms in male<br/>- 19% with NG has CT +ve</td><td>- Microscopy in symptomatic pts:<br/>- Urethral/ meatal swab/ Rectal<br/>- Phalangeal swabs NR<br/>NAAT ideal.<br/>- 1st pass urine<br/>- Swabs (Rectal, Phalangeal, VVS)<br/>Culture all pts<br/>- purpose to check susceptibility</td><td>- Ceftriaxone 1g I/M stat if susceptibility unknown or<br/>- Cipro 500mg p/o x stat if susceptibility known (36% are resistant to Cipro).</td><td>*Cefixime 400mg + azthro 2g stat or<br/>*Gentamycin 240mg I/M + azthro 2g p/o stet<br/>or<br/>*Spectinomycin I/M + Azthro 2g p/o</td><td>&nbsp;</td><td>*All pts *culture after 72 hours of completion of t/m.</td><td>Recommended<br/>- Asymptomatic +ve NG or infection of other sites.<br/>3m0 all partners.<br/>- Symptomatic urethral NG<br/>All partners within 2 weeks</td><td><strong>*</strong><strong>Conjunctivitis</strong> – 1g ceftriaxone<br/><strong>*</strong><strong>Dis</strong><strong>s</strong><strong>eminated</strong> 1g I/M, I/V <strong>ceftriaxo</strong><strong>ne</strong><strong> </strong>24 hourly.<br/>Or<br/><strong>Cefo</strong><strong>taxime</strong> 1g -8 hourly I/V. or<br/><strong>Cipro</strong>500mg I/V, B.D<br/><strong>Spectino</strong><strong>mycin</strong><strong> </strong>2g I/M B.D<br/><strong>*</strong><strong>Pregnancy </strong>Cipro avoid<br/>*<strong>HIV</strong> same t/m<br/>*<strong>NG + CT</strong> if <strong>azthro</strong> taken before then only NG t/m.</td></tr><tr><td><strong>chlamydia </strong><strong>Trachomatis</strong><br/>20 – 40age.<br/>- No Urinary symptoms.<br/>-Neonatal conjunctivitis &gt;5days.<br/>- Acute cervicitis.</td><td>15 – 19y = 1.5 – 4.3%<br/>50% resolve spontaneously over 12m0.<br/><strong>Rectal</strong> 3 – 50% in MSM 70% in heterosexual.<br/><strong>Phalangeal</strong> 0.5 – 2.3% MSM<br/><strong>SARA</strong> 1%<br/><strong>PID</strong> 16%<br/><strong>Subfertility </strong>1 – 20% after PID<br/><strong>Periportal </strong><strong>Adhesions</strong><br/>5 – 10%.<br/><strong>Co – infections</strong> with Mycoplasma 3 – 15%.<br/>- 54% resolve spontaneously after 1yr.</td><td><strong>NAAT</strong><br/>- VVS in women.<br/>- FCU in men.<br/>- Rectal swab.<br/>- <strong>LG V Testing</strong><br/>- All pts with proctitis.<br/>- HIV + MSM without proctitis but positive CT.</td><td><strong>Uncomplicated</strong><br/>Doxycycline 100mg B.D – 7D.<br/>Or<br/>Azthro 2g stat<br/><strong>Rectal </strong><br/>Doxycycline</td><td><strong>Genital</strong><br/>Erythromycin 500 BD for 10 – 14D<br/>Or<br/>Ofloxacin 200mg BD<br/>Or<br/>Ofloxacin 400 OD<br/><strong>Rectal </strong>Azithromycin.</td><td>*2 – 5m0 after previous infection * so repeat testing 3m0 after t/m.</td><td><strong>NR</strong><strong> = </strong>Routinely *<strong>recommended</strong><br/>*Pregnancy 6 weeks.<br/>*Symptoms persists<br/>Swabs and PCR<br/>CT Persists for 3 – 5weeks so TOC NR routinely.</td><td>ALL</td><td><strong>*</strong><strong>HIV</strong> +ve<br/>Genital &amp; pharyngeal CT same as HIV –ve.<br/><strong>*</strong><strong>HIV +ve</strong><br/>Rectal CT<br/>Test LGV<br/>Not doneNot doneNot doneNot done<br/>Not done<br/>Not done<br/>+ve<br/>Doxi 3 wks<br/><strong>*</strong><strong>Pregnancy</strong><br/>Azthro, Erythro Ampicillin<br/><strong>NG + CT</strong><br/>ceftriaxone 500 I/M + Azthro 1g.<br/><strong>NG + Rectel CT</strong> – ceftriaxone + Doxi + Azthro.<br/><strong>Neonatal CT</strong><br/>5-12D oral Erythro</td></tr></tbody></table>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-003', 'chap-mm-05-01', '3.PID', 'Detailed medical reference and study guide on 3.PID.', 3, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-93e1de29', 't-mm-05-003', 'html', '<h3><strong>includes:</strong></h3>
<ul><li>Endometritis</li><li>Salpingitis</li><li>Oophoritis</li><li>Tubo – ovarian abscess</li><li>Pelvic peritonitis.</li></ul>
<h3><strong>D/D:</strong></h3>
<ul><li>UTI</li><li>Ectopic</li><li>Ovarian cyst complications.</li><li>Appendicitis</li><li>Functional pain</li><li>Endometriosis</li></ul>
<h3><strong>C</strong><strong>ausative</strong><strong> Agents:</strong></h3>
<ul><li>3% gonococcal</li><li>14 – 35% CT¼ of PiD in UK</li><li>4 – 6 weeks after IUCD</li></ul>
<h3><strong>Others:</strong></h3>
<ul><li>Gardnella</li><li>Anaerobes</li><li>Mycoplasma – emerging agent.</li></ul>
<h3><strong>Symptoms:</strong></h3>
<ul><li>Lower abdominal pain</li><li>Deep dyspareunia</li><li>AUB</li><li>IMB</li><li>PCB</li><li>Menorrhagia.</li><li>Abnormal discharge</li></ul>
<h3><strong>Signs:</strong></h3>
<ul><li>B/L tenderness in lower abdomen</li><li>Adnexal tenderness</li><li>Cervical motion tenderness</li><li>Fever &gt; 380 C.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Clinical S/S =&gt; PPV 65 – 90%</li><li>Elevated ESR, CRP</li><li>Testing for NG &amp; CT.</li><li>Absence of PUS cells on endo cervical &amp; vaginal swabs =&gt; Good NPV 95% but presence has PPV of 17%.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Don’t delay – risk of complication</li><li>Subfertility</li><li>Ectopic</li><li>CPP</li><li>Fitz hugh Curtis syndrome</li><li>Empirical treatment.</li><li>Rest</li><li>Analgesia</li><li>Avoid intercourse till they &amp; their partners have completed treatment.</li><li>Partner screening is recommended</li><li>OCP + Break through bleeding =&gt; STI screening esp CT.</li><li>UPT =&gt; Offer</li><li>Screening for STI including HIV =&gt; offer</li></ul>
<h3><strong>Out Patient Treatment (Mild – Mod</strong><strong>erate</strong><strong>):</strong></h3>
<ul><li>Ceftriaxone 1g stat IM</li><li>[14 DAYS][14 DAYS][14 DAYS][14 DAYS]+ Doxi 100mg</li><li>+ Flagyl 400 B.D</li><li>[14 DAYS][14 DAYS][14 DAYS][14 DAYS]Ofloxacin 400 B.D</li><li>+ metronidazole</li><li>Ceftriaxone 1g stat I/M</li><li>+ Azthro 1g/weeks. [14 DAYS]</li><li>Oral Moxi 400 OD – [14 DAYS]</li><li>M-Genitalium = moxifloxacin</li><li>Pregnancy, B.F – parental therapy.</li><li>Severe PID – Consider anaerobes</li><li>Quinolones – avoided in Gonococcal PID due to     ing resistance.</li><li>Don’t use Quinolones as 1st line</li><li>I/V in inpatient regimens should be continued 24 hours after clinical improvement.</li><li><em><strong>Partner</strong></em><em><strong> treatment:</strong></em><em><strong> </strong></em></li><li>Azthro 1g – single dose.</li><li>Screening in 6m0 duration</li><li>Avoid sexual intercourse until index pt have completed treatment course.</li></ul>
<h3><strong>TOC:</strong></h3>
<ul><li>2 – 4 weeks.</li><li>CT – not routinely if indicated then after 3 – 5weeks.</li></ul>
<h3><strong>In – Patient:</strong></h3>
<ul><li>Surgical Emergency can’t be excluded.</li><li>No response to therapy</li><li>Severe disease</li><li>To Abscess</li><li>Intolerance to oral treatment</li><li>Pregnancy</li><li>Ceftriaxone 2g daily I/v + Doxi B.D.</li><li>Followed by</li><li>Doxi B.D</li><li>[14 DAYS][14 DAYS][14 DAYS][14 DAYS]+ Metronidazole B.D</li><li>Clinda 90mg TDS</li><li>+ Gentamycin 2mg/kg loading dose then 1.5mg/kg 1day – TDS</li><li>F.B</li><li>[14 DAYS][14 DAYS][14 DAYS][14 DAYS]Oral clinda 45mg QDS or</li><li>Doxi 10mg B.D</li><li>+ Metronidazole</li><li>Gentamycin levels should be monitored.</li><li>I/V ofloxacin 400mg B.D + I/V</li><li>Metronidazole 500mg TDS – 14days</li><li>Cipro 200 B.D + Doxi + Metronidazole TID = 14 days.</li></ul>
<h3><strong>Surgical management:</strong></h3>
<ul><li>Laparoscopy – divide adhesions &amp; drainage of pelvic abscess.</li><li>USG Guided aspiration of fluid collection is less invasive but equally effective.</li><li>Adhesiolysis in Perihepatitis.</li></ul>
<h3><strong>Follow Up:</strong></h3>
<ul><li>72 hours in moderate – severe.</li><li>Further review 2 – 4 weeks.</li><li>Persistent symptoms, consider</li><li>I/V antibiotics</li><li>Rule out resistance.</li><li>Recurrent infection.</li><li>Repeat testing for N.G &amp; CT after 2 – 4 weeks.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
