INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3a0738fa', 't-mm-05-004', 'html', '<table><tbody><tr><td><strong>Condition</strong></td><td><strong>Causative Agent</strong></td><td><strong>Clinical features</strong></td><td><strong>Diagnosis</strong></td><td><strong>Treatment</strong></td><td><strong>Partner</strong><strong> tracing and Treatment</strong></td><td><strong>TOC</strong></td><td><strong>Follow up</strong></td></tr><tr><td>Donovanosis<br/>20 – 40years<br/>More in India<br/>Ing over all</td><td>Klebsiella<br/>Granulomatous</td><td>- Papules<br/>- S/C nodules that ulcerate.</td><td><strong>Direct </strong><strong>Microscopy</strong><br/>Rapid Giemsa<br/><strong>Histology</strong><br/>Donnovan bodies<br/><strong>PCR</strong></td><td>- Azithro 1g weekly<br/>- Co – trimoxazole<br/>- Doxi<br/>- Erythromycin<br/><strong>Children </strong>Azithromycin<br/><strong>Pregnancy </strong>Erythromycin</td><td>All in 6m0</td><td>&nbsp;</td><td>Till lesions heals</td></tr><tr><td>Lymphogranuloma<br/>venereum<br/>LGV</td><td>CT L1 – L3<br/>L2 commonest</td><td>- 95% Asymptomatic.<br/>- <strong>Painless</strong> papules, pustules, shallow ulcers.<br/>- Hemorrhagic proctitis<br/>- pharyngeal LGV.<br/>- <strong>Painful</strong> lymphadenopathy, lymphadenitis (painful + Tender unilateral)</td><td><strong>NAAT</strong>:<br/>- Ulcer base<br/>- Rectal swabs.<br/>- Urethral swab</td><td>Doxi Erythro</td><td>Within weeks? Before onset of symptoms</td><td>Not required routinely</td><td>&nbsp;</td></tr><tr><td>Chancroid</td><td>H Ducreyi</td><td><strong>Painful</strong> ulcers<br/>Bubo formations<br/><strong>Painful</strong> lymphadenopathy</td><td>NAAT<br/>Ulcer base</td><td>Azithromycin<br/>Ceftriaxone<br/>Ciprofloxacin</td><td>All partners within 10 days before symptoms</td><td>Not required</td><td>&nbsp;</td></tr><tr><td>Syphilis</td><td>&nbsp;</td><td><strong>Painless</strong> ulcers<br/><strong>Painless</strong> lymphadenopathy</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
