INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7fdbac29', 't-mm-05-007', 'html', '<table><tbody><tr><td><strong>Postpartum</strong> (in breastfeeding or non-breastfeeding women, including post-caesarean section)</td><td>&nbsp;</td></tr><tr><td>a) 0 to 48 hours</td><td>1</td><td>1</td><td>See above</td></tr><tr><td>b) 48 hours to &lt;4 weeks</td><td>3</td><td>3</td><td>&nbsp;</td></tr><tr><td>c) 24 weeks</td><td>1</td><td>1</td><td>&nbsp;</td></tr><tr><td>d) Postpartum sepsis</td><td>4</td><td>4</td><td>&nbsp;</td></tr><tr><td><strong>Post-abortion </strong></td><td>&nbsp;</td></tr><tr><td>a) First trimester</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) Second trimester</td><td>2</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>c) Post-abortion sepsis</td><td>4</td><td>4</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td><strong>Past ectopic pregnancy </strong></td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>History of<strong> pelvic surgery </strong></td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td><strong>Smoking </strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>a) Age &lt;35 years</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Age ≥35 years</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>(i) &lt;15 cigarettes/day</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>(ii) ≥15 cigarettes/day</td><td>&nbsp;</td><td>1</td><td>1</td><td>1</td><td>1</td><td>4</td></tr><tr><td>(iii) Stopped smoking &lt;1 year</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>(iv) Stopped smoking 21 year</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td><strong>Obesity</strong></td><td>&nbsp;</td><td>&nbsp;</td><t