INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e045bccb', 't-mm-05-007', 'html', '<table><tbody><tr><td><strong>Organ transplant </strong></td><td>&nbsp;</td></tr><tr><td>a) Complicated: graft failure (acute or chronic), rejection, cardiac allograft vasculopathy</td><td>I</td><td>C</td><td>I</td><td>C</td><td>2</td><td>2</td><td>2</td><td>3</td></tr><tr><td>&nbsp;</td><td>3</td><td>2</td><td>3</td><td>2</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>b) Uncomplicated</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td><strong>CARDIOVASCULAR DISEASE (CVD) </strong></td></tr><tr><td><strong>Multiple risk factors for CVD</strong> (such as smoking, diabetes, hypertension, obesity and dyslipidemias)</td><td>1</td><td>2</td><td>2</td><td>3</td><td>2</td><td>3</td></tr><tr><td><strong>Hypertension</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>a) </strong>adequately controlled hypertension</td><td>1</td><td>1</td><td>1</td><td>2</td><td>1</td><td>3</td></tr><tr><td><strong>b) </strong>Consistently elevated BP levels (properly taken measurements)</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>(i) </strong>Systolic &gt;140-159 mmHg or diastolic &gt;90-99 mmHg</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td><strong>(ii)</strong>Systolic &gt; 160 mmHg or diastolic &gt;100</td><td>1</td><td>1</td><td>1</td><td>2</td><td>1</td><td>4</td></tr><tr><td><strong>c) </strong>Vascular Disease</td><td>1</td><td>2</td><td>2</td><td>3</td><td>2</td><td>4</td></tr><tr><td>History of high BP during pregnancy</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr></tbody></table>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d49d52ed', 't-mm-05-007', 'html', '<table><tbody><tr><td>Current and history of ischemic heart disease</td><td>1</td><td>I</td><td>C</td><td>I</td><td>C</td><td>3</td><td>I</td><td>C</td><td>4</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>2</td><td>3</td><td>2</td><td>3</td><td>&nbsp;</td><td>2</td><td>3</td><td>&nbsp;</td></tr><tr><td>Stroke (history of cerebrovascular accident, including TIA)</td><td>1</td><td>I</td><td>C</td><td>I</td><td>C</td><td>3</td><td>I</td><td>C</td><td>4</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>2</td><td>3</td><td>2</td><td>3</td><td>&nbsp;</td><td>2</td><td>3</td><td>&nbsp;</td></tr><tr><td>Known dyslipidemias</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td><strong>Venous thromboembolism (VTE)</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>a) History of VTE</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>b) Current VTE (on anticoagulants)</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>c) Family history of VTE</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>(1) First-degree relative age &lt;45 years</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>(2) First-degree relative age ≥ 245 years</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>d) Major surgery</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>(1) With prolonged immobilization</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>(ii) Without prolonged immobilization</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>e) Minor surgery without immobilization</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>f) Immobility (unrelated to surgery) (e.g wheelchair use, debilitating illness)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>Superficial venous thrombosis</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>a) Varicose veins</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) Superficial venous thrombosis</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Known thrombogenic mutations e.g factor V Leiden, prothrombin mutation, protein s. protein C and the antithrombin deficiencies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td><strong>Valvular and congenital heart disease</strong></td></tr><tr><td>a) Uncomplicated</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Complicated (e.g. pulmonary hypertension, history of subacute bacterial endocarditis)</td><td>2</td><td>2</td><td>1</td><td>1</td><td>1</td><td>4</td></tr><tr><td><strong>Cardiomyopathy </strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>a) Normal cardiac function</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Impaired cardiac function</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td><strong>Cardiac arrhythmias</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>a) </strong>Atrial fibrillation</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td><strong>b) </strong>Known long QT syndrome</td><td>I</td><td>C</td><td>I</td><td>3</td><td>1</td><td>2</td><td>1</td><td>2</td></tr><tr><td>&nbsp;</td><td>3</td><td>1</td><td>3</td><td>1</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>NEUROLOGICAL CONDITIONS:</strong></td></tr><tr><td><strong>HEADACHES</stro