S(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-60675b74', 't-mm-05-007', 'html', '<table><tbody><tr><td>b) Carrier</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>c) Chronic</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>Cirrhosis</td><td>&nbsp;</td></tr><tr><td>a) Mild (compensated without complications)</td><td>4</td><td>4</td><td>4</td><td>4</td><td>4</td><td>4</td></tr><tr><td>b) Severe (decompensated)</td><td>1</td><td>3</td><td>3</td><td>3</td><td>3</td><td>4</td></tr><tr><td><strong>Inflammatory bowel disease (including Crohn\'s disease and ulcerative colitis) </strong></td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td></tr><tr><td><strong>ANAEMIAS </strong></td><td>&nbsp;</td></tr><tr><td>Thalassemia</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>Sickle cell disease</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Iron deficiency anemia</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td><strong>RHEUMATIC DISEASES </strong></td><td>&nbsp;</td></tr><tr><td>Rheumatoid arthritis</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>Systemic lupus erythematosus (SLE)</td><td>&nbsp;</td></tr><tr><td>a) No antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>b) Positive antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>Positive antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr></tbody></table>', 19) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
