INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ca8711d1', 't-mm-05-008', 'html', '<table><tbody><tr><td><strong>Method</strong></td><td><strong>Typical use (%) (estimated)</strong></td><td><strong>Perfect use (%)</strong></td></tr><tr><td>No method</td><td>85</td><td>85</td></tr><tr><td>Fertility awareness-based methods</td><td>24</td><td>0.4-5</td></tr><tr><td>Female diaphragm</td><td>12</td><td>6</td></tr><tr><td>Male condom</td><td>18</td><td>2</td></tr><tr><td>Combined hormonal contraception"</td><td>9</td><td>0.3</td></tr><tr><td>Progestogen-only pill</td><td>9</td><td>0.3</td></tr><tr><td>Progestogen-only injectable</td><td>6</td><td>0.2</td></tr><tr><td>Copper intrauterine device</td><td>0.8</td><td>0.6</td></tr><tr><td>Levonorgestrel intrauterine system</td><td>0.2</td><td>0.2</td></tr><tr><td>Progestogen-only implant</td><td>0.05</td><td>0.05</td></tr><tr><td>Female sterilization</td><td>0.5</td><td>0.5</td></tr><tr><td>Vasectomy</td><td>0.15</td><td>0.1</td></tr></tbody></table>', 15) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-74c6899b', 't-mm-05-008', 'html', '<h3><strong>Women using combined hormonal contraception: key indications for medical review </strong></h3>
<h3><strong>Key symptoms that should prompt women to seek urgent medical review </strong></h3>
<ul><li>Calf pain, swelling and/or redness</li><li>Chest pain and/or breathlessness and/or coughing up blood</li><li>Loss of motor or sensory function</li></ul>
<h3><strong>Key symptoms that should prompt women to seek medical review </strong></h3>
<ul><li>Breast lump, unilateral nipple discharge, new nipple inversion, change in breast skin</li><li>New onset migraine</li><li>New onset sensory or motor symptoms in the hour preceding onset of migraine</li><li>Persistent unscheduled vaginal bleeding</li></ul>
<h3><strong>New medical diagnoses that should prompt women to seek advice from their contraceptive provider (and review of the suitability of CHC) </strong></h3>
<ul><li>High blood pressure</li><li>High body mass index (&gt;35 kg/m²)</li><li>Migraine or migraine with aura</li><li>Deep vein thrombosis or pulmonary embolism</li><li>Blood clotting abnormality</li><li>Antiphospholipid antibodies</li><li>Angina, heart attack, stroke or peripheral vascular disease</li><li>Atrial fibrillation</li><li>Cardiomyopathy</li><li>Breast cancer or breast cancer gene mutation</li><li>Liver tumor</li><li>Symptomatic gallstones</li><li>If two or more Pills have been missed (&gt; 72 hours since last pill is current packet of &gt; 48 hours late starting first pill in new packet)If two or more Pills have been missed (&gt; 72 hours since last pill is current packet of &gt; 48 hours late starting first pill in new packet)If two or more Pills have been missed (&gt; 72 hours since last pill is current packet of &gt; 48 hours late starting first pill in new packet)If two or more Pills have been missed (&gt; 72 hours since last pill is current packet of &gt; 48 hours late starting first pill in new packet)<strong>Missed pill Guidelines:</strong><strong>IF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packetIF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packet</strong>IF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packetIF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packet</li><li><strong>Continuing contraceptive coverThe most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.Continuing contraceptive coverThe most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.</strong><strong>Continuing contraceptive cover</strong>The most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.<strong>Continuing contraceptive cover</strong>The most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.<strong>Continuing contraceptive cover:The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.Continuing contraceptive cover:The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.</strong><strong>Continuing contraceptive cover:</strong>The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.<strong>Continuing contraceptive cover:</strong>The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.</li><li><strong>Minimizing risk of pregnancyEmergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.Minimizing risk of pregnancyEmergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.</strong><strong>Minimizing risk of pregnancy</strong>Emergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.<strong>Minimizing risk of pregnancy</strong>Emergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.</li><li><strong>Minimizing The risk of pregnancyIf pills are missed in the first week (Pills 1-7)EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.if pills are missed the second week (pills 8 – 14)No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. if pills are missed in the third week (pills 15 – 21)OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.Minimizing The risk of pregnancyIf pills are missed in the first week (Pills 1-7)EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.if pills are missed the second week (pills 8 – 14)No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. if pills are missed in the third week (pills 15 – 21)OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.</strong><strong>Minimizing The risk of pregnancy</strong><strong>If pills are missed in the first week (Pills 1-7)</strong>EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.<strong>if pills are missed the second week (pills 8 – 14)</strong>No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. <strong>if pills are missed in the third week (pills 15 – 21)</strong>OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.<strong>Minimizing The risk of pregnancy</strong><strong>If pills are missed in the first week (Pills 1-7)</strong>EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.<strong>if pills are missed the second week (pills 8 – 14)</strong>No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. <strong>if pills are missed in the third week (pills 15 – 21)</strong>OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.</li><li><em><strong>1st week</strong></em> missed - EC + additional precautions</li><li><em><strong>2nd week</strong></em> only additional precautions</li><li><em><strong>3rd week</strong></em> – skip pill free interval</li></ul>', 16) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-009', 'chap-mm-05-01', '11.PROGESTOGEN-ONLY PILL', 'Detailed medical reference and study guide on 11.PROGESTOGEN-ONLY PILL.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5a62410d', 't-mm-05-009', 'html', '<ul><li>This guideline will consider POPs available in the UK. namely Desogestrel (DSG) 75 kg, Drosperinone (DRSP) 4 mg (soon to be available in the UK) and the ‘traditional’ POPs levonorgestrel| (LNG) 30 pg and norethisterone (NET) 350 ug</li><li><strong>MOA:</strong> DSG and DRSP POPs: inhibition of ovulation</li><li>LNG and NET POPs: changes on cervical mucus, endometrium and tubal motility</li><li>A 12-month supply of traditional, DSG or DRSP POP can be provided with an annual review.</li><li>Specific approved brands of DSG POP can now be bought from a pharmacy, without a prescription, under the supervision of a pharmacist.</li><li>LNG, NET and DSG POPs are taken continuously at 24-hour intervals without an HFI.</li><li>The new DRSP POP is taken in a regimen of 24 daily active pills followed by four hormone-free placebo pills (to establish a more predictable bleeding pattern)</li><li>Use of all POPs taken between menarche and age 55 years.</li><li><em><strong>DRSP POP</strong></em><em><strong> should also generally be </strong></em><em><strong>avoided in</strong></em><em><strong>:</strong></em></li><li>Severe renal insufficiency or acute renal failure.</li><li>Individuals with known hyperkaliemia or untreated hyperaldosteronism (e.g., Addison\'s disease).</li><li>Individuals currently using potassium-sparing diuretics, aldosterone antagonists or potassium supplements.</li></ul>
<p><em><strong>DRSP POP</strong></em><em><strong> used with caution by</strong></em><strong> </strong>individuals with mild/moderate renal impairment or treated hyperaldosteronism (e.g., treated Addison\'s disease)</p>
<ul><li>Individuals with significant risk factors for chronic kidney disease: measurement of urea &amp; electrolytes (U&amp;E) and blood pressure considered prior to prescription of the DRSP POP, <em><strong>particularly if age over 50 years</strong></em></li><li><strong>Side effects</strong>: Change in bleeding pattern over a 3-month period ending at about 12 months of use (at around 6—9 months of use with DRSP POP)</li><li><strong>Interactions:</strong> contraceptive effectiveness of all POPs could be reduced during use of the enzyme-inducer and for 28 days after stopping the enzyme-inducer.</li><li>Ability of UPA-EC as an EC can be reduced if a POP has been taken in the preceding 7 days or within 5 days of taking the UPA. Offer them DMPA. the Cu-lUD or the LNG-IUS</li><li>Interactions between DRSP POP and drugs such as ACEi and ARBs could also potentially increase risk of hyperkaliemia</li><li><strong>Non-contraceptive benefits:</strong></li><li>DSG and DRSP POP could reduce dysmenorrhea for some users</li><li>DRSP POP might theoretically offer benefit for acne or hirsutism</li></ul>
<p>Induction of withdrawal bleeding is not required in individuals with PCOS during use of a POP even if they are amenorrhea.</p>
<h3><strong>AC: additional contraception like barrier or abstinence</strong></h3>
<ul><li>DRSP POP is started on day 1 of a natural menstrual cycle, day 1 after abortion or by day 21 after childbirth. If started at any other time, quick start+ AC for 7 days+ consider EC and follow-up pregnancy test</li><li>LNG, NET and DSG POPs can be started on days 1—5 of a natural menstrual cycle, by day 5 after abortion or by day 21 after childbirth. At any other time. quick start +AC for 2 days+ consider EC and follow-up pregnancy test if required.</li><li>(UPSI from the time that the first pill was missed until correct pill taking had resumed for 48 hours)</li><li>DRSP POP if taken 24hrs late recent pill + next pill at usual time+ AC for 7days+ consider EC</li><li>(OMIT THE HFI (PLACEBO PILLS) IF ANY OF THE LAST 7 ACTIVE PILLS ARE MISSED)</li></ul>
<h3><strong>Vomiting after the progestogen-only pill is taken</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b82769b1', 't-mm-05-009', 'html', '<table><tbody><tr><td><strong>Type of POP</strong></td><td><strong>Manufacturer-recommended time after pill-taking until unaffected by</strong><br/><strong>vomiting</strong></td></tr><tr><td>DRSP POP</td><td>3-4 hours</td></tr><tr><td>LNG traditional POP</td><td>2 hours</td></tr><tr><td>NET traditional POP</td><td>Not stated. GDG su est 2 hours as above</td></tr><tr><td>DSG POP</td><td>hours</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-86dc86e1', 't-mm-05-009', 'html', '<ul><li>POPs are taken daily with no pill-free interval.</li><li>taken at or around the same POPs currently available in the UK contain either NET 350 pg (Micronor, Noriday), LNG 30 pg (Norgeston@) or DSG 75 pg (Cerazetto)</li><li><strong>Mode of action:</strong></li><li>POPs increase volume &amp; viscosity of cervical mucus preventing sperm penetration into upper reproductive tract. Can also act to suppress ovulation.</li><li><strong>Efficacy:</strong></li><li>If used consistently and correctly, POPs are more than 99% effective.</li><li><strong>Drug interactions:</strong></li><li>POP users taking enzyme-inducing drugs should be advised to switch to the progestogen-only injectable or intrauterine contraception.</li><li>For short durations of enzyme-inducing treatment (&lt;2 months) women can continue the POP providing they use additional precautions</li><li>Women wishing to start the POP after stopping enzyme-inducing drugs should be advised dafter the last dose of enzyme-inducing drug.</li><li><strong>Missed Pill </strong><strong>Guideline</strong><strong>:</strong></li></ul>
<h3><strong>TRADITIONAL POPS                     </strong><strong>DESOGESTREL POPS      </strong></h3>
<ul><li>3 hours late &gt;12 hours late</li></ul>
<p>(&gt;27 hours since the last pill was taken) (&gt;36 hours since the last pill was taken)</p>
<ul><li>The missed pill should be taken as soon as remembered. If more than one pill has been missed, only one pill should be taken.</li><li>The next pill should be taken at the usual time. This may mean that two pills are taken in 1 day.</li><li>Additional contraceptive precautions (condoms or avoidance of sex) are advised for 2 days (48 hours) after restarting the POP.</li><li>Emergency contraception is indicated if unprotected sexual intercourse occurred after the missed pill and within 48 hours of restarting the POP.</li><li><strong>Raised BMI and POP:</strong></li><li>NO increased risk of pregnancy in POP users with a heavier body weight or a higher BMI and insufficient evidence to support a dose of more than one pill per day in women who are heavy or overweight.</li><li><strong>Non-contraceptive benefits: </strong></li><li><strong>Dysmenorrhea: DSG </strong></li><li><strong>Ectopic pregnancy</strong>: While the overall risk of pregnancy is reduced with use of traditional POPs, around 1 in 10 pregnancies that do occur may be ectopic.</li><li><strong>Headaches and Ovarian cysts/persistent ovarian follicles:</strong> No good evidence was identified.</li><li><strong>Return of fertility:</strong> There is no evidence suggesting a delay in return of fertility following discontinuation of a POP; therefore, if pregnancy is not desired, other contraceptive methods should be used immediately following discontinuation of the POP.</li><li><strong>Side effects:</strong></li><li><strong>Bleeding:</strong> Changes in bleeding patterns associated with the POP are common.</li><li><strong>Libido:</strong> Effects of POP on libido are lacking and therefore a possible effect cannot be excluded.</li><li><strong>Weight change:</strong> Evidence does not support a casual association between POP use and weight change.</li><li>Women may be given up to a 12-month supply of POPs at their first and follow-up visits and advised to return at any time if problems arise.</li><li>The POP can be used until the age of 55 years when natural loss of fertility can be assumed for most women.</li></ul>
<p>If they are aged &gt; 50 years and amenorrhea they can continue using a POP and have FSH concentrations tested on two occasions 6 weeks apart. If both FSH measurements are &gt;30 IU/I this is</p>
<ul><li>suggestive of ovarian failure and they should continue with a POP or barrier method for one further year.\'</li><li><strong>Recommendations following incorrect progestogen-only pill use </strong></li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-167cb285', 't-mm-05-009', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>Traditional POP</strong></td><td><strong>DSG POP</strong></td><td><strong>DRSP POP </strong></td></tr><tr><td>When is a pill missed?</td><td>A pill is missed if taken 3 hours late (27 hours after last pill taken)</td><td>A pill is missed if taken 12 hours last (36 hours after les pill</td><td>A pill is missed if taken 24 hours late 48 hours after last pill was taken or 24 hours after a new packet should have been started after an HFI</td></tr><tr><td>Action if pill(s) missed</td><td>Take the most recent missed pill as soon as possible<br/>Take the next pill at the usual time (this may mean taking two pills in 1 day)<br/>Use additional contraceptive precautions (eg, condoms) for 48 hours after correct pill-taking has restarted<br/>Consider EC</td><td>&nbsp;</td><td>Take the most recent missed pill as soon as possible<br/>Take the next bill at the usual time (this may mean taking two pills in 1 day)<br/>Use additional contraceptive precautions (eg, condoms) for 7 days after correct pill-taking has restarted<br/>Consider EC<br/><strong>OMIT THE HFI (PLACEBO PILLS) IF ANY OF THE LAST 7 ACTIVE PILLS ARE MISSED </strong></td></tr><tr><td>Is EC required?</td><td>EC should be considered if there was UPSI from the site that the first pill was missed until correct pill taking had resumed for 48 hours</td><td>&nbsp;</td><td>EC should be considered if<br/>Any active pill(s) were missed and there was UPSI from the time that the first pill was missed until correct pill-taking had resumed for 7 days<br/>Pills were missed on days 1-7 of the packet and there was UPSI during the HFI or week 1</td></tr><tr><td>Follow-up</td><td>Consider pregnancy test 21 days after last UPSI</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2728798e', 't-mm-05-009', 'html', '<p>Table 21. Recommendations following incorrect progestogen-only pill use</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-010', 'chap-mm-05-01', '11. PROGESTOGEN-ONLY INJECTABLE CONTRACEPTION', 'Detailed medical reference and study guide on 11. PROGESTOGEN-ONLY INJECTABLE CONTRACEPTION.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5f4aa0f4', 't-mm-05-010', 'html', '<p><strong>▪ Long-acting reversible contraceptives (LARCs)</strong> are those that are administered less frequently than once a month.</p>
<ul><li>DMPA (Depot Medroxyprogesterone Acetate) and NET-EN (Norethisterone Enanthate) are long-acting progestogens.</li><li>DMPA:</li><li>Administered via intramuscular (IM) injection:</li><li>Depo-Provera: 150 mg medroxyprogesterone acetate in 1 ml.</li><li>Also available as a subcutaneous (SC) injection:</li></ul>
<p>Sayana Press: 104 mg MPA in 0.65 ml</p>
<ul><li>NET-EN:</li><li>Less commonly used in the UK.</li><li>Given as Noristerat®: 200 mg in 1 ml via IM injection.</li><li>Licensed for short-term use, such as:</li><li>When a partner has undergone vasectomy (until successful vasectomy is confirmed).</li><li>After rubella immunization.</li><li>The combined contraceptive injectable is not available in the UK.</li><li><strong>Mode of action</strong>: Progestogen-only injectable contraception works primarily by <strong>inhibiting ovulation</strong>. There is also an effect on cervical mucus, resulting in poor cervical mucus scores and limited sperm penetration.</li></ul>
<p><strong>Failure rate</strong>: When administered at the recommended dosing interval the failure rate of progestogen-only injectable contraception is approximately <strong>0.2% in the first year of use</strong>.</p>
<ul><li>With typical use the failure rate is approximately <strong>6%</strong>.</li></ul>
<h3><strong>Non-contraceptive benefits:</strong></h3>
<ul><li>Bleeding and dysmenorrhea:Amenorrhea or reduced bleeding is common in progestogen-only injectable users and may benefit women with menstrual problems. DMPA use may reduce pain associated with endometriosis. Women should be advised about changes in bleeding patterns.</li><li>Ovarian and endometrial cancers:Use of DMPA is not associated with an increased risk of ovarian or endometrial cancer and may offer some protection.</li><li>Sickle cell disease:DMPA is a contraceptive option for women with sickle cell disease and may reduce the severity of sickle crisis pain.</li></ul>
<h3><strong>Health concerns</strong></h3>
<ul><li>Bone mineral density (BMD):Progestogen-only injectable use is associated with a small loss of BMD, which is usually recovered after discontinuation.</li></ul>
<p>In women aged under 18 years, progestogen-only injectable contraception can be used after consideration of alternative methods.</p>
<p>Women are generally advised to switch to another method at age 50 years.</p>
<ul><li>No DMPA before 18years and after 50 years</li><li><em><strong>Breast cancer:</strong></em> There is a weak association between current use of DMPA and breast cancer. Any increased risk is likely to be small and reduce with time after stopping</li><li><em><strong>Cardiovascular health:</strong></em> A causal association between DMPA and venous thrombosis has not been demonstrated.</li><li><em><strong>Cervical cancer:</strong></em> There is a weak association between cervical cancer and use of DMPA for 5 years or longer. Any increased risk appears to reduce with time after stopping and could be due to confounding factors.</li></ul>
<h3><strong>Side effects:</strong></h3>
<ul><li><em><strong>Altered bleeding patterns and Weight gain:</strong></em> Use of DMPA appears to be associated with weight gain, particularly in women under 18 years of age with a BMI &gt;30kg/m2.</li><li><em><strong>Injection site reactions:</strong></em> Injection site reactions appear to be more common with use of SC DMPA than with use of IM DMPA.</li><li><em><strong>Others Effects:</strong></em> Diffuse hair loss (alopecia), Headache, Mood change, Vasomotor symptoms,   Libido and sexual function,</li><li><em><strong>Vaginitis:</strong></em> Whilst there is little evidence available to demonstrate causation, a number of possible side effects such as acne, decreased libido, mood swings, headache, hot flushes and vaginitis have been reported with use of DMPA.</li></ul>
<h3><strong>Site of injection and period</strong>:</h3>
<ul><li>The gluteal muscle is the preferred site for IM DMPA administration but it can be administered into the deltoid muscle of SC DMPA should be injected into the abdomen or anterior thigh.</li><li>Women should be advised to return fora repeat injection of IM or SC DMPA (outside the product license for IM DMPA). An injection of DMPA can be administered up to 7 days late (up to 14 weeks after the last injection) without the need for additional contraceptive</li><li>precautions (outside the product license for IM DMPA).</li><li>The efficacy of DMPA is not reduced with concurrent use of enzyme-inducing drugs.</li><li>No increased risk of pregnancy has been demonstrated in progestogen-only injectable users with higher body weight, although data are limited in women with a BMI &gt;40 kg/m².</li><li>Return of fertility:Women who discontinue their progestogen-only injectable and who do not wish to conceive should be advised to start another contraceptive method before or at the time of their next scheduled injection even if amenorrhoeic.</li></ul>
<p>Women should be informed that there can be a delay of up to 1 year in the return of fertility after discontinuation of IM or SC DMPA.</p>
<ul><li>Sexually transmitted infections and testing:The consistent and correct use of condoms (male or female) can reduce the risk of STI transmission and should therefore be recommended as a risk-reduction strategy.</li><li>Problematic bleeding:</li><li>Women who experience unscheduled bleeding during use of a progestogen-only injectable and who are medically eligible can be offered a COC for 3 months.</li><li>Women with unscheduled bleeding during use of a progestogen-only injectable contraceptive can be offered 500 mg mefenamic acid up to three times daily for 5 days.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-011', 'chap-mm-05-01', '12. PROGESTOGEN-ONLY IMPLANT', 'Detailed medical reference and study guide on 12. PROGESTOGEN-ONLY IMPLANT.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-470797ce', 't-mm-05-011', 'html', '<ul><li>The ENG-IMP is currently the only progestogen-only contraceptive subdermal implant available in the UK.</li><li>The ENG-IMP is a highly effective long-acting reversible method of contraception.</li><li>Licensed for 3 years of use for contraception.</li></ul>
<h3><strong> Effectiveness:</strong></h3>
<ul><li>The first-year contraceptive failure rate for the ENG-IMP has been estimated at 0.05%.</li><li>Routine use of the ENG-IMP for longer than 3 years is not currently recommended.</li></ul>
<h3><strong> Drugs Interactions:</strong></h3>
<ul><li>Women using enzyme-inducing drugs should be informed that the contraceptive effectiveness of the ENG-IMP could be reduced during use of the enzyme-inducer and for 28 days after stopping the enzyme-inducer.</li><li>Women using enzyme-inducing drugs should be offered a reliable contraceptive method that is unaffected by enzyme-inducers.</li></ul>
<h3><strong>Weight/BMI</strong></h3>
<ul><li>The available evidence suggests that contraceptive effectiveness of ENG is not affected by body weight or BMI</li></ul>
<h3><strong> Ulipristal acetate (UPA):</strong></h3>
<ul><li>The ability of UPA-EC to delay ovulation could be reduced if an ENG-IMP is inserted within 5 days of taking the UPA.</li><li>The ability of UPA-EC to delay ovulation could theoretically be reduced if a woman has an ENG-IMP in situ (even if it has been in situ for longer than 3 years).</li><li>Individuals should be advised to wait 5 days after taking UPA-EC before insertion of the ENG-IMP.</li></ul>
<p>They should be made aware that they must use condoms reliably or abstain from sex during the 5 days waiting and then for 7 days after implant insertion.</p>
<h3><strong> Suitability of the etonogestrel implant:</strong></h3>
<ul><li>Breast cancer, arterial thromboembolism, decompensated cirrhosis, hepatocellular tumors and unexplained vaginal bleeding are UKMEC 3 or 4</li></ul>
<h3><strong> Medical conditions that are UKMEC3 or UKMEC4 for use of the etonogestrel subdermal implant</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-312d0aba', 't-mm-05-011', 'html', '<table><tbody><tr><td><strong>Condition</strong></td><td><strong>UKMEC category for use of etonogestrel subdermal implant</strong></td></tr><tr><td>Current and history of ischemic heart disease</td><td>UKMEC3 for continuation (UKMEC2 for initiation)</td></tr><tr><td>History of stroke</td><td>UKMEC3 for continuation (UKMEC2 for initiation)</td></tr><tr><td>Unexplained vaginal bleeding (before evaluation)</td><td>UKMEC3</td></tr><tr><td>Current breast cancer</td><td>UKMEC4</td></tr><tr><td>Past breast cancer</td><td>UKMEC3</td></tr><tr><td>Severe (decompensated) cirrhosis</td><td>UKMEC3</td></tr><tr><td>Hepatocellular adenoma or carcinoma</td><td>UKMEC3</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-26dd3d86', 't-mm-05-011', 'html', '<ul><li><strong>Dysmenorrhea</strong></li><li><strong>Heavy menstrual bleeding</strong></li><li><strong>Endometriosis:</strong> Limited available evidence suggests that use of the ENG-IMP could be associated with improvement in endometriosis- associated pain</li><li><strong>Endometrial protection in polycystic ovary syndrome</strong>: Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic</li></ul>
<p>ovary syndrome who are amenorrhoeic during the licensed duration of use of the ENG-IMP</p>
<h3><strong>Risk of adverse health events</strong></h3>
<ul><li>Venous and arterial thromboembolism:Evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.</li><li>Osteoporosis:Evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in bone mineral density (BMD).</li><li>Breast cancer:No significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.</li><li>Gynecological cancer:The available evidence is too limited to inform whether an association exists between use of the ENG-IMP and risk of ovarian, endometrial, or cervical cancer.</li><li>Ectopic pregnancy:Risk of ectopic pregnancy during use of the ENG-IMP is extremely small.</li></ul>
<h3><strong>Side Effects</strong></h3>
<ul><li>Irregular, unpredictable bleeding is common during use of the ENG-IMP.</li><li>Bleeding pattern may change at any time during use of an ENG-IMP.</li><li>Individuals with ‘unfavorable’ bleeding patterns in the first few months after ENG-IMP insertion may have about a 50% chance that bleeding will improve over time.</li><li>Endometrial protection in polycystic ovary syndrome:Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic ovary syndrome who are amenorrhoeic during licensed duration of use of ENG-IMP.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-efe7f598', 't-mm-05-011', 'note', 'Note:After exclusion of other causes of bleeding, ENG-IMP users with problematic bleeding who are medically eligible can be offered a 3-', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f5107237', 't-mm-05-011', 'html', '<ul><li>month trial of additional use of COC or a 5-day course of mefenamic acid.</li></ul>
<h3><strong>Side Effects</strong></h3>
<ul><li>Headache: Headache is commonly reported during ENG-IMP use; but limited evidence.</li><li>Acne: Observational studies suggest that during ENG-IMP use a minority of users experience new onset acne or worsening of existing acne while others have improvement in existing acne.</li><li>Depression: The available evidence is too limited to confirm or exclude a causative association between ENG-IMP use and depression.</li><li>Weight change: The available evidence is too limited to confirm or exclude a causal association between ENG-IMP use and weight gain.</li><li>Other side effects: Mastalgia (10.2% of women), abdominal pain (5.2%), dizziness (4.9%), emotional lability (5.7%), nervousness (3.5%) and nausea (2.5%).</li></ul>
<h3><strong>Risk of adverse health events</strong></h3>
<ul><li>Venous and arterial thromboembolism: evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.</li><li>Osteoporosis: evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in BMD.</li><li>Breast cancer: no significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.</li><li>Gynecological cancer: The available evidence is too limited to inform whether an association between use of the ENG-IMP and risk of ovarian, endometrial or cervical cancer.</li><li>Ectopic pregnancy: risk of ectopic pregnancy during use of the ENG-IMP is extremely small.</li></ul>
<h3><strong>Points to cover in the clinical history from an etonogestrel implant user who presents with problematic bleeding</strong></h3>
<h3>Clinical history taking should include assessment of:</h3>
<ul><li>The individual\'s own concerns (a particular bleeding pattern may be acceptable to one user, but not to another)</li><li>Duration of use of the etonogestrel implant (ENG-IMP)</li><li>Use of any medications (including over-the-counter preparations) which may interact with the ENG-IMP</li><li>Cervical screening history</li><li>Risk of sexually transmitted infections (highest risk in those aged &lt;25 years, or at any age with a new partner, or more than one partner in the last year, but consider testing for all those with problematic bleeding)</li><li>Bleeding pattern before starting hormonal contraception, since starting and currently</li><li>Other symptoms suggestive of an underlying cause (for example, abdominal or pelvic pain, postcoital bleeding, dyspareunia, heavy menstrual bleeding)</li><li>Possibility of pregnancy.</li></ul>
<h3><strong>Time of Insertion:</strong></h3>
<ul><li>The ENG-IMP can be inserted on days 1–5 of a natural menstrual cycle, by day 5 after abortion, or by day 21 after childbirth without requirement for additional contraceptive precautions.</li><li>Endometrial protection in polycystic ovary syndrome:Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic ovary syndrome who are amenorrhoeic during licensed duration of use of ENG-IMP.</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-25c378b9', 't-mm-05-011', 'note', 'Note:After exclusion of other causes of bleeding, ENG-IMP users with problematic bleeding who are medically eligible can be offered a 3-month trial of additional use of COC or a 5-day course of mefenamic acid.', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2637d8e7', 't-mm-05-011', 'html', '<h3><strong>Side Effects</strong></h3>
<ul><li>Headache: Headache is commonly reported during ENG-IMP use; but limited evidence.</li><li>Acne: Observational studies suggest that during ENG-IMP use a minority of users experience new onset acne or worsening of existing acne while others have improvement in existing acne.</li><li>Depression: The available evidence is too limited to confirm or exclude a causative association between ENG-IMP use and depression.</li><li>Weight change: The available evidence is too limited to confirm or exclude a causal association between ENG-IMP use and weight gain.</li><li>Other side effects: Mastalgia (10.2% of women), abdominal pain (5.2%), dizziness (4.9%), emotional lability (5.7%), nervousness (3.5%) and nausea (2.5%).</li></ul>
<h3><strong>Risk of adverse health events</strong></h3>
<ul><li>Venous and arterial thromboembolism: evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.</li><li>Osteoporosis: evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in BMD.</li><li>Breast cancer: no significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.</li><li>Gynecological cancer: The available evidence is too limited to inform whether an association between use of the ENG-IMP and risk of ovarian, endometrial or cervical cancer.</li><li>Ectopic pregnancy: risk of ectopic pregnancy during use of the ENG-IMP is extremely small.</li></ul>
<h3><strong>Points to cover in the clinical history from an etonogestrel implant user who presents with problematic bleeding</strong></h3>
<h3>Clinical history taking should include assessment of:</h3>
<ul><li>The individual\'s own concerns (a particular bleeding pattern may be acceptable to one user, but not to another)</li><li>Duration of use of the etonogestrel implant (ENG-IMP)</li><li>Use of any medications (including over-the-counter preparations) which may interact with the ENG-IMP</li><li>Cervical screening history</li><li>Risk of sexually transmitted infections (highest risk in those aged &lt;25 years, or at any age with a new partner, or more than one partner in the last year, but consider testing for all those with problematic bleeding)</li><li>Bleeding pattern before starting hormonal contraception, since starting and currently</li><li>Other symptoms suggestive of an underlying cause (for example, abdominal or pelvic pain, postcoital bleeding, dyspareunia, heavy menstrual bleeding)</li><li>Possibility of pregnancy.</li></ul>
<h3><strong>Time of Insertion:</strong></h3>
<ul><li>The ENG-IMP can be inserted on days 1–5 of a natural menstrual cycle, by day 5 after abortion, or by day 21 after childbirth without requirement for additional contraceptive precautions.</li><li>At any other time, the ENG-IMP can be quick started according to Quick Starting Guidance, with advice to use additional contraceptive precautions for 7 days and to take a follow-up pregnancy test (if required).</li></ul>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-012', 'chap-mm-05-01', '13. EMERGENCY CONTRACEPTION', 'Detailed medical reference and study guide on 13. EMERGENCY CONTRACEPTION.', 12, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0e12f0e8', 't-mm-05-012', 'heading', '14. DRUG INTERACTION WITH HORMONAL CONTRACEPTION', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a3d22b97', 't-mm-05-012', 'html', '<ul><li><strong>Indication:</strong> Women who do not wish to conceive should be offered EC after UPSI that has taken place on any day of a natural menstrual cycle.</li><li><strong>After pregnancy:</strong> Women who do not wish to conceive should be offered EC after:</li><li>UPSI from Day 21 after childbirth</li><li>UPSI from Day 5 after abortion, miscarriage, ectopic pregnancy or uterine evacuation for gestational trophoblastic disease (GTD).</li><li>Hormonal contraception incorrectly: Women who do not wish to conceive should be offered EC after UPSI if their regular contraception has been compromised or has been used incorrectly</li></ul>
<h3><strong>There are 3 methods of EC</strong><strong>:</strong></h3>
<ul><li>CU – IUD</li><li>UPA – EC</li><li>LNG – ECG</li></ul>
<h3><strong>Mode of action:</strong></h3>
<ul><li>Sperm are viable in the female genital tract for about 5 days after UPSI. If ovulation occurs within those 5 days, fertilization could take place and a woman is at risk of pregnancy.</li><li><strong>Cu-lUD:</strong> Inhibition of fertilization by its toxic effect on sperm and ova. Copper has been shown to adversely affect the motility and viability of sperm and the viability and transport of ova. It is the most effective method of EC</li><li>UPA: UPA 30 mg – a selective progesterone receptor modulator – acts by delaying ovulation for at least 5 days, until sperm from the UPSI for which EC was taken are no longer viable.</li><li>LNG: LNG-EC inhibits ovulation, delaying or preventing follicular rupture and causing luteal dysfunction.</li></ul>
<h3><strong>    </strong><strong> Oral EC</strong></h3>
<ul><li>EC providers should advise women that UPA-EC has been demonstrated to be effective for EC up to 120 hours of UPSI</li><li>LNG-EC is licensed for <strong>EC up to 72 hours</strong> after UPSI. The evidence suggests that LNG-EC is ineffective if taken more than 96 hours after UPSI.</li><li>UPA-EC has been demonstrated to be more effective than LNG-EC.</li><li>Oral EC administered after ovulation is ineffective</li></ul>
<h3><strong>Effect of Weight/BMI:</strong></h3>
<ul><li><strong>Cu-IUD:</strong> Effectiveness of the Cu-IUD is not known to be affected by weight or BMI.</li></ul>
<p><strong>Oral EC:</strong> It is possible that higher weight or BMI could reduce the effectiveness of oral EC, particularly <strong>LNG-EC</strong>.</p>
<h3>Table 22. Methods of emergency contraception in UK:</h3>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2eba2c30', 't-mm-05-012', 'html', '<table><tbody><tr><td><strong>Method</strong></td><td><strong>Class</strong></td><td><strong>Recommended dose/use</strong></td><td><strong>Indications</strong></td></tr><tr><td>Copper intrauterine device (Cu-IUD)</td><td>Intrauterine contraceptive method</td><td>IUD retained until pregnancy excluded (e.g., onset of next menstrual period) or can be kept for ongoing contraception</td><td>Within 5 days (120 hours) after the first UPSI in a cycle or within 5 days after the earliest estimated date of ovulation</td></tr><tr><td>Levonorgestrel EC (LNG-EC)</td><td>Progestogen</td><td>1.5 mg single oral dose*</td><td>Licensed for use within 72 hours after UPSI or contraceptive failure</td></tr><tr><td>Ulipristal acetate EC (UPA-EC)</td><td>Progesterone receptor modulator</td><td>30 mg single oral dose</td><td>Licensed for use within 5 days (120 hours) after UPSI or contraceptive failure</td></tr></tbody></table>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-444d2c4e', 't-mm-05-012', 'html', '<h3><strong>Consideration before offering EC:</strong></h3>
<ul><li>Hours passed from UPSI</li><li>Date of M/C</li><li>R/O Contraindications of EC</li><li>If <strong>LNG</strong>, double check indications of <strong>Double Dose</strong> (3 mg vs 1.5 mg)</li></ul>
<h3><strong>Double dose of LNG – EC is given in:</strong></h3>
<ul><li>Wt &gt;70 kg</li><li>BMI &gt;26</li><li>Taking enzyme inducing drugs</li></ul>
<h3><strong>Inducers of hepatic CYP450 enzymes:</strong></h3>
<ul><li>EC providers should advise women using enzyme-inducing drugs that the effectiveness of <strong>UPA-EC and LNG-EC could be reduced</strong>.</li><li>Women requiring EC who are using enzyme-inducing drugs should be offered <strong>a Cu-IUD</strong> if appropriate.<strong>A 3 mg dose of LNG can be considered but women should be informed that the effectiveness of this regimen is unknown.</strong></li><li>A <strong>double-dose of UPA-EC is not recommended</strong></li></ul>
<p>▪ Progestogens: EC providers should be aware that the effectiveness of UPA-EC could be reduced.</p>
<p>▪ If a woman takes progestogen in the 5 days after taking UPA-EC, EC providers should be aware that the effectiveness of UPA-EC could theoretically be reduced if a woman has taken progestogen prior to taking UPA-EC.</p>
<h3><strong>Contraindications/Restrictions to Use of EC:</strong></h3>
<ul><li><strong>Cu-IUD:</strong> EC providers should be aware that the contraindications to insertion of a Cu-IUD for EC are the <strong>same as those for routine IUD insertion</strong>.</li><li><strong>UPA-EC:</strong> EC providers should be aware that UPA-EC is <strong>not suitable for use by women </strong><strong>who have severe asthma controlled by oral glucocorticoids</strong>.</li></ul>
<h3><strong>Breastfeeding and Require EC:</strong></h3>
<ul><li><strong>Cu-IUD:</strong> Breastfeeding women have a higher relative risk of uterine perforation during insertion of intrauterine contraception than non-breastfeeding women. However, absolute risk of perforation is low.</li><li><strong>UPA-EC:</strong> Breastfeeding women should be advised not to breastfeed and to express &amp; discard milk <strong>for a week</strong> after they have taken UPA-EC.</li><li><strong>LNG-EC:</strong> Women who breastfeed should be informed that available limited evidence indicates that <strong>LNG-EC has no adverse effects</strong> on breastfeeding or on their infants.</li></ul>
<h3><strong>Method of EC:</strong></h3>
<p>All women requiring EC should be offered a Cu-lUD if appropriate as</p>
<p>it is the most effective method of EC. Cu-IUD can be inserted up to 5 days after the first UPSI in a natural menstrual cycle, or up to 5 days after the earliest likely date of ovulation (whichever is later).</p>
<p>a Cu-IUD is not appropriate or not acceptable; women should be advised that oral EC should be taken as soon as possible if there has been UPSI within the last 5 days</p>
<p>EC providers should consider! UPA-EC as the first-line oral EC for a woman who has had UPSI 96-120 hours ago (even if she has also had UPSI within the last 96 hours).</p>
<p><em><strong>Sexual assault:</strong></em> Women requiring EC after sexual assault should be offered all methods of EC including the Cu-IUD.</p>
<ul><li>offer a woman UPA-EC or LNG-EC if she has had UPSI earlier in the same cycle as well as within the last 5 days, as evidence suggests that UPA- EC and LNG-EC do not disrupt an existing pregnancy and are not associated with fetal abnormality.</li><li>If vomiting occurs within 3 hours of taking oral EC, a repeat dose should be given</li></ul>
<h3><strong>Time to contraceptive effectiveness when starting 120 hours after ulipristal acetate emergency contraception (UPA-EC)</strong></h3>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c0ab5531', 't-mm-05-012', 'html', '<table><tbody><tr><td><strong>Contraceptive method</strong></td><td><strong>Requirement for additional contraception after starting method</strong></td></tr><tr><td>Combined oral contraceptive pill except Qlaira</td><td>7 days</td></tr><tr><td>Combined vaginal ring/transdermal patch</td><td>7 days</td></tr><tr><td>Progestogen-only pill (traditional/Desogestrel)</td><td>2 days</td></tr><tr><td>Progestogen-only implant or injectable</td><td>7 days</td></tr><tr><td>Qlaira</td><td>9 days</td></tr></tbody></table>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3ab59d94', 't-mm-05-012', 'html', '<p>🔹 <strong>Choosing between UPA-EC and LNG-EC</strong></p>
<ul><li>Ulipristal acetate EC (UPA-EC) has been demonstrated to be more effective than levonorgestrel.</li><li>EC (LNG-EC) from <strong>0–120 hours</strong> after UPSI. The evidence suggests that both UPA-EC and LNG-EC are ineffective if taken after ovulation.</li></ul>
<h3><strong>METHODS OF EC IN UK</strong></h3>
<ul><li><strong>Women requiring EC who are using enzyme-inducing drugs should be offered a Cu-IUD if appropriate.</strong></li><li><strong>A 3 mg dose of LNG can be considered but women should be informed that the effectiveness of this regimen is unknown. </strong><strong>A double-dose of UPA-EC is NOT recommended.</strong></li></ul>
<h3><strong>METHODS OF EC IN UK</strong></h3>
<p>The effectiveness of UPA-EC could be reduced if a woman takes progestogen in the <strong>5 days after taking UPA-EC</strong>.</p>
<p>Effectiveness of UPA-EC could theoretically be reduced if a woman has <strong>taken progestogen in the 7 days prior</strong> to taking UPA-EC.</p>
<p>Avoid progestogen 7 days before and 5 days after taking UPA-EC.</p>
<h3><strong>EMERGENCY CONTRACEPTION</strong></h3>
<ul><li>✅ <strong>Adolescents who need EC should be offered all methods of EC including the Cu-IUD.</strong></li><li>✅ <strong>Women requiring EC after sexual assault should be offered all methods of EC including the Cu-IUD.</strong></li></ul>
<h3><strong>Effectiveness of EC – methods:</strong></h3>
<ul><li>UPA ➜ 98% if taken within 120 hours</li><li>LNG ➜ 85% in 72 hours then decreases to 56% in next 12 hours</li><li>IUCD ➜ 99% effective</li></ul>
<h3><strong>IMP</strong><strong>ORTANT</strong><strong> tips before selection of EC</strong></h3>
<ul><li>after day 19 ➜ use of IUCD if ovulation delayed</li><li>within day 14 ➜ prefer oral pills</li><li>LNG – UPSI → 72 hrs. (before midcycle)</li><li>UPA – UPSI → 120 hrs. (before midcycle &lt;19 days)</li><li>IUCD – UPSI → 120 hrs. (after midcycle even before midcycle)</li><li>always keep in mind contra-indications of each EC</li></ul>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-013', 'chap-mm-05-01', '14.DRUG INTERACTIONS WITH HORMONAL CONTRACEPTION', 'Detailed medical reference and study guide on 14.DRUG INTERACTIONS WITH HORMONAL CONTRACEPTION.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-cd624169', 't-mm-05-013', 'html', '<p>Enzyme inducers which may DECREASE contraceptive efficacy</p>
<p>Antiepileptics(e.g. carbamazepine, eslicarbazepine, fosphenytoin, oxcarbazepine, phenobarbital, phenytoin, primidone, rufinamide, topiramate)</p>
<p>Antibacterials(e.g. rifabutin, rifampicin)</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-eb4cb0a0', 't-mm-05-013', 'note', 'Antiretrovirals(e.g. efavirenz, nevirapine)Note: Ritonavir reduces the bioavailability of estrogen and may reduce the bioavailability of progestogens by inducing glucuronidation.', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8548ad8f', 't-mm-05-013', 'html', '<p>Antidepressants(e.g. St John’s wort – a herbal preparation)</p>
<p>Others(e.g. modafinil, bosentan, aprepitant, lumacaftor)</p>
<h3>Enzyme inhibiting drugs that may INCREASE hormone levels:</h3>
<ul><li>Antibacterials (e.g. erythromycin)</li><li>Antifungals (e.g. fluconazole, itraconazole, ketoconazole, posaconazole, voriconazole)</li><li>Antiretrovirals (e.g. atazanavir)</li><li>Immunosuppressants (e.g. tacrolimus)</li><li>Non-steroidal anti-inflammatories (NSAIDs) (e.g. etoricoxib)</li><li>Statins (e.g. atorvastatin, rosuvastatin)</li><li>Vasodilators (e.g. sitaxentan sodium)</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-65fe1be6', 't-mm-05-013', 'note', 'Note:', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-75f2b551', 't-mm-05-013', 'html', '<p>Lamotrigine (antiepileptic) and griseofulvin (antifungal) are not thought to be enzyme-inducing drugs; however, contraceptive efficacy may still be reduced by concurrent use.The clinical significance of this effect is unknown</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-368c2373', 't-mm-05-013', 'heading', 'Effects of contraceptive hormones on other drugs', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-137accb7', 't-mm-05-013', 'html', '<ul><li>Antiepileptics</li><li>Combined hormonal contraception (CHC) moderately reduces lamotrigine exposure.</li><li>This can lead to decreased seizure control during the hormone phase and increased lamotrigine exposure and toxicity risk in the hormone-free week.</li><li>Desogestrel</li><li>Might increase lamotrigine levels and adverse effects.</li><li>Ethinylestradiol (EE) may modestly reduce sodium valproate levels.</li><li>Progestogen receptor modulators</li></ul>
<p>Quick starting hormonal contraception after ulipristal acetate (UPA) for emergency contraception (EC) may reduce EC effectiveness.</p>
<p><em>Possible adverse effects and/or consider some monitoring</em></p>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-abec8427', 't-mm-05-013', 'html', '<table><tbody><tr><td><strong>Drug Class</strong></td><td><strong>Interaction</strong></td></tr><tr><td>Antihypertensives</td><td>Estrogens may increase BP and antagonize antihypertensive efficacy.</td></tr><tr><td>Antidiabetics</td><td>Estrogens may antagonize the hypoglycemic effect of antidiabetics.</td></tr><tr><td>Anxiolytics &amp; hypnotics</td><td>Estrogens and progestogens may reduce plasma concentrations of lorazepam, oxazepam, and temazepam.</td></tr><tr><td>Thyroid hormones</td><td>Estrogens may increase the requirements for thyroid hormones in hypothyroidism.</td></tr></tbody></table>', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-166c1d0c', 't-mm-05-013', 'heading', 'Increased levels or adverse effects', 9) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e1292e2f', 't-mm-05-013', 'html', '<table><tbody><tr><td><strong>Drug Class</strong></td><td><strong>Interaction Details</strong></td></tr><tr><td>✅ Immunosuppressants</td><td>EE (Ethinylestradiol) might increase tacrolimus concentrations — should be monitored by a specialist. Ciclosporin levels may be increased by estrogens and progestogens.</td></tr><tr><td>✅ UPA (Ulipristal Acetate)</td><td>Predicted to increase everolimus and sirolimus concentrations.</td></tr><tr><td>✅ Dopaminergic</td><td>Selegiline levels may increase due to estrogens/progestogens → toxicity risk. EE reduces ropinirole clearance by ~one-third. Manufacturers advise avoiding concurrent use.</td></tr></tbody></table>', 10) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-26d8185d', 't-mm-05-013', 'heading', 'Possible adverse effects and/or consider some monitoring', 11) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a3ce385d', 't-mm-05-013', 'html', '<table><tbody><tr><td><strong>Drug Class</strong></td><td><strong>Interaction</strong></td></tr><tr><td>Antifungals</td><td>Estrogens and progestogens may increase levels of voriconazole.</td></tr><tr><td>Anxiolytics &amp; hypnotics</td><td>Estrogens and progestogens may increase plasma concentrations of chlordiazepoxide, diazepam, and clorazepate.</td></tr><tr><td>Bronchodilators</td><td>Estrogens slightly reduce the clearance of theophylline, leading to increased plasma concentrations. Reducing dosage is recommended if adverse effects occur.</td></tr><tr><td>Muscle relaxants</td><td>Estrogens and progestogens may increase tizanidine levels and its adverse effects.</td></tr></tbody></table>', 12) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c90454b7', 't-mm-05-013', 'heading', 'Possible adverse effects and/or consider some monitoring', 13) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-61711669', 't-mm-05-013', 'html', '<table><tbody><tr><td><strong>Drug Class</strong></td><td><strong>Interaction</strong></td></tr><tr><td>✅ Potassium-sparing diuretics and aldosterone antagonists</td><td>Additive hyperkaliemia or hypotension might occur with Drosperinone and potassium-sparing diuretics.</td></tr><tr><td>✅ Retinoids</td><td>Adverse effects of oral contraceptives on lipids may add to those of isotretinoin. As retinoids are teratogenic, highly effective contraception (e.g., IUDs or progestogen-only implants) is recommended.</td></tr><tr><td>✅ Triptans</td><td>COCs (Combined Oral Contraceptives) appear to slightly raise levels of frovatriptan, naratriptan, and zolmitriptan, though not clinically significant.</td></tr></tbody></table>', 14) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2b8a2dc2', 't-mm-05-013', 'heading', 'Effect of Enzyme Inducers (during use and for 4 weeks after)', 15) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c1630a39', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Type</td><td>Impact of Enzyme Inducers</td><td>Action</td></tr><tr><td>CHC (Combined Hormonal Contraception)</td><td>❌ Known clinical interaction</td><td>Avoid use; advise alternative method</td></tr><tr><td>POP (Progestogen-only pill)</td><td>❓ Potential interaction</td><td>Caution required</td></tr><tr><td>IMP (Progestogen-only implant)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>DMPA (Depot medroxyprogesterone acetate)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>LNG-IUS (Levonorgestrel IUD)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>Cu-IUD (EC)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>LNG-EC (Levonorgestrel Emergency Contraception)</td><td>❓ Potential interaction</td><td>Caution required</td></tr><tr><td>UPA-EC (Ulipristal Acetate EC)</td><td>❌ Known clinical interaction</td><td>Avoid use; advise alternative method</td></tr><tr><td><strong>Drug Type</strong></td><td><strong>CHC</strong></td><td><strong>POP</strong></td><td><strong>IMP</strong></td><td><strong>DMPA</strong></td><td><strong>LNG-IUS</strong></td><td><strong>Cu-IUD (EC)</strong></td><td><strong>LNG-EC</strong></td><td><strong>UPA-EC</strong></td></tr><tr><td><strong>Lamotrigine</strong> <em>(non-enzyme inducer)</em></td><td>❓</td><td>❓</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Griseofulvin</strong> <em>(non-enzyme inducer)</em></td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>❓</td></tr><tr><td><strong>Drugs that alter gastric pH</strong></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Drugs causing severe </strong><strong>diarrhea</strong><strong>/vomiting</strong></td><td>❓</td><td>❓</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>❓</td><td>❓</td></tr><tr><td><strong>Progestogen receptor modulators</strong> <em>(e.g., UPA)</em></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 16) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
