INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7dba75ff', 't-mm-05-014', 'html', '<p><strong>Continue with methodContinue with method</strong>Continue with methodContinue with method<strong>Normal findingsNormal findings</strong>Normal findingsNormal findings<strong>Clinical findings refer/manage appropriatelyClinical findings refer/manage appropriately</strong>Clinical findings refer/manage appropriatelyClinical findings refer/manage appropriately</p>
