INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-05-015', 'chap-mm-05-01', '16. BARRIER METHODS FOR CONTRACEPTION AND STI PREVENTION', 'Detailed medical reference and study guide on 16. BARRIER METHODS FOR CONTRACEPTION AND STI PREVENTION.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-1ac5385b', 't-mm-05-015', 'html', '<h3>Barrier methods include:</h3>
<ul><li>Male condoms (latex, non-latex, and deproteinized latex varieties)</li><li>Female condoms (nitrile or latex)</li><li>Diaphragms (latex, silicone)</li><li>Cervical cap (silicone)</li><li>Dams (latex, non-latex)</li><li>Condoms (male and/or female): Men and women requesting condoms should be informed of the efficacy of condoms including their failure rate relative to other methods.</li><li>Diaphragms and caps: A diaphragm or cervical cap can be inserted with spermicide any time before intercourse. Spermicide should be reapplied if sex is to take place and the diaphragm or cap has been in situ for &gt;3 hours or if sex is repeated with the method in place. A diaphragm or cervical cap should not be removed until at least 6 hours after the last episode of intercourse.</li><li>Barrier Methods at Preventing Transmission of STIs and other infections</li><li>Condoms recommendedSexually active men and women can be informed that the consistent and correct use of condoms (including with sex toys) is the most efficient means of protecting against HIV and other STIs.</li><li>HIV</li><li>Chlamydia trachomatis</li><li>Neisseria gonorrhoeae</li><li>Trichomonas vaginalis</li><li>Syphilis</li><li>Human papillomavirus</li><li>Herpes simplex infection</li><li>Viral hepatitis</li><li><strong>Factors Affecting the Efficacy of Barrier Methods</strong></li><li>Spermicides:Women using a diaphragm or cap should be advised to use the device with spermicide. The use of condoms lubricated with N-9 is not recommended.</li><li>Lubricants:When using lubricant with latex condoms, diaphragms, and caps, a water- or silicone-based preparation is recommended.</li><li>Size and shape:Ill-fitting condoms can be associated with breakage and incomplete use.</li><li>Legal issues:Health professionals should keep up to date with the important legal issues regarding HIV/STI transmission and advise patients appropriately as regards partner notification, disclosure and condom use.</li></ul>
<h3><strong>Considerations Following Barrier Method Failure:</strong></h3>
<h3>Emergency contraception (EC) may be indicated in the following situations:</h3>
<ul><li>Diaphragm or cap is dislodged or removed within 6 hours of sex</li><li>Diaphragm has been left in for longer than 3 hours before sex and no additional spermicide applied</li><li>Condom splitting/breaking</li><li>Condom slippage</li><li>Failure to use condoms as advised when starting or switching contraception</li><li>If enzyme-inducing drugs are being used alongside hormonal contraception (combined hormonal contraception, POP and implant) and condoms are not used during or for 28 days after</li><li>Post-exposure prophylaxis for HIV:Men and women can be made aware of PEPSE.For women living with HIV or at high risk of HIV infection, the use of either a diaphragm or cervical cap is a UKMEC Category 3.</li><li>Post-exposure prophylaxis for HIV:Men and women can be made aware of PEPSE.For women living with HIV or at high risk of HIV infection, the use of either a diaphragm or cervical cap is a UKMEC Category 3.</li><li>Latex allergy:Women with sensitivity to latex proteins should avoid the use of latex barrier contraceptives and may use a:</li><li>silicone diaphragm</li><li>cervical cap</li><li>non-latex male or female condoms</li><li>deproteinized latex male condoms</li><li>Toxic shock syndrome (TSS):For women with a history of toxic shock syndrome:</li><li>The use of the diaphragm, cervical cap or contraceptive sponge is a UKMEC Category 3.</li><li>Women with a history of TSS may use male or female condoms.</li></ul>
<p>Caps and diaphragms should not be left in situ for longer than recommended by the manufacturer or used during menstruation.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
