INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0545588e', 't-mm-06-005', 'html', '<ul><li>1.1 – 1.9%.</li></ul>
<h3><strong>Pathophysiology:</strong></h3>
<ul><li>Neuropraxia:</li><li>External compression disruption of conduction system in small portion.</li><li>Axonotmesis – healing takes weeks to months:</li><li>Profound compression or traction.</li><li>Preservation of Schwan cells.</li><li>Damage to Axon.</li><li>Take weeks to months to recover</li><li>Neurotmesis:</li><li>Complete nerve transection.</li><li>Both Axon + Schwan cells.</li><li>Poor prognosis</li><li>Surgery is required.</li></ul>
<h3><strong>Prevention:</strong></h3>
<ul><li>Proper lithotomy.</li><li>Strips &amp; boots @ equal height.</li><li>Proper incision – lateral margin or rectus &amp; health.</li><li>Suturing of rectus sheath with 1.5 of lateral margins. Separate fat from sheath as it contains ilioinguinal or iliohypogastric nerves</li><li>Self-retaining Cather for max of 4 hours, frequently change the position.</li><li>Arm rest not beyond 900.</li><li>Keep Arm in pronated position.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li><em><strong>Sensory:</strong></em></li><li>5 weeks trial of TCA, GABA</li><li>No effect after 6m0  then give local anesthesia.</li><li><em><strong>Moto</strong></em><em><strong>r:</strong></em></li><li>10 weeks up to 4 years =&gt; physiotherapy, splinting.</li><li><em><strong>Surgery:</strong></em></li></ul>
<p>Rarely required except Transection type injuries.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f86e2cbd', 't-mm-06-005', 'html', '<table><tbody><tr><td><strong>NERVE</strong></td><td><strong>PROCEDURE</strong></td><td><strong>PRESENTATION</strong></td></tr><tr><td>Femoral</td><td>TAH<br/>With retractor 8%.<br/>Without 1%.<br/>Improper lithotomy.</td><td>Loss of knee Jerk<br/>Sensory loss @ anterior and Medial thigh.<br/>Unable to climb Stairs.</td></tr><tr><td>Ilioinguinal, iliohypogastric 3.7%</td><td>Pfannenstiel incision 7%</td><td>Pain from scar to mons, labia, thigh</td></tr><tr><td>Genitofemoral</td><td>External Iliac node dissection</td><td>Same as ilioinguinal but towards femoral triangle instead of thigh</td></tr><tr><td>Lateral cutaneous Nerve of thigh</td><td>As (F) Nerve</td><td>Pain and paresthesia over lateral post and anterior thigh</td></tr><tr><td>Obturator nerve</td><td>TOT<br/>Pelvic flow repair<br/>Endometriosis</td><td>Medial thigh</td></tr><tr><td>Common peroneal</td><td>Sciatic notch</td><td>Foot drop</td></tr><tr><td>Tibial</td><td>Improper lithotomy</td><td>caves deformity</td></tr><tr><td>Pudendal</td><td>SSF</td><td>perineal pain on sitting sexual dysfunction.</td></tr><tr><td>Brachial plexus</td><td>Arm rest</td><td>&nbsp;</td></tr><tr><td>Upper trunk</td><td>Hyperabduction</td><td>Erb</td></tr><tr><td>Lower trunk</td><td>Lateral placement of brace</td><td>Clump Kie’s + claw hand radial wrist drop</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
