INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-022', 'chap-mm-06-01', '17.5. DEEP VEIN THROMBOSIS', 'Detailed medical reference and study guide on 17.5. DEEP VEIN THROMBOSIS.', 22, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5d6d19a2', 't-mm-06-022', 'html', '<ul><li>Prevention and trhomboprophylaxis</li><li>DVT</li></ul>
<h3><strong>Symptoms:</strong></h3>
<ul><li>Pain</li><li>Swelling</li><li>Erythema</li></ul>
<h3><strong>Signs:</strong></h3>
<ul><li>Low grade temperature</li><li>Leg swollen, warmer</li><li>Peripharal veins distal to occlusion may appear distorted</li><li>Tender to palpation.</li></ul>
<h3><strong>Investigations:</strong></h3>
<ul><li>1. Compression duplex USG</li><li>Primary diagnostic test with 87% sensitivity</li><li>Vein is visualized by using B – mode USG</li><li>Vein is compressed by the transducer, if vein fails to collapse and intraluminal clot is present, even if it can’t be visualized.</li></ul>
<h3><strong>Compression duplex USG</strong></h3>
<p><em><strong>Positive</strong></em><em><strong>negative</strong></em></p>
<p><em><strong>+ High suspicion </strong></em></p>
<p><strong>Venographystart anti – coagulant + repeat test in 1 week        ++ve-veContinuediscontinue AnticoagulationanticoagulationVenographystart anti – coagulant + repeat test in 1 week        ++ve-veContinuediscontinue Anticoagulationanticoagulation</strong>Venographystart anti – coagulant + repeat test in 1 week       <strong> +</strong>+ve-veContinuediscontinue AnticoagulationanticoagulationVenographystart anti – coagulant + repeat test in 1 week       <strong> +</strong>+ve-veContinuediscontinue Anticoagulationanticoagulation</p>
<ul><li>2. Venography – as explained in the chart</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-66bee209', 't-mm-06-022', 'heading', '3. MR venography or contrast venography', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8c86e03a', 't-mm-06-022', 'html', '<ul><li>In iliac vein thrombosis (back pain + entire limb swelling)</li><li>4. D – dimer – assist in clinical diagnosis.</li><li>Levels =&gt; exclude VTE</li><li>4 – 17 % VTE not identified by D – dimer</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-03993a6d', 't-mm-06-022', 'heading', '5. CTPA vs radionuclide V/Q scan.', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-4a6daa7c', 't-mm-06-022', 'html', '<table><tbody><tr><td><strong>Parameter</strong></td><td><strong>CTPA</strong></td><td><strong>V/Q</strong></td></tr><tr><td>1. Radiation dose</td><td>High (20msv)</td><td>Low</td></tr><tr><td>2. Absorbed dose to breast</td><td>10mGY</td><td>0.28mGY</td></tr><tr><td>3. Risk of LA breast</td><td>13.6%</td><td>1/200 (background risk)</td></tr><tr><td>4. 1st choice investigation</td><td>Gold standard in diagnosis of pulmonary embolism</td><td>- In young women.<br/>- Who had CT in past<br/>- FH of CA breast</td></tr></tbody></table>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bf0f8de3', 't-mm-06-022', 'html', '<ul><li><strong>Pulmonary embolism</strong></li></ul>
<h3><strong>Symptoms:</strong></h3>
<ul><li>Cough</li><li>SOB</li><li>Pleutritic chest pain</li><li>Haemoptysis</li><li>Fever</li></ul>
<h3><strong>Signs:</strong></h3>
<ul><li>Tachycardia</li><li>Tachypnoea</li><li>Low SPO2</li><li>Low grade pyrexia</li><li>ECG changes (S1 Q2 T3) Non specific</li><li>Plueral rub</li><li>Fine crepitation @ base of lungs</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Emergency with high mortality</li><li>ICU admission</li><li>MDT involvement</li><li>Full anticoagulation</li><li>Understanding of recurrent factor.</li></ul>
<h3>17.6. SEPSIS:</h3>
<ul><li>Hospital acquired infection 7%</li><li>Upto 15% in low and middle income countries</li><li>Sepsis six</li></ul>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-73dc630b', 't-mm-06-022', 'image', '/uploads/content-images/maternal_mind_book/image69.jpg', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d2138526', 't-mm-06-022', 'html', '<h3><strong>Management:</strong></h3>
<ul><li>Same as other patients</li><li>Broad spectrum antibiotics, Gentamicin is considered useful.</li><li>Genital sepsis is polymicobial infection</li><li>Liasie with microbiologist</li><li>Follow up treatment according to culture and sensitivities.</li></ul>', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-023', 'chap-mm-06-01', '17.7. PELVIC ABSCESS', 'Detailed medical reference and study guide on 17.7. PELVIC ABSCESS.', 23, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0ab6032a', 't-mm-06-023', 'html', '<ul><li>Can form in pouch of douglas</li><li>Can vary in size and symptoms</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>History + examination</li><li>Abdominopelvic USG</li><li>Abdominopelvic CT scan</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li><em><strong>1. </strong></em><em><strong>Medical:</strong></em></li><li>Rule out sepsis</li><li>Antibiotics to small abscess</li><li>2. <em><strong> Needle drainage:</strong></em></li><li>Percutaneous drainage by intervention radiologist</li><li>Can be performed abdominally or vaginally depending upon location</li><li>Hospital stay</li><li>Morbidity</li><li>Microscopy, culture and sensitivity of purulant content improve overall management.</li><li>Immediately effective if successful</li><li><em><strong>3. </strong></em><em><strong>Surgical Management:</strong></em></li><li>Either open or laproscopy</li><li>Surgical treatment is considered where medical treatment has failed and intervention radiology is not available.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-024', 'chap-mm-06-01', '17.8. ANAESTHESIA COMPLICATION', 'Detailed medical reference and study guide on 17.8. ANAESTHESIA COMPLICATION.', 24, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-20704a70', 't-mm-06-024', 'html', '<ul><li>Post dural puncture headache, commonest complication</li><li>Fronteal headache</li><li>Severe in intensity</li><li>Postural and relived by lying down</li><li>meningitis should be ruled out</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-025', 'chap-mm-06-01', '17.9. VISCERAL INJURIES', 'Detailed medical reference and study guide on 17.9. VISCERAL INJURIES.', 25, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-026', 'chap-mm-06-01', '17.9.1. URINARY TRACT', 'Detailed medical reference and study guide on 17.9.1. URINARY TRACT.', 26, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9db2eb6e', 't-mm-06-026', 'html', '<ul><li>Most common visceral injury in gynaecological surgery is to the bladder, Dome is most commonly involved.</li><li>Ureteric damage in gynaecological surguries = 0.5 – 2.5%</li><li>In endometriosis surgery = 65% damage to ureter and 5.6% ureteric stenosis.</li><li>Most common sites of damage</li><li>Angle of vagina</li><li>Near pelvic brim close to ovarian blood supply.</li></ul>
<h3><strong>Signs and symptoms of urinary tract damage:</strong></h3>
<ul><li>Persistant loin pain.</li><li>Poor urine output despite ruling out other conditions</li><li>Blood stained or clear fluid in peritoneal drain</li><li>Vaginal leakage of urine</li><li>Urine draining abdominally</li></ul>
<h3><strong>Signs and symptoms of Urinary tract o</strong><strong>c</strong><strong>culsion:</strong></h3>
<ul><li>Loin pain – may not be as severe as anticipated and may settle with NSAID.</li><li>Oliguria (in case of bilateral)</li><li>Persistant haematuria</li><li>Pyrexia</li></ul>
<h3><strong>Investigations:</strong></h3>
<ul><li>Blood test, RFT’S to rule out kidney damage</li><li>Ultrasound – dilated ureters in occulsion</li><li>IVU – details of level of block</li><li>3 swab test – VVF</li><li>Cytoscopy = VVF and occulsion of terminal ureter</li><li>Stenting + radio – opaque dye – demonstrate in ureter.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Seek a urologists help.</li></ul>
<h3><strong>Uretric Injury:</strong></h3>
<ul><li>@ pelvic brim – end to end anastomosis</li><li>@ bladder edge – reimplantation into bladder using psoas hitch or bladder flap to relive tension on repair.</li></ul>
<h3><strong>Fistula:</strong></h3>
<ul><li>Immediate after surgery – repair + cathetrization</li><li>Small leakage post op = cathertrization 7 – days and manage conservatively</li><li>Delayed repair – if fistula appears late.</li><li>Adequate mobilization of fistula</li><li>Triming of edges or debridment</li><li>Repair in 2 layers can be done in 1 layer</li><li>Use absorbable sutures.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-027', 'chap-mm-06-01', '17.9.2. Bowel complications', 'Detailed medical reference and study guide on 17.9.2. Bowel complications.', 27, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-84b9281d', 't-mm-06-027', 'html', '<ul><li>Relatively rare</li><li><strong>Paralytic ilues:</strong></li><li>Commonest bowel complication</li><li>Manipulation of small bowel during surery diminishes bowel activity for 16 hours, Failure to return to normal activity will result in paralytic ilues</li></ul>
<h3><strong>Signs and symptoms:</strong></h3>
<ul><li>Nausea</li><li>Vomiting</li><li>Abdominal distention</li><li>Unable to tolerate fluids</li><li>Delayed passage of flatus and stool</li></ul>
<h3><strong>On examination</strong></h3>
<p>Bowel sounds quiet or reduced</p>
<h3><strong>X – ray abdomen</strong></h3>
<p>Dilated bowel loops</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8e69ec94', 't-mm-06-027', 'image', '/uploads/content-images/maternal_mind_book/image70.jpg', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0da61048', 't-mm-06-027', 'html', '<h3><strong>Management</strong></h3>
<ul><li>Always managed conservatively</li><li>NPO to rest the bowels.</li><li>Fluid replacement</li><li>Nasogestric tube drainage once ileus is confirmed</li><li>Oral intake when there is evidance of return of bowel function</li><li>Start oral intake gradually</li><li><strong>Bowel obstruction:</strong></li><li>Rare complication</li><li>Become apparant untill day 5 post op</li></ul>
<h3><strong>Clinical picture</strong></h3>
<ul><li>Persistent vomiting</li><li>Abdominal distention</li><li>Abdominal pain</li><li>Signs of peritonism</li></ul>
<h3><strong>X – ray:</strong></h3>
<ul><li>Reveals dilated bowel loop</li><li>Air fluid levels</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-080daea9', 't-mm-06-027', 'image', '/uploads/content-images/maternal_mind_book/image71.jpg', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-90e87281', 't-mm-06-027', 'html', '<h3><strong>Management:</strong></h3>
<ul><li><em><strong>Signs of peritonism orDespite conservative treatmentPersistent vomitingHigh volume NG aspirateMinimal passage of flatusProlong durationsurgerySigns of peritonism orDespite conservative treatmentPersistent vomitingHigh volume NG aspirateMinimal passage of flatusProlong durationsurgery</strong></em><em><strong>Signs of peritonism or</strong></em><em><strong>Despite conservative treatment</strong></em>Persistent vomitingHigh volume NG aspirateMinimal passage of flatusProlong durationsurgery<em><strong>Signs of peritonism or</strong></em><em><strong>Despite conservative treatment</strong></em>Persistent vomitingHigh volume NG aspirateMinimal passage of flatusProlong durationsurgery</li></ul>
<p><em><strong>No Peritonis</strong></em><em><strong>m</strong></em></p>
<ul><li>NPO</li><li>NG tube</li><li>I/V fluids</li></ul>
<p>Mostly resolves</p>
<p>in 48 – 72 hours</p>
<p>Failed conservative</p>
<p>measures</p>
<p>surgery</p>
<h3><strong>Differnces between ileus and intestinal obstruction</strong><strong>:</strong><strong> </strong></h3>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
