INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2cef2dee', 't-mm-06-032', 'html', '<p>8.1. POP CLASSIFICATION</p>
<p>8.2. VAGINAL PRESSERIES</p>
<p>8.3. VAUL PROLAPSE</p>
<h3><strong>UV Prolapse:</strong></h3>
<ul><li>Vaginal hystrectomy</li><li>Most common</li><li>Uterine conservative procedures</li><li>Laproscopic uterosacral ligament plication</li><li>Risk of uretric kinking.</li><li>Hysteropexy</li><li>Risk of:</li><li>Anterior prolapse</li><li>Urinary retention</li><li>Need for further prolapse surgery</li></ul>
<h3><strong>Vault Prolapse:</strong></h3>
<ul><li>Sacrocolpopexy</li><li>Uterosacral ligament suspension</li></ul>
<h3><strong>Incontine</strong><strong>nce procedures:</strong></h3>
<ul><li>Colposuspension</li><li>Retroperitoneal/ Transperitoneal</li><li>Preffered option for SUI</li><li>Plication of paraurethral tissue with cooper’s ligament by applying 2 – 3 suture and correcting vesicourethral angle</li><li>Midurethral sling – preffferably vaginally</li></ul>', 11) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-06-033', 'chap-mm-06-01', '22. SURGICAL SMOKE', 'Detailed medical reference and study guide on 22. SURGICAL SMOKE.', 33, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-442ecc3e', 't-mm-06-033', 'html', '<h3><strong>Following energy devices are used in surgery:</strong></h3>
<ul><li>1. Electrosurgical</li><li>2. Laser</li><li>3. Ultrasonic</li><li>4. Plasma energy devices</li></ul>
<h3><strong>Surgical Plume/Surgical Smoke:</strong></h3>
<ul><li>Are the vapor produced during surgical procedures while using energy devices</li><li>Contain hazardous substances including ultrafine particle, bacteria, viruses, cellular debris, toxic gasses and vapours</li><li>Exposure can lead to various health issues to surgical staff including respiratory problems, eye and throat irritation and potential long term health effects like carcinogenesis</li><li>More in monopolar (@ 1000) than bipolar (@ 2000)</li></ul>
<h3><strong>Composition of Plume:</strong></h3>
<ul><li>95% water</li><li>5% particles</li></ul>
<h3><strong>Particle size:</strong></h3>
<ul><li>Upto 100um</li><li>Smallest – 0.7um in electrosurgery</li><li>Large – 0.31um in laser</li><li>Largest – 0.3-0.6um in ultrasonic devices</li><li>Below 10 um =&gt; inhalable</li><li>Below 5um =&gt; deposited in nose, pharynx, trachea.</li><li>Below 25um =&gt; deeper penetration and inflamatory response</li></ul>
<h3><strong>Particle concentration:</strong></h3>
<ul><li>More concentrated in fat and viscera</li><li>Less concentrated in muscles</li></ul>
<h3><strong>Measures to reduce risk of surgical smoke:</strong></h3>
<ul><li>PPE</li><li>Surgical mask filters upto 5um particles</li><li>Filters upto 0.1um.</li><li>Surgical evacuation system</li><li>Portable</li><li>Local exhaust ventilatio</li><li>Wall suction devices</li><li>Choosing the right devices</li><li>Using bipolar instead of monopolar</li><li>Lower power setting</li><li>Minimum necessary use of devices</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
