INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-07-001', 'chap-mm-07-01', '1. RECURRENT PREGNANCY LOSS', 'Detailed medical reference and study guide on 1. RECURRENT PREGNANCY LOSS.', 1, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b8110fe7', 't-mm-07-001', 'html', '<ul><li>Work up after 2 miscarriages if abnormality is suspected</li><li>Sggryd – 5% women</li><li><strong>Risk factors of Recurrent pregnancy loss:</strong></li><li>Age</li><li>Female &gt; 35yrs</li><li>Male &gt; 40yrs</li><li>Previous miscarriages</li><li>Successful pregnancy after RPL = 60%</li><li>Further loss after RPL = 40%</li><li>Obesity / low BMI</li></ul>
<p>&lt;19, &gt;25</p>
<ul><li>Black ethnicity</li><li>Smoking.</li><li>alcohol</li><li>caffeine&gt;200mg/day</li><li><strong>Risk factor of Sporadic miscarriages:</strong></li><li>Caffeine / Tea, mostly in first trimester.</li><li>Alcohol.</li><li>Obesity.</li><li>Age.</li><li>Environmental Factors.</li><li>Anesthetic Gases – under Reasaerch, confliciting data.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-75e73324', 't-mm-07-001', 'html', '<table><tbody><tr><td><strong>Age of female</strong></td><td><strong>% of Miscarriage</strong></td></tr><tr><td>12 – 19 years</td><td>13%</td></tr><tr><td>20 – 24</td><td>11%</td></tr><tr><td>25 – 29</td><td>12%</td></tr><tr><td>30 – 34</td><td>15%</td></tr><tr><td>35 – 39</td><td>25%</td></tr><tr><td>40 – 44</td><td>51%</td></tr><tr><td>&gt;45</td><td>93%</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-048c98d0', 't-mm-07-001', 'html', '<h3><strong> CAUSES OF RPL AND THEIR MANAGEMENT</strong></h3>
<ul><li><strong>APLA:</strong></li><li>15%  of RPL.</li><li>2% in healthy pregnancies.</li><li>80% success after t/m.</li><li>10% without t/m.</li></ul>
<p><strong>Work up:</strong><strong> </strong>offer prior to pregnancy – 2+ve test 12 weeks apart and at least 6 weeks post miscarriage.</p>
<ul><li><strong>Criteria of workupCriteria of workup</strong><strong>Criteria of workup</strong><strong>Criteria of workup</strong>&gt;3 – 1st miscarriage before 10 weeks.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
