INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3f856296', 't-mm-07-001', 'html', '<ul><li>USG + HSG – initial screening</li><li>3D USG is the diagnostic test</li></ul>
<h3><strong>Treatment</strong><strong>:</strong></h3>
<p>Hysteroscopic septostomy – Audit /Research context.</p>
<ul><li><strong>Cervical</strong><strong> anomaly</strong><strong>:</strong></li><li>Cause 2nd miscarriages, premature ruptured membranes or painless dilation.</li></ul>', 15) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2f80865d', 't-mm-07-001', 'image', '/uploads/content-images/maternal_mind_book/image83.emf', 16) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-469b9d43', 't-mm-07-001', 'html', '<h3><strong>Workup:</strong></h3>
<ul><li>One 2nd miscarriage or suspected Cervical weakness.</li><li>USG measurement of Cervix.</li><li>Serial measurements from 16 weeks to 24weeks.</li></ul>
<h3><strong>Treatment</strong><strong>:</strong><strong> </strong></h3>
<h3><strong>C</strong><strong>ervic</strong><strong>al</strong><strong> cerclage</strong></h3>
<p>1.ultrasound indicated cerclage if length is ≤2.5mm</p>
<h3>2.History indicated cerclage:</h3>
<p>3 or more 2nd trimester miscarriages</p>
<p>1 or more PTB</p>
<ul><li><strong>Abdominal Cerclage:</strong></li><li>Failed Cerclage.</li><li>Very Short or scarred Cervix.</li><li><strong>Inherited</strong><strong> Thrombophilia</strong><strong>:</strong></li><li>Carrier of factor v, prothrombin gene mutation – double risk.</li><li>Antithrombin 3 deficiency is rare yet most thrombogenic mutation associated with sporadic miscarriage.</li><li>Thrombophilia testing may be offered to women with 2nd trimester miscarriage.</li></ul>
<h3><strong>Work up:</strong></h3>
<ul><li>One 2nd miscarriage.</li></ul>', 17) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
