INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-54808b52', 't-mm-07-001', 'html', '<ul><li>Factor V Leiden.</li><li>Factor II - prothrombin gene mutation</li><li>Protein S deficiency</li></ul>
<p><strong>Treatment</strong><strong>:</strong> - 86% success in 2nd with LMWH</p>', 19) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
