INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-580f7631', 't-mm-08-008', 'html', '<ul><li>B.P &gt; 160.</li><li>Creatinine &gt;1mg/mmol.</li><li>ALT &gt;70 Or twice upper (N).</li><li>PLT &lt;150,000.</li><li>Signs of impending Eclampsia.</li><li>Signs of Eclampsia.</li></ul>
<p>Suspected fetal compromise</p>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6678130f', 't-mm-08-008', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>HTN</strong><br/>HTN &lt;160/110</td><td><strong>Severe HTN</strong><br/>B.P &gt; 160/110</td><td><strong>Pre eclampsia</strong><br/>B.P &lt; 160/110</td><td><strong>Severe </strong><strong>E</strong><strong>clampsia</strong><br/>B.P &gt; 160/110</td></tr><tr><td>Admission</td><td>* Not required</td><td>Admit till B.P &lt; 160/110</td><td>Admit if clinical concerns.</td><td>Admit till B.P &lt;160/110.</td></tr><tr><td>Anti-hypertensive</td><td>B.P &gt; 140/90</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Target B.P</td><td>135/85 or less</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>B.P monitoring</td><td>1 – 2 times/ week<br/>(weekly)</td><td>Every 15 – 30 min till B.P &lt;160/110</td><td>Twice/ thrice weekly (every 48 hours)</td><td>15 – 30 min till B.P &lt;160/110 then 4 hourly.</td></tr><tr><td>Proteinuria</td><td>1 – 2/ week</td><td>Daily while admitted</td><td>Repeat if clinically indicated</td><td>If clinically indicated.</td></tr><tr><td>Blood Testing</td><td>Weekly</td><td>Weekly</td><td>twice/ week</td><td>thrice/ week</td></tr><tr><td>PIGE Testing</td><td>20 – 35 weeks</td><td>20 – 35 weeks</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>Fetal Assessment:</strong></td></tr><tr><td>FHR Auscultation</td><td>Every visit</td><td>Every visit</td><td>Every visit</td><td>Every visit</td></tr><tr><td>CTG</td><td>If clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td></tr><tr><td>USG</td><td>2 – 4 weeks</td><td>2 weeks</td><td>2 weeks</td><td>2 weeks</td></tr><tr><td><strong>Timing of Birth:</strong><strong> </strong>discussed below</td></tr><tr><td><strong>Post Natal</strong><strong> care </strong><strong> </strong></td><td>Ask about Epigastric pain and headache while checking B.P.</td></tr><tr><td>B.P monitoring</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Daily for</td><td>2 days</td><td>2 days</td><td><strong>On treatment:</strong><br/>4 hourly during admission<br/>Every day or alternate days till 2weeks<br/><strong>Without Treatment:</strong><br/>4 hourly during admission<br/>Once for 3 – 5 days<br/>Alternate days till B.P is normal</td></tr><tr><td>Once for next</td><td>3 – 5 days</td><td>3 – 5 days</td><td>&nbsp;</td></tr><tr><td>Once on day</td><td>15</td><td>15</td><td>&nbsp;</td></tr><tr><td>Once in</td><td>6 – 8 weeks</td><td>6 – 8 weeks</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Start Anti-Hypertensive if</td><td>B.P &gt; 150/100</td><td>B.P &gt; 150/100</td><td>B.P &gt; 150/100<br/>B.P &lt; 130/80<br/>*  48 – 72 hours after Birth.<br/>Normal =&gt; no need to repeat.<br/>U/A: 6 – 8 weeks =&gt; repeat 3m0 Postnatal.</td></tr><tr><td>Target B. P</td><td>B.P &lt; 130/80</td><td>B.P &lt; 130/80</td><td>&nbsp;</td></tr><tr><td>Hematological Tests</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3265c086', 't-mm-08-008', 'html', '<p>Table 31. HTN in Pregnancy</p>
<h3><strong>Timing of Delivery:</strong></h3>
<ul><li><strong>CH HTN and Gestational Hypertension, </strong>B.P &lt;160/100, Delivery not before 37 weeks</li><li>Delivery after 37 weeks according to obstetric review and women choices</li><li><strong>Pre – Eclampsia and B.P &gt;160/110: </strong>Formulate birth plan</li></ul>
<h3><strong>* Decision Making Factors</strong><strong> for timing of birth</strong><strong>:</strong></h3>
<ul><li>Uncontrolled B.P despite 3 classes of antihypertensive with appropriate doses.</li><li>O2 sat &lt; 90%</li><li>Progressive deterioration in LFT’S, RFT’S, hemolysis, low Plt.</li><li>Ongoing neurological symptoms.</li><li>Abruption.</li><li>REDF in U/A Doppler.</li><li>Non – reassuring CTG/ Still birth.</li></ul>
<h3><strong>* Team Involved in Decision</strong><strong> Making</strong><strong>:</strong></h3>
<ul><li>Senior Obstetrician.</li><li>Anesthetist.</li><li>Neonatologist.</li></ul>
<h3><em><strong>Offer:</strong></em></h3>
<ul><li>Steroid and mgso4 in pre – Term babies before 37 weeks.</li></ul>
<h3><em><strong>Timing:</strong></em></h3>
<ul><li>Before 37 weeks if any of above worsening factor.</li></ul>
<h3><em><strong>After 37:</strong></em></h3>
<ul><li>Initiate within 24 – 48 hours.</li></ul>
<h3><strong>Fetal Monitoring:</strong></h3>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9900e316', 't-mm-08-008', 'html', '<table><tbody><tr><td><strong>USG</strong></td><td><strong>CH HTN</strong></td><td><strong>Gest HTN</strong></td><td><strong>Severe HTN + PE</strong></td></tr><tr><td>- Biometry (growth)<br/>+ AFI<br/>+ U/A Doppler</td><td>28weeks<br/>32 weeks<br/>36 weeks</td><td>@ diagnosis then every 2 weeks.</td><td>@ diagnosis then every 2 weeks.</td></tr><tr><td>CTG</td><td>If clinically indicated</td><td><strong>USG, EFW, AFI, U/A Doppler.@ between 28 – 30 weeks or 2 weeks before previous event.Repeat: 4 weekly if (N).USG, EFW, AFI, U/A Doppler.@ between 28 – 30 weeks or 2 weeks before previous event.Repeat: 4 weekly if (N).</strong><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong>@ between 28 – 30 weeks or 2 weeks before previous event.<strong>Repeat:</strong> 4 weekly if (N).<strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong>@ between 28 – 30 weeks or 2 weeks before previous event.<strong>Repeat:</strong> 4 weekly if (N).If clinically indicated<br/><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong><br/>@ between 28 – 30 weeks or 2 weeks before previous event.<br/><strong>Repeat:</strong> 4 weekly if (N).<br/><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong><br/>@ between 28 – 30 weeks or 2 weeks before previous event.<br/><strong>Repeat:</strong> 4 weekly if (N).</td><td>@ diagnosis repeat if clinically indicated or:<br/>-  RFM<br/>- Bleeding.<br/>- Abd pain.<br/>- deterioration of maternal condition.</td></tr></tbody></table>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-969fc8c0', 't-mm-08-008', 'html', '<h3><strong>Women with</strong><strong> previous</strong><strong> History of:</strong></h3>
<ul><li>Severe pre-eclampsia</li><li>PE resulted in Birth</li><li>Before 34 weeks.</li><li>IUGR &lt; 10th centile.</li><li>IUD.</li><li>Abruption.</li></ul>
<p>Offer usg for EFW,AFI and umbilical artery doppler @between 28-30 weeks or 2 weeks before the previous event. Repeat after 4 weeks if results are normal</p>
<h3><strong>Management in </strong><strong>critical</strong><strong> setting:</strong></h3>
<ul><li>Severe HTN, severe Pre-eclampsia, history of fits, planned birth in 24 hours =&gt; I/V Mgso4</li><li>Give Mgso4 in pre-eclampsia with any of following</li><li>1.Ongoing headache</li><li>2.Visual scotoma.</li><li>3.Nausea vomiting.</li><li>4.Epigastric pain.</li><li>5.Oliguria/ Severe HTN.</li><li>6.Progressive deterioration</li><li>of lab tests.</li></ul>
<p><strong>Eclampsia</strong><strong> </strong><strong>Mgso4</strong><strong> Loading</strong>4g I/V in 5 – 15 min.</p>
<p><strong>Maintenance</strong> 1g/hr./24 hours of last fit.</p>
<p><strong>Repeat fit</strong>2 – 4g repeat Bolus.</p>
<h3><strong>Regional An</strong><strong>a</strong><strong>esthesia:</strong></h3>
<ul><li>Low dose epiduraldon’t preload in severe PE</li><li>Combine spinal epidural</li></ul>
<h3><strong>Anti – Hypertensives:</strong></h3>
<h3><strong>* </strong><strong>A</strong><strong>ntenatal</strong><strong> Period:</strong></h3>
<ul><li>1st line – labetalol (C/I in Asthma).</li><li>2nd line – nifedipine (C/I with Mgso4).</li><li>3rd line – Methyldopa, (C/I in PP period).</li></ul>
<h3><strong>* </strong><strong>P</strong><strong>ostnatal</strong><strong>:</strong></h3>
<ul><li>Enalapril – Breast Feeding friendly.</li><li>Nifedipine/amlodipine.</li><li>Combination of enalapril + Nifedipine.</li><li>Add atenolol Labetalol to combination</li><li>Mildly exerted in breast milk.</li><li>Ask women to look for signs of drowsiness paler, Feeding problem in baby.</li><li>Check B.P of baby.</li></ul>
<p><strong>HELLP</strong> is a cause of 3 – 15% of Aki.</p>
<h3><strong>Recurrence of hypertension</strong></h3>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2542ce6d', 't-mm-08-008', 'html', '<table><tbody><tr><td><strong>Recurre</strong><strong>nce</strong><strong>:</strong></td><td>In current/ previous pregnancy</td></tr><tr><td>In future pregnancy</td><td>HTN</td><td>Pre-eclampsia</td><td>Gest HTN</td></tr><tr><td>HTN</td><td>21%</td><td>20%</td><td>22%</td></tr><tr><td>Pre-eclampsia</td><td>14%</td><td>- 16% overall - birth before 34 weeks 33%<br/>- after 34 – 37 weeks 23%.</td><td>7%</td></tr><tr><td>Gest HTN</td><td>9%</td><td>6 – 12%</td><td>11 – 15%</td></tr><tr><td>Chronic HTN</td><td>4%</td><td>2%</td><td>3%</td></tr></tbody></table>', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-009', 'chap-mm-08-01', '9.LOW DOSE ASPIRIN + CALCIUM SUPPLEMENTATION FOR PREVENTION OF PRE – ECLAMPSIA', 'Detailed medical reference and study guide on 9.LOW DOSE ASPIRIN + CALCIUM SUPPLEMENTATION FOR PREVENTION OF PRE – ECLAMPSIA.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e1f0e607', 't-mm-08-009', 'html', '<ul><li>Pre – Eclampsia = 3 – 5%, 50,000 deaths/ year in the world.</li><li>Impaired placentation 8 – 18 weeks.</li></ul>
<h3><strong>Screening for </strong><strong>Pre – Eclampsia</strong><strong>:</strong></h3>
<p><em><strong>* History:</strong></em><em><strong> </strong></em><em>with 10% false positive detection</em></p>
<ul><li>Pre – Eclampsia detection 47%.</li><li>Gest Hypertension detection = 35%</li></ul>
<h3><em><strong>* History + MAP</strong></em><em><strong> (Mean Arterial Pressure)</strong></em><em><strong>:</strong></em></h3>
<ul><li>Pre – Eclampsia – 60%.10% false</li><li>G.H 40%positive</li></ul>
<h3><em><strong>* History + Pla</strong></em><em><strong>cental Mar</strong></em><em><strong>ke</strong></em><em><strong>r</strong></em><em><strong>s:</strong></em></h3>
<p>PLGF, PAPPA – A</p>
<ul><li>Early Pre – Eclampsia – 80%    10% false</li><li>Late Pre – Eclampsia 64%.          positive</li><li>G.H 39%.</li></ul>
<h3><em><strong>* History + MAP + UA Doppler + p</strong></em><em><strong>la</strong></em><em><strong>cen</strong></em><em><strong>tal ma</strong></em><em><strong>r</strong></em><em><strong>kers:</strong></em></h3>
<ul><li>Early Pre – Eclampsia 88.5%.    10% false</li><li>Late Pre – Eclampsia 46.7%     positive</li><li>G.H 35.5%</li></ul>
<h3><em><strong>* </strong></em><em><strong>Placental</strong></em><em><strong> </strong></em><em><strong>Biomarkers</strong></em><em><strong> in prediction of pre-Eclampsia:</strong></em></h3>
<ul><li>PLGF</li><li>S – Flt 1 =</li><li>PAPPA =</li><li>SEND =</li><li>VEGF =</li><li>HCG =</li><li>ADAM =</li></ul>
<h3><strong>Low dose Aspirin:</strong></h3>
<ul><li>More effective before 16 weeks</li><li>start after 12 weeks 75 – 150mg.</li><li>8% reduction in PTB.</li><li>14% reduction in neonatal death.</li><li>10% reduction in IUGR</li><li>17% reduction in Pre – Eclampsia</li></ul>
<h3><strong>Mechanism of Action of Aspirin:</strong></h3>
<p>Inhibits cyclooxygenase</p>
<p>Inhibit production of</p>
<p><em><strong>1. Prostacyclin</strong></em><em><strong>2. Thromboxane A2</strong></em></p>
<ul><li>Found in Endothelium       - Found in platelets</li><li>Cause Vasodilatation         - Vasoconstriction</li><li>Effects are reversible         - irreversible</li></ul>
<h3><strong>Ca</strong><strong>lcium</strong><strong> – Supplementation:</strong></h3>
<ul><li>After 20 weeks 1.5 – 2 g Elemental Calcium/day.</li><li>2 – 3 divided doses until delivery.</li><li>Target population – High risk for Pre – Eclampsia, Ca deficiency population.</li><li>Max dose 3000mg/day.</li></ul>
<h3><strong>Ca + Aspirin:</strong></h3>
<ul><li>Can be given simultaneously</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-010', 'chap-mm-08-01', '10.HEMOPHILIA', 'Detailed medical reference and study guide on 10.HEMOPHILIA.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d7c2c33e', 't-mm-08-010', 'html', '<ul><li>X – linked recessive disorders:</li><li>Type A – Absent or reduced Factor VIII.</li><li>Type B – Absent or reduced Factor IX.</li><li>Male affected 50%.If female</li><li>Female carrier 50%.is carrier</li><li>50% has no previous history</li><li>Spontaneous mutation in 40 – 50% cases</li><li>More mutations in spermatogenesis than oogenesis</li><li>In maternal Grand Father.</li><li>Factor VIII: VWF &lt;0.7 is suggestive of carriership</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><em><strong>Mild:</strong></em> .06 – 0.40IU/mlbleeding after</li><li><em><strong>Mod:</strong></em> 0.01 – 0.5 trauma</li><li><em><strong>Severe:</strong></em> &lt; 0.01 – spontaneous bleeding in Joints and muscles.</li></ul>
<p><strong>Carriers:</strong>  risk of bleeding during invasive procedures, TOP, C/S, SVD when levels between 0.4 – 0.6.</p>
<p><strong>Neonate</strong><strong>s:</strong> Male at risk of ICH, ECH, iatrogenic haemorrhage.</p>
<h3><strong>Pre – </strong><strong>Pregnancy Management:</strong></h3>
<ul><li>Monitor levels before pregnancy.</li><li>Correct weight and iron deficiency =&gt;    ed bleeding risk.</li><li>Genetic counselling + genetic testing of partner.</li><li>Written informed consent before genetic Testing.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>MDT management of pregnancy</li><li><strong>P</strong><strong>renatal diagnosis</strong> – all carriers of severe hemophilia</li><li>9 weeks CFFDNA in all pts to determine sex.</li><li>If male fetus then determine hemophilia status by</li><li>1.CVS at 11 – 14 weeks.</li><li>2.Amniocentesis in 3rd</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
