INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-015', 'chap-mm-08-01', '15.MYOCARDIAL INFARCTION IN PREGNANCY', 'Detailed medical reference and study guide on 15.MYOCARDIAL INFARCTION IN PREGNANCY.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-97d423da', 't-mm-08-015', 'html', '<ul><li>Increased mortality if delivery occurs within 2 weeks.</li><li>increased mortality if MI occurred in last stages of pregnancy.</li><li>Cardiovascular disease = 0.2 – 4% of all pregnancies.</li><li>In pregnancy – MI risk is increased 3 – 4 times.</li><li>50% during peripartum.</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><em><strong>STEMI</strong></em></li><li><em><strong>NSTEMI.</strong></em></li></ul>
<h3><strong>Physiological changes </strong><strong>In pregnancy:</strong></h3>
<ul><li>Cardiac output and blood volume are increased, maximum @ 25 – 32weeks.</li><li>Prothrombotic state returns after 8 weeks.</li><li>HDL decreases</li><li>48 hours after delivery, Diuretic and natriuretic states.</li></ul>
<h3><strong>Normal in Pregnancy:</strong></h3>
<ul><li>15 – 200 left deviations.</li><li>ST – depression.</li><li>T – wave inversion in inferior and lateral leads.</li><li>Q in AVF</li><li>Inverted T waves in –V1, V2, V3</li></ul>
<h3><strong> Causes of Mi</strong></h3>
<ul><li>Atherosclerosis = 50%</li><li>CA thrombosis = 14%.</li><li>CA spasm = 14%.</li><li>CA dissection (in women with no cardiovascular risks) =22%</li><li>CA = Coronary Artery</li></ul>
<p>80% of MI =&gt; left anterior descending branch – Mortality 30 – 40%.</p>
<h3><strong>Investigations:</strong></h3>
<p><strong>1.</strong><strong>ECG:</strong> 1st line 50% sensitivity</p>
<ul><li>Serial ECG are fundamental.</li></ul>
<h3>ECG changes in Acute MI:</h3>
<ul><li>ST – elevation.</li><li>ST – depression.</li><li>T – wave invasion</li><li>Newly developed Q waves.</li></ul>
<h3><strong> 2.</strong><strong>Cardiac Makers:</strong></h3>
<ul><li>Troponins</li><li>investigation of choice.</li><li>Unchanged during labor, delivery and anaesthesia.</li><li>Others: CK MB, myoglobin are non – specific.</li></ul>
<p><strong> 3.</strong><strong>Echo</strong> – safe.</p>
<p><strong> 4.</strong><strong>Angiography</strong> – Radial access is recommended.</p>
<ul><li><strong>STEMI (ST elevation Myocardial infarction).</strong></li><li>Complete occlusion of vessels.</li></ul>
<h3><em><strong>Treatment:</strong></em></h3>
<ul><li>Coronary angiography and primary percutaneous coronary intervention PCCI.</li><li>Thrombolysis by Tpa, don’t cross placenta.</li><li>Risk of maternal bleeding.</li><li><strong>NSTEMI</strong><strong> (</strong><strong>Non-ST</strong><strong> elevation Myocardial Infarction)</strong><strong>:</strong></li><li>Partial occlusion of vessels.</li><li>Medical treatment 1st line:</li><li>Aspirin</li><li>LMWH.</li><li>Nifedipine.</li><li>Labetalol</li><li>Clopidogrel +</li><li>Stenting = 2nd line</li><li>If symptoms continue on medical treatment.</li><li>Hemodynamic instability.</li></ul>
<h3><strong>Timing and MODE of delivery:</strong></h3>
<ul><li>Try to delay birth 2 – 3 weeks.</li><li>ICU care, MDT management</li><li>C/S less hemodynamic instability.</li><li>Slow syntocinon infusion &lt; 2IU/MIN.</li><li>1st stage left lateral.</li><li>O2 sat, vitals, ECG monitoring during labour and after delivery</li><li>Cut short 2nd stage of labor.</li><li>ICU monitoring 24 – 48 hours after birth.</li><li>MOD according to obstetric indication.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-016', 'chap-mm-08-01', '16.DERMATOLOGICAL CONDITIONS OF PREGNANCY', 'Detailed medical reference and study guide on 16.DERMATOLOGICAL CONDITIONS OF PREGNANCY.', 16, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-17968dd9', 't-mm-08-016', 'html', '<ul><li>Melasma 75%.</li><li>Spider nevi – 66% Caucasian, 11% black.</li><li>Pruritus- 18% with 80% recurrence.</li><li>Symmetrical lesion =&gt; endogenous cause.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8a6f238f', 't-mm-08-016', 'html', '<table><tbody><tr><td><strong>Dermatosis of  pregnancy</strong></td><td><strong>Affected area</strong></td><td><strong>Risk</strong><strong> factors</strong></td><td><strong>Recurre</strong><strong>nce</strong></td><td><strong>Management</strong></td><td><strong>Pregnancy outcome</strong></td></tr><tr><td>IHCP 0.7%</td><td>Scalp Anus, Vulva abdominal skin.</td><td>*Ethnicity: more in India,<br/>Pakistan.<br/>*Previous IHCP</td><td>60 – 70%</td><td>* Urso<br/>* Topical emollients.<br/>* Sedating anti histamine.<br/>* Water soluble vitamin K</td><td>Risk of:<br/>* IUD<br/>* Meconium<br/>* PPH.<br/>* Fetal distress.<br/>* C/S prematurity.</td></tr><tr><td>Atopic eruption of pregnancy:<br/>* Prurigo gestationis.<br/>* Prurigo Folliculitis.<br/>* Eczema of Pregnancy.<br/>* Nurse early onset Prurigo.<br/>Risk is 1/300</td><td>Erythematous/ excoriated<br/>nodules.<br/>Papules on<br/>Face, Neck, Chest<br/>Extensor surfaces.<br/>* Immune mediated.<br/>* Clinical diagnosis.</td><td>Family History</td><td>Limited data</td><td>* Topical emollients.<br/>* Anti pruritus.<br/>* Topical steroids<br/>* Anti Histamine, UV light.<br/>* 1% Menthol.<br/>* Benzoyl per oxide.<br/>* Erythromycin,<br/>* Zinc.</td><td>No Adverse effects.</td></tr><tr><td>* Polymorphic eruption of pregnancy PEP<br/>* 1/160 –1/300.<br/>*Pruritic, urticarial papules/ plaques of pregnancy.<br/>* Toxic erythema.<br/>* Nurse late onset.</td><td>Periumbilical sparing + sparing of palms, soles and face</td><td>PG, twins over distention.</td><td>Rarely occur</td><td>* Topical steroids (1st line)<br/>* Emollients.<br/>* Oral steroids.<br/>* Anti Histamine.</td><td>No adverse effect.</td></tr><tr><td>* Pemphigoid Gestationis<br/>* 1/700-1/50’000.<br/>* Herpes Gestationis.<br/>* Bullous pemphigoid.<br/>* Gestationis<br/>Pemphigoids.</td><td>* Bullous eruption.<br/>* Appears around umbilicus unlike PEP.<br/>* Mucosal sparing.<br/>* All over the body.<br/>* Biopsy necessary.<br/>* Two samples:<br/>1. Biopsy.<br/>2. Immune studies.<br/>* Flare @ time of delivery</td><td>Immunological HLA – DR3, DR4.</td><td>* Recurrence with earlier onset and increasing severity.<br/>* Recurrence with OCP and periods.</td><td>* Topical/ Oral steroid.<br/>* Anti Histamines<br/>* Antibiotics.<br/>* Immunosuppressive drugs.</td><td>* IUGR.<br/>* Pre – Term.<br/>* self-limiting.<br/>* Skin lesion in Neonates.</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
