INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-019', 'chap-mm-08-01', '19.PKU - PHENYLKETONURIA', 'Detailed medical reference and study guide on 19.PKU - PHENYLKETONURIA.', 19, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7be1214a', 't-mm-08-019', 'html', '<ul><li>Autosomal Recessive 1/10,000.</li><li>More in Turkish &amp; Irish ethnicity.</li><li>Deficiency of PAH phenylalanine hydroxylase enzyme.</li><li>PKU – most common in born error of Metabolism.</li><li>Phenylalanine is converted to – tyrosine with the help of enzyme PAH.</li></ul>
<h3><strong>PKU in Maternal blood Causes</strong><strong>:</strong></h3>
<ul><li>IUGR</li><li>Heart defects 7 – 10%</li><li>Development defects</li><li>Rash</li><li>Microcephaly.</li><li>Facial dysmorphism =&gt; like FAS (fetal Alcohol syndrome).</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><em><strong>Classical</strong></em><strong>:</strong></li><li>Absent PAH.</li><li>Phenylalanine levels &gt; 1200 µmol/L</li><li><em><strong>Non – Classical:</strong></em></li><li>Mild to moderate PAH.</li></ul>
<h3><strong>Pathogenesis:</strong></h3>
<ul><li>Phenylalanine level – cross placenta.</li><li>Teratogenesis, behavioral/ developmental problems.</li><li>Tyrosine -&gt;    melanin -&gt; fair skin, blue eyes.</li></ul>
<h3><strong>Treatment of PKU:</strong></h3>
<ul><li>Phenylalanine restricted diet (avoid animal proteins).</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Pre – pregnancy: Contraception till optimal Phenylalanine levels.</li><li>Target phenylalanine (120 – 300 µmol/l).</li><li>Discontinue contraception if phenylalanine level &lt; 350.</li><li>Allow pregnancy when 3 – 4 levels of Phenylalanine &lt; 350.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>Phenylalanine level 3 times/ week.</li><li>MDT:</li><li>Dietitian.</li><li>Obstetrician</li><li>Midwife.</li><li>Amino acid, trace minerals.</li><li>@ Smoking &amp; 20 – 22weeks.</li><li>Tyrosine supplementation after 16 weeks.</li></ul>
<p>Dairy egg, chicken, fish, Beans, Oats, Wheats, nuts.</p>
<ul><li>Weight gain = microcephaly</li><li>Link between weight gain and microcephaly.</li></ul>
<p><strong>Delivery:</strong> obstetric indication.</p>
<p><strong>Unplanned pregnancies:</strong> Anomaly scan @ FMU.</p>
<h3><strong>Fetal Monitoring</strong><strong>:</strong></h3>
<ul><li>Anomaly scan.</li><li>Echo</li><li>Doppler – IUGR.</li></ul>
<h3><strong>Microcep</strong><strong>ha</strong><strong>ly:</strong></h3>
<ul><li>Diagnosed @ 28 weeks.</li><li>HC &lt; 2.5 SD = Suspect.</li><li>HC &lt; 5.5 SD = Confirmed.</li><li>Breast Feeding safe.</li></ul>
<h3><strong>Neonatal PKU:</strong></h3>
<ul><li>Testing @ D – 5.</li></ul>
<h3><strong>Psychological Assessment:</strong></h3>
<ul><li>@ 18 months.</li><li>Then @4, 8 and 14 years.</li><li>To access cognition and behavior.</li><li>Dietary restriction for 5 – 6 years.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-020', 'chap-mm-08-01', '20.IBD – INFLAMMATORY BOWEL DISEASE', 'Detailed medical reference and study guide on 20.IBD – INFLAMMATORY BOWEL DISEASE.', 20, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-539ea9ab', 't-mm-08-020', 'html', '<ul><li>50% diagnosed before 35 years.</li><li>Relapse in pregnancy = 30% most in early pregnancy.</li><li>25% patient with IBD conceive</li></ul>
<h3><strong>C</strong><strong>auses of </strong><strong>Sub</strong><strong>fertility</strong><strong>:</strong></h3>
<ul><li>Tubal occlusion.</li><li>Ovarian dysfunction.</li><li>Dyspareunia.</li></ul>
<h3><strong>Risk in Pregnancy:</strong></h3>
<ul><li>Miscarriage.</li><li>Low birth.</li><li>PTL.</li><li>Periosteal cracking + Bleeding.</li><li>Intestinal obstruction.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>S/S.</li><li>CBC, CRP, ESR.</li></ul>
<h3><strong>Fecal</strong><strong> calprotectin:</strong></h3>
<ul><li>Non-invasive marker of disease activity during pregnancy.</li><li>Don’t differentiate between infection and IBD.</li><li>Indicate neutrophilic breakdown in stool.</li></ul>
<h3><strong>USG:</strong></h3>
<ul><li>Imaging of choice.</li></ul>
<h3><strong>MRI:</strong></h3>
<ul><li>Without contrast in complex cases.</li><li>In 2nd /3rd  where USG inconclusive.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-fd1a84b1', 't-mm-08-020', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-76372b02', 't-mm-08-020', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a8457dec', 't-mm-08-020', 'html', '<h3><strong>Abd X – RAY: </strong></h3>
<ul><li>Colonic dilatation and Acute severe colitis.</li></ul>
<p><strong>CT:</strong><strong> </strong>not done routinely</p>
<h3><strong>Gastro</strong><strong>scopy, Colonoscopy</strong><strong>, Sigmoidoscopy:</strong></h3>
<ul><li>Safe.</li></ul>
<h3><strong>Pre – pregnancy counselling:</strong></h3>
<ul><li>Mycophenolate mofetil, Metho stop 3m0 before.</li></ul>
<h3><strong>Nutritional Supplements:</strong></h3>
<ul><li>Vitamin B12, D, proteins, fats, iron folate.</li><li>Correct prior to conception.</li></ul>
<h3><strong>Drugs:</strong></h3>
<ul><li><em><strong>Amino salicylates:</strong></em> category B drug</li><li>Up to 3g/day =&gt; fetal nephrotoxic.</li><li>High dose folic acid, 5mg.</li><li>Bloody diarrhea in infants with mesalazine.</li><li><em><strong>Metro</strong></em><em><strong>nidazole</strong></em><em><strong>:</strong></em> In perineal Crohn’s disease + initial flare.</li><li><em><strong>Steroids:</strong></em> hydrocortisone during labor.</li><li><em><strong>Azathioprine:</strong></em><em><strong> </strong></em>safe</li><li><em><strong>Calcineurin</strong></em><em><strong> inhibitors:</strong></em> fulminant colitis.</li><li><em><strong>Biologics:</strong></em> avoid live vaccination in babies until levels are undetectable.</li><li><em><strong>Mycoph</strong></em><em><strong>e</strong></em><em><strong>nola</strong></em><em><strong>te:</strong></em> category X</li><li><em><strong>Metho:</strong></em> category X</li></ul>
<h3><strong>Labor &amp; Delivery:</strong></h3>
<ul><li>Avoid episiotomy in perianal disease.</li><li>Elective CS is preferred over emergency CS.</li><li>Opiates =&gt; constipation so give osmotic laxative with opiates.</li></ul>
<p><strong>VTE:</strong> Score 3</p>
<p>Post-partum depression – 3 times     risk.</p>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-021', 'chap-mm-08-01', '21.EPILEPSY', 'Detailed medical reference and study guide on 21.EPILEPSY.', 21, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b6fa5f60', 't-mm-08-021', 'html', '<ul><li>Maternal mortality10 Fold in WWE.</li><li><strong>WWE:</strong> women with epilepsy.</li><li>Incidence 0.5 – 1%</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><em><strong>Tonic Clonic:</strong></em></li><li>Highest risk of SUDEP.</li><li>Sudden loss of conscious and fell without warning symptoms.</li><li><em><strong>Absence </strong></em><em><strong>seizure</strong></em><em><strong>.</strong></em></li><li>Worsening absence =&gt;    risk of tonic – colonic.</li><li><em><strong>Juvenile: </strong></em></li><li>Sudden Jerks -&gt; falling of baby.</li><li><em><strong>Focal </strong></em><em><strong>seizure</strong></em><em><strong>:</strong></em></li><li>Complex partial – with loss of consciousness.</li><li>Simple partial – without unconsciousness.</li><li>Involve Neurologist -&gt; if diagnostic uncertainty.</li></ul>
<h3><strong>No longer </strong><strong>have Epilepsy</strong><strong>:</strong></h3>
<ul><li>Seizure free &gt; 10 years.</li><li>Last 5 years without treatment.</li><li>Childhood epilepsy syndrome.</li></ul>
<h3><strong>Pre – pregnancy counselling:</strong></h3>
<ul><li>Folic acid 5mg 3m0 before – continue throughout pregnancy.</li><li>Monotherapy or less teratogenic drugs.</li><li>Avoid sodium valproate -&gt; change to safe drug</li><li>Multi drug change to Monotherapy</li><li>Lamotrigine, carbamazepine – No effect on Neurodevelopment.</li><li>Lowest effective dose of most appropriate AED 2/3rd = No fit in pregnancy.</li><li>&lt; 1 year of last fit =&gt; close monitoring.</li></ul>
<p>Safe =&gt; lamotrigine, carbamazepine, levetiracetam.</p>
<h3><strong>Anomalies:</strong></h3>
<ul><li>1 drug = 6 – 7%.</li><li>2 drugs = 15%.</li><li>3 drugs = 50%.</li></ul>
<h3><strong>Anomalies Risk:</strong></h3>
<ul><li>WWE = 28%.</li><li>Sodium valproate = 10.7%.</li><li>Poly therapy = 16.8%.</li><li>WWE with previous affected child = 16.8%.</li><li>Na – valproate = NTD, facial cleft, hypospadias.</li><li>Phenobarbital + phenytoin cardiac defects.</li><li>Phenytoin + carbamazepine = cleft palate, cleft lip</li></ul>
<h3><strong>Effect of Epilepsy</strong><strong> on Pregnancy:</strong></h3>
<ul><li>Seizure free – 67%</li><li>ed frequency – 17%.</li><li>Frequency – 16%.</li><li>Intrapartum seizure – 3.5%.</li><li>Status Epilepticus – 2%.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>Anomaly Scan 18 – 21 weeks.</li></ul>
<h3><strong>Drugs Monitoring:</strong></h3>
<ul><li>In special circumstances not routinely lamotrigine level   up to 70% =&gt;   risk of seizures.</li></ul>
<p><strong>Current practice:</strong><strong> </strong>to adjust the dose is</p>
<ul><li>Either monitor regularly</li><li>Or adjust according to clinical features</li></ul>
<h3><strong>Maternal Monitoring:</strong></h3>
<ul><li>Sleep.</li><li>Dehydration.</li><li>AED adherence.</li><li>Seizure type and frequency.</li></ul>
<p>No role of antenatal vitamin K to mother, given only to high risk of Haemorrhagic disease of new born.</p>
<p>Delivery according to obstetric indications.</p>
<p>Regular dose steroids (in enzyme inducers double dose).</p>
<h3><strong>Fetal:</strong></h3>
<ul><li>Serial growth scan from 28 weeks.</li></ul>
<h3><strong>IPC:</strong></h3>
<ul><li>1 – 2% risk of fits during labour</li><li>Avoid precipitating factors – continue AED.</li><li><strong>Clobazam</strong> – long-acting benzodiazepine</li><li>If risk of fits is highest.</li><li>Prophylactic clobazam during Labor:</li><li>Fits in previous labor.</li><li>History of fit with stress.</li><li>History of recurrent fits</li><li>Benzodiazepine – drug of choice during labor.</li><li>CEFM – high risk of fits or after fits.</li><li>Intermittent – low risk pts (10year fit free or 5 years without mediation).</li></ul>
<h3><strong>Seizures</strong><strong>:</strong></h3>
<ul><li>5 min =&gt; high risk for progression to status.</li><li>1% individuals with epilepsy present with status.</li><li>Medical emergency</li><li>Left lateral.</li><li>Lorazepam/ Diazepam/ Midazolam</li><li>Not controlled</li><li>Phenytoin.</li></ul>
<p><strong>Uncontrolled seizure</strong><strong>s</strong> lead to</p>
<h3><strong>hypertonus uterus</strong><strong>:</strong></h3>
<ul><li>Tocolytics</li></ul>
<p>-CEFM</p>
<p>Abnormal CTG not recovering to normal after 5 min or recurrent fits are indications of Emergency c/s</p>
<h3><strong>An</strong><strong>a</strong><strong>esthesia/ Analgesia</strong></h3>
<h3><em><strong>Avoid: </strong></em></h3>
<ul><li>Pethidine.</li><li>Ketamine.</li><li>Sevoflurane.</li></ul>
<h3><strong>U</strong><strong>se</strong><strong>:</strong></h3>
<ul><li>No, TENS,</li><li>Regional anaesthesia, diamorphine.</li></ul>
<h3><strong>PNC:</strong></h3>
<ul><li>Vitamin K injection to Neonates.</li><li>Continue AED</li><li>Sodium Valproate, Carbamazepine, phenytoin =&gt; minimum transfer in milk.</li><li>Lamotrigine, Levetiracetam, topiramate =&gt;   transfer in milk.</li><li>If AED   ed during pregnancy =&gt; reviewed within 10 days of delivery to avoid toxicity.</li><li>Highest risk of fits =&gt; postpartum.</li><li>1 – 2% postpartum</li><li>3.5% (according to TOG article).</li></ul>
<h3><strong>B.F:</strong></h3>
<ul><li>Lamotrigine 50% excretion in milk – so breast feeding before taking dose.</li><li>Other drugs 3 – 5% excretion.</li></ul>
<h3><strong>Contraception:</strong></h3>
<ul><li>IUD, Mirena, DMPA – not affected by Enzyme inducers, carbamazepine, topiramate, phenytoin, phenobarbital</li><li>COC, POP, implants, Patch, ring – affected by enzyme inducers.</li><li>Dose of Estradiol to 70mcg and reduce pill free interval from 7 – 4 days.</li><li><strong>Offer all Methods to Women taken:</strong></li><li>Sodium Valproate, levetiracetam, gabapentin, vigabatrin, pregabalin.</li><li>Emergency Contraception=&gt; IUD or 3mg LNG.</li><li>Don’t offer UPA.</li><li>COC    lamotrigine level 25 – 70% =&gt;    fits.</li></ul>
<p><strong>Enzyme inducers:</strong> CP3T</p>
<ul><li>Carbamazepine, phenytoin.</li><li>Primidone phenobarbital.</li><li>Topiramate.</li></ul>
<p><strong>Non-Inducers</strong><strong>:</strong> SL2</p>
<ul><li>Sodium Valproate, levetiracetam, lamotrigine.</li></ul>
<h3><strong>Non – epileptic Seizure disorders:</strong></h3>
<ul><li>Psychogenic most common</li><li>Associated with</li><li>Prolonged repeated seizures without cyanosis</li><li>Resistance to eye opening</li><li>Down going planters</li><li>Persistence of +ve conjunctival reflex</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-022', 'chap-mm-08-01', '22.CA BREAST IN PREGNANCY AND PREGNANCY FOLLOWING CA BREAST', 'Detailed medical reference and study guide on 22.CA BREAST IN PREGNANCY AND PREGNANCY FOLLOWING CA BREAST.', 22, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-054e7055', 't-mm-08-022', 'html', '<ul><li>1 in 9 women has life time risk.</li><li>Most common female cancer.</li><li>Leading cause of death in between age 35 – 54 years.</li><li>15% diagnosed before 45 years.</li><li>10 – 20% cases associated with pregnancy or occur within 1 years after birth.</li><li>5 Years survival 80% &lt;50 years of age.</li></ul>
<h3><strong>CA Breast Diagnosed During Pregnancy:</strong></h3>
<ul><li>Pregnancy itself don’t worse prognosis</li><li>Feeling of lump =&gt; refer to Breast specialist.</li><li>Testing in conjunction with MDT team.</li><li>Diagnosis:</li><li>USG – 1st line.</li><li>Mammography:</li><li>If cancer is confirmed, to assess the extent with shield.</li><li>Tissue Biopsy:</li><li>Not cytology because it is inconclusive in pregnancy due to normal proliferative changes.</li><li>H/P, receptor status, stage, Grade.</li><li>X – RAY chest and spine (bone involvement).</li><li>liver USG – if needed.</li><li>MRI with Gadolinium: done only if clinical concerns limited data on safety.</li><li>Tumor makers – Not recommended – As they are misleading (CA 15-3, CA -125).</li><li>CT, pelvic x - ray, NR as they have effect on baby.</li><li>TOP: MDT review.</li><li>Treatment: MDT.</li></ul>
<h3><strong>Surgical:</strong></h3>
<ul><li>Wide local excision.</li><li>Sentinel node biopsy, if pre -op USG and needle biopsy has negative results then do S.N Biopsy.</li><li>Avoid blue dye.</li><li>S.N biopsy =&gt; positive =&gt; axillary clearance.</li><li>MRM.</li><li>Reconstruction is delayed till delivery.</li></ul>
<h3><strong>Radio:</strong></h3>
<ul><li>C/I routinely.</li><li>If preservation of organ function is required like spinal cord compression by radio, then do with shield or after Iatrogenic delivery of baby.</li></ul>
<h3><strong>Chemo:</strong></h3>
<ul><li>C/I – 1st can be given in 2nd and 3rd .</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-783aa532', 't-mm-08-022', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a530b80d', 't-mm-08-022', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b349e0fb', 't-mm-08-022', 'html', '<ul><li>Anthracyclines safe in pregnancy</li><li>Left ventricular dysfunction.</li><li>Cardiomyopathy.</li><li>No evidence of</li><li>2nd  miscarriage</li></ul>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-90810449', 't-mm-08-022', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b41a4371', 't-mm-08-022', 'html', '<ul><li>IUGR.</li><li>long Term effect</li><li>5HT3, Steroids =&gt; for emesis</li><li>Tamoxifen and trastuzumab (HER 2 new) contraindicated in pregnancy and lactation.</li></ul>
<h3><strong>Birth:</strong></h3>
<ul><li>MDT.</li><li>Postpone delivery 2 – 3weeks after last chemo to avoid neutropenic crises.</li></ul>
<h3><strong>Lactation:</strong></h3>
<ul><li>B.F on chemo is C/I – as it causes leukopenia &amp; infection in neonates.</li><li>Otherwise offered short duration in between chemo (14days after chemo).</li></ul>
<h3><strong>CC:</strong></h3>
<ul><li>Avoid hormonal CC =&gt; consider after 5 years free of recurrence.</li></ul>
<h3><strong>Pregnancy Following CA – Breast:</strong></h3>
<ul><li>&lt;10% became pregnant following diagnosis of CA Breast:</li></ul>
<h3><strong>Pre pregnancy:</strong></h3>
<ul><li>Consult:</li><li>Oncologist.</li><li>Surgeon.</li><li>Obstetrician</li></ul>
<p>Stop tamoxifen 3m0 before (washout period) long half-life.</p>
<ul><li>CA with Mets =&gt; Avoid pregnancy as life expectancy is limited and treatment is compromised.</li><li>Pregnancy don’t adversely affect long term survival.</li><li>Avoid pregnancy till 2 years after treatment (highest time for recurrence).</li><li>Outcome of pregnancy after CA Breast No evidence available</li><li>Recommended tamoxifen treatment for CA Breast is 5 years.</li><li>Ed risk of C/section.</li><li>BRCA carrier =&gt; PGD.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>MDT.</li><li>Echo if risk of cardiomyopathy (on anthracycline, taxanes rare complication).</li></ul>
<h3><strong>PNC:</strong></h3>
<ul><li>B.F – from unaffected side.</li><li>Breast conserving surgery – don’t affect milk production from affected side.</li><li>Radio cause fibrosis – lactation not possible.</li></ul>
<h3><strong>Effect of treatment on Fertility:</strong></h3>
<ul><li>Discuss with all women, written information.</li></ul>
<h3><strong>Chemo:</strong></h3>
<p>gonadtoxicity esp. alkylating agents.</p>
<ul><li>Taxanes less gonadotoxic.</li><li>CMF (Cyclophosphamide, Metho, 5Floro)</li><li>=&gt; higher risk of amenorrhea.</li><li>FEC (5floro, epirubicin, cyclophosphamide) =&gt;less amenorrhea</li><li>Tamoxifen =&gt; Menstrual irregularity, Endometrial hyperplasia</li></ul>
<h3><em><strong>Amenorrhea</strong></em><em><strong> after chemo:</strong></em></h3>
<ul><li>&lt;30 years = 5%.</li><li>36 – 40 years = 50%.</li></ul>
<h3><strong>Fertility preservation Before treatment:</strong></h3>
<h3><strong>Cryopreservation:</strong></h3>
<ul><li>Egg or Embryo freezing.</li><li>Egg preservation for those with no partners otherwise embryo.</li><li>Embryo preservation success 20%.</li><li>Ovarian stimulation with tamoxifen or letrozole combined with gonadotrophins.</li><li>Ovarian tissue storage =&gt; research setting.</li></ul>
<h3><strong>ART after Treatment of C</strong><strong>A Breast:</strong></h3>
<ul><li>Loss of ovarian reserve due to treatment (chemo).</li><li>IVF =&gt; estrogenic state.</li><li>Egg donation if ovarian failure due to treatment.</li></ul>
<p>Surrogacy – where pregnancy is C/I</p>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-023', 'chap-mm-08-01', '23.DIABETES IN PREGNANCY', 'Detailed medical reference and study guide on 23.DIABETES IN PREGNANCY.', 23, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b5c763ad', 't-mm-08-023', 'html', '<h3><strong>Pre conception counselling:</strong></h3>
<ul><li>Individualized dietary advice.</li><li>Weight reduction if BMI &gt;27.</li><li>Folic acid 5mg till 12 weeks.</li><li>Monthly HbA1C:</li><li>Aim &lt; 48 mol/ mol – 6.5%.</li><li>C/I to pregnancy &gt; 86mol/mol – 10%.</li><li>Stop other mediation pre – conceptionally.</li><li>Retinal assessment (if not done within 6m0).</li><li>Renal assessment (if not done within 6m0).</li><li>Referral to nephrologist:</li><li>Serum Creatinine &gt; 1.2.</li><li>Albumin: Creatinine&gt; 30 mg/nmol.</li><li>GFR &lt; 45ml/min.</li></ul>
<h3><strong>Gest</strong><strong>ational</strong><strong> Diabetes:</strong><strong> </strong></h3>
<h3><strong>R.F:</strong></h3>
<ul><li>BMI &gt; 30 screening @ 24 – 28 weeks.</li><li>Previous baby wight &gt; 4.5k screening @ 24 – 28 weeks.</li><li>Previous GDM @ booking if normal then Repeat @ 24 – 28 weeks.</li><li>Family history screening @ 24 – 28 weeks.</li><li>Ethnicity screening @ 24 – 28 weeks.</li></ul>
<h3><strong>Glycosuria</strong><strong>:</strong></h3>
<ul><li>2+ on single event.</li><li>1 + on 2 occasions</li><li>Indicate GDM</li><li>Further Testing OGTT.</li></ul>
<h3><strong>OGTT:</strong></h3>
<ul><li>75g OGTT, 2hours duration</li><li>At Booking (1st, 2nd ) – with previous GDM.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2c685ff6', 't-mm-08-023', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-4c646b2b', 't-mm-08-023', 'html', '<ul><li>24 – 28 with previous normal OGTT.</li></ul>
<p>Fasting &gt; 5. 6 GDM refer to joint Diabetes</p>
<p>2 hours &gt; 7.8 clinic within 1 week of diagnosis</p>
<ul><li>Early self-monitoring – with previous history of GDM.</li></ul>
<h3><strong>Interventions:</strong></h3>
<ul><li>Education:</li><li>Fetomaternal risk.</li><li>Benefit of controlled BSL.</li><li>Self – monitoring of BSL.</li><li>Diet and exercise (walking 30min after meal daily).</li><li>Dietician Referral all women:</li><li><em><strong>Fasting BSL;</strong></em></li></ul>
<h3>1.&lt;7 mmol/ lit:</h3>
<ul><li>Diet + exercise for 1 – 2 weeks.</li><li>Start metformin if not controlled after 1 – 2 weeks of diet and exercise.</li><li>Insulin if Metformin C/I or not tolerated.</li></ul>
<p>2. ≥ 7 offer insulin + diet + exercise +     Metformin.</p>
<ul><li>3.6 – 6.9 + complications.</li><li>Consider insulin + diet + exercise.</li><li>Offer Glibenclamide if Metformin not effective/Not tolerated.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>Joint diabetic + A/N clinic (1 – 2 weekly visits).</li></ul>
<h3><em><strong>BSL Monitoring:</strong></em></h3>
<ul><li>Type 1</li><li>Type 2     on multiple<strong>4 levels:</strong></li><li>GDM     daily dosage     1. Fasting</li><li>Regimen.      2. Pre-meal</li></ul>
<p>3.Post-meal 1hr.</p>
<p>4. Bed time.</p>
<ul><li>Type 2     on diet exercise</li><li>GDM      oral therapy or</li><li>Single dose <strong>2 levels:</strong></li><li>insulin.1. Fasting.</li><li>2. One hour -       post meal.</li><li><strong>Targets:</strong></li><li>Fasting – 5.3</li><li>1 hour post meal – 7.8</li><li>0r</li><li>2 hours – 6.4.</li><li>Above 4mmol/lit.</li></ul>
<h3><strong>HbA1C Monito</strong><strong>ring:</strong></h3>
<ul><li>At booking – all women with pre – existing diabetes.</li><li>Consider in 2nd and 3rd  to assess risk/</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-cb799b20', 't-mm-08-023', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-32833523', 't-mm-08-023', 'html', '<ul><li>All women with GDM @ diagnosis.</li><li>Don’t measure to check the control.</li><li>Targets: &lt;486.5%.</li></ul>
<h3><strong>Hypoglycemi</strong><strong>a &amp; insulin Treatment:</strong></h3>
<ul><li>Aspart/ Lispro – rapid acting – recommended during pregnancy.</li><li>Explain hypoglycemia and treatment:</li><li>Fasting acting glucose.</li><li>Glucagon – type I.</li><li>Offer continuous S/C insulin infusion.</li><li>If hypoglycemia + uncontrolled BSL with Multiple dosage.</li><li>Continuous glucose monitoring:</li><li>Don’t offer routinely.</li><li>Offer:</li><li>Problematic Hypoglycemia.</li><li>Unstable BSL.</li><li>To gain information about variability in BSL.</li></ul>
<h3><strong>Ketone Monitoring/Testing:</strong></h3>
<ul><li>Type I:</li><li>Offer strips &amp; meter.</li><li>Home testing if unwell or raised BSL</li><li>Urgent help if ketones positive.</li><li>Type II + GDM:</li><li>Unwell or hyperglycemia | seek urgent help.</li></ul>
<p>Urgent ketones</p>
<ul><li>Positive ketones Admit level II.</li></ul>
<h3><strong>Retinal Assessment:</strong></h3>
<ul><li>Offer in preexisting DM (if not done in previous 3m0).</li><li>@ booking.</li><li>@ 28 weeks.</li><li>Pts with retinopathy @ booking (1 additional)</li><li>@ 16 – 20weeks again @ 28weeks.</li><li>@ 6months after child birth.</li><li>Vaginal birth is not C/I in retinopathy.</li></ul>
<h3><strong>Renal Assessment:</strong></h3>
<ul><li>Offer – (if not done in 3m0).</li><li>Refer to nephrologist:</li><li>Creatinine &gt; 1.2</li><li>Albumin: creatinine &gt; 30mg/mol.</li><li>Protein excretion &gt; 0.5g/ day.</li><li>Don’t use GFR.</li><li>Thromboprophylaxis.</li><li>Albumin: creatinine &gt; 220mg/mol</li><li>Proteinuria &gt; 5g/day.</li></ul>
<h3><strong>Fetal Monitoring:</strong></h3>
<ul><li>Anomaly Scan for structural anomalies + heart defects including:</li><li>4 chambers.</li><li>3 vessels.</li><li>Out flaw track.</li><li>@20 weeks</li></ul>
<h3><strong>Most common</strong></h3>
<p>VSD.</p>
<h3><strong>Pathognomonic:</strong></h3>
<p>Sacral agenesis.</p>
<ul><li>Growth + well-being: @</li><li>28, 32, 36 weeks including AFI</li><li>Routine Doppler, BPP, CTG, not recommended.</li></ul>
<h3><strong>IUGR + Growth Scan:</strong></h3>
<ul><li>Macro vascular disease.</li><li>Nephropathy.</li><li>Pre-eclampsia</li></ul>
<h3><strong>IPC:</strong></h3>
<ul><li>Discuss with women:</li><li>Timing of birth.</li><li>Mode.</li><li>Anaesthesia.</li></ul>
<h3><strong>Type I + II:</strong></h3>
<ul><li>No other complications | 37 – 38 + 6 weeks.</li><li>With fetal/ maternal or</li><li>metabolic complication | before 37 weeks.</li></ul>
<h3><strong>GDM:</strong></h3>
<ul><li>No complications | - Before 40 + 6 weeks.</li><li>Elective birth if not delivered till 40 + 6 weeks.</li><li>With complications | - Elective birth before 40+6 weeks.</li><li>Whenever complications arise.</li></ul>
<h3><strong>Mac</strong><strong>rosomia</strong><strong> on USG:</strong></h3>
<ul><li>Discuss with women:</li><li>SVD.</li><li>IOC.</li><li>C/S.</li></ul>
<h3><strong>An</strong><strong>a</strong><strong>esthesia:</strong></h3>
<ul><li>Evaluation in 3rd .</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5143dc48', 't-mm-08-023', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6910ac64', 't-mm-08-023', 'html', '<ul><li>If DM + comorbidities:</li><li>Obesity.</li><li>Neuropathy.</li></ul>
<h3><strong>G.A:</strong></h3>
<ul><li>BSL every 30 min from induction of anesthesia till delivery of baby &amp; women as conscious.</li></ul>
<h3><strong>Regional </strong><strong>A</strong><strong>naesthesia</strong><strong>:</strong></h3>
<ul><li>BSL every 1 hour</li></ul>
<h3><strong>BSL</strong><strong> Monitoring During labour</strong></h3>
<ul><li>1 hourly (target 4 – 7 mmol/lit).</li><li>Insulin infusion- Type I – all women.</li><li>+ Dextrose.- Type II, GDM:</li><li>If BSL is not between 4 – 7 mmol/lit during labor.</li></ul>
<h3><strong>Neonatal Care:</strong></h3>
<ul><li>Delivery in unit where resuscitation available during 24 hours.</li><li>BSL level – 2 – 4hours after birth (routinely).</li><li>Polycythemia, Hyper bilirubinemiaif</li><li>Hypocalcemia, hypo magnesemiaclinical signs</li><li>Echo if clinical signs present</li><li>Admissions:</li><li>Hypoglycemia + abnormal signs.</li><li>RDS + pre – term &lt; 34 weeks.</li><li>Cardiac signs.</li><li>Encephalopathy.</li><li>Polycythemia (partial exchange Tx).</li><li>Need for I/V fluid or N – G feeding.</li><li>Jaundice – requiring phototherapy.</li><li>Hypoglycemia:</li><li>Early feeding within 30 min – every 2 – 3 hours until BSL = 2mmol/lit.</li><li>Not effective feeding</li><li>Abnormal clinical signs.   N – G feeding</li><li>&lt; 2 mol on 2 reading or</li><li>Despite Max feeding.        I/V dextrose.</li><li>Don’t Discharge before 24 hours.</li></ul>
<h3><strong>PNC:</strong></h3>
<ul><li>Reduce insulin dose immediately after birth.</li><li>Shift to pre pregnancy regimen or cut the dose up to 50% if it is diagnosed 1st time in pregnancy</li></ul>
<h3><strong>GDM:</strong></h3>
<ul><li>Lifestyle modifications</li><li>6 – 3 weeks post-natal fasting BSL.</li><li>After 13 weeks – fasting BSL or HbA1C.</li><li><strong>Fasting 6 or HbA1c &lt; 39</strong><strong> = </strong><strong> 5.</strong><strong>7%.</strong></li><li>Low probability of DM @ present.</li><li>Continue lifestyle modification</li><li>Annual testing HbA1C.</li><li>Moderate risk of type 2 DM</li><li><strong>Fasting 6 – 6.9 or HbA1C 39 </strong><strong>-</strong><strong>47</strong><strong>=</strong><strong> 5.7 – 6.5%</strong></li><li>High risk of type 2 DM.</li><li>Advice regarding prevention.</li><li><strong>Fasting &gt;7 or HbA1C &gt; 48 </strong><strong>=</strong><strong> 6.5%.</strong></li><li>Have DM type (2).</li></ul>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-024', 'chap-mm-08-01', '24.DKA IN PREGNANCY', 'Detailed medical reference and study guide on 24.DKA IN PREGNANCY.', 24, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-625ccff7', 't-mm-08-024', 'html', '<h3><strong>precipitating</strong><strong> factors:</strong></h3>
<ul><li>Vomiting.</li><li>Infections.</li><li>Insulin non-compliance.</li><li>Insulin pump failure.</li></ul>
<h3><strong>S/S:</strong></h3>
<ul><li>Abdominal Pain.</li><li>Vomiting.</li><li>Polyuria, polydipsia.</li><li>Blurred vision.</li><li>Muscle weakness.</li><li>Lethargy.</li><li>drowsiness, irritability</li><li>Tachycardia, tachypnea.</li><li>Hypotension, shock, coma.</li></ul>
<p><em><strong>Biscarb =&gt;</strong></em> harmful to mother and baby – worsen hypokalemia inhibit hyper ventilation.</p>
<h3><strong>Investigations:</strong></h3>
<ul><li>BSL &gt; 11mnol.</li><li>Ketones:</li><li>Blood &gt;3 mmol/lit</li><li>Urinary 2 +Diagnostic</li><li>Bicarb &lt; 1.5.criteria.</li><li>Or PH &lt; 7.3.</li><li>Anion gap &gt; 12.</li><li>Base deficient &gt; 4.</li><li>S/K</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>MDT approach:</li><li>I/V Fluids.</li><li>I/V insulin.</li><li>Electrolyte correction</li><li>Bicarb administration of evaluation.</li><li>Treatment of underlying cause.</li><li>Fetomaternal monitoring + response of treatment.</li><li><strong>I/V fluids:</strong></li><li>0.9% N/S 10 – 15ml/kg/hr. then titrate according to haemodynamic status.</li><li>70 kg women:</li><li>1 lit/hr in 1hr</li><li>500ml/hr in next 4 hrs</li><li>250/hr in next 8 hrs</li><li>150/hr onwards</li><li><strong>K</strong><strong>+</strong><strong> Replacement and Insulin:</strong></li><li><strong>According</strong><strong> to K</strong><strong>+ </strong><strong>levels</strong></li></ul>
<p>&lt;3.3&lt;3.5 – 5.5&gt;5.5</p>
<ul><li>Give K+.K+ + insulingive I/V insulin</li><li>Don’t give</li></ul>
<p>Insulin</p>
<p>K+ replacement, ensure<strong>I/V insulin</strong></p>
<p>Adequate UOP insulin infusion</p>
<p>0.5ml/ kg/ hour.@ 0.1 unit/kg/hr.</p>
<p>40mmol/ lit of ongoingstop after DKA</p>
<p>Fluids.reversal and after</p>
<p>&lt; 3.5 =&gt; consider 30-60min of</p>
<p>Medical review.1st dose of S/C rapid acting insulin given with meal.</p>
<ul><li><strong>Identification</strong><strong> and treatment of cause:</strong></li><li>History, Examination CBC.</li><li>Investigations:</li><li>CBC</li><li>Urine analysis.</li><li>Cultures.</li><li><strong>P</strong><strong>atient</strong><strong> Monitoring:</strong></li><li>BSL – hourly.</li><li>Ketones – hourly.</li><li>Then 2 hourly.</li><li>S/E – 2 hourly</li><li>BUN, creatinine – 2 hourly until stable.</li><li>PH – 2 hourly.</li><li><strong>Fetal Monitoring:</strong></li><li>Confirm viability.</li><li>CTG monitoring.</li><li>USG if indicated.</li><li>Delivery if indicated.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-025', 'chap-mm-08-01', '25.OBESITY IN PREGNANCY', 'Detailed medical reference and study guide on 25.OBESITY IN PREGNANCY.', 25, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-25858eb3', 't-mm-08-025', 'html', '<ul><li>21% pregnant population is obese</li><li>47% have normal BMI.</li></ul>
<h3><strong>Maternal Risk:</strong></h3>
<ul><li>GDM</li><li>HTN.</li><li>VTE.</li><li>PE.</li><li>Labor:</li><li>IOL.</li><li>Dysfunctional labour</li><li>Prolonged labour</li><li>C/S.</li><li>Anesthetic complication.</li><li>Maternal mortality and morbidity (30% obese and 22% over weight)</li></ul>
<h3><strong>Fetal:</strong></h3>
<ul><li>Miscarriages</li><li>Anomalies (obese + GDM 3x anomalies).</li><li>Macrosomia.<strong>BMI Classification:</strong></li><li>Still birth.1. Underweight &lt;18.5</li><li>Pre – maturity.2. Normal 18.5-24.9</li><li>Neonatal death.3. Overweight &gt; 25</li></ul>
<p>4. Pre-obese 25-29.9</p>
<p>5. Class I 30-34.9</p>
<p>6. Class II 35-39.9</p>
<p>7. Class III 40 and above.</p>
<h3><strong>Pre – pregnancy:</strong></h3>
<ul><li>Weight reduction if BMI is &gt; 30.</li><li>Weight reduces (1) still birth (2), HTN (3), macrosomia.</li><li>VBAC success</li><li>5mg FA 1-month pre – pregnancy if BMI &gt; 30.</li><li>Vitamin D, 10ug (1000IU) daily.</li></ul>
<h3><strong>ANC:</strong></h3>
<h3><em><strong>MDT</strong></em>:</h3>
<ul><li>Consultant led BMI&gt;35.</li><li>Facilities and equipment BMI &gt;30.</li><li>Assessment of BMI @ booking then 3rd  to make appropriate plan for equipment and personal required during labour and birth.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-fa6db69e', 't-mm-08-025', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bde9ee3e', 't-mm-08-025', 'html', '<ul><li>Weight gain – no consensus.</li><li>Dietary advice by trained professional.</li><li>Anti – obesity drugs.</li><li>Orlistat – congenital anomalies.</li><li>Suppress</li><li>Topiramate – oral cleft.      appetite</li><li>Phentermine – oral cleft</li><li>Lorcaserin HT2Cpromote satiety.</li><li>Anesthetic assessment by obstetric anesthetist if BMI &gt; 40.</li><li>Pressure sore BMI &gt;40.</li></ul>
<h3><strong>BMI &amp; THEIR IMPLICATIONS:</strong></h3>
<h3><strong>BMI 40 &amp; More:</strong></h3>
<ul><li>Anaesthesia evaluation.</li><li>Uterine rupture.</li><li>Pressure sores.</li><li>I/V line in labour.</li><li>Higher loss rate with amniocentesis.</li></ul>
<h3><strong>BMI 35 &amp; Above:</strong></h3>
<ul><li>HTN, pre-eclampsia.</li><li>Difficult to measure SFH.</li><li>Post-dated.</li><li>Still birth.</li><li>Consultant led care.</li></ul>
<h3><strong>BMI 30 &amp; Above:</strong></h3>
<ul><li>GDM screening.</li><li>VTE, risk assessment/ scoring.</li><li>Mental health screening.</li><li>Wound infection.</li><li>Pre – pregnancy counselling.</li><li>Folic acid.</li><li>Vitamin D levels.</li><li>Lactation advice.</li><li><strong>GDM</strong> Screening BMI &gt; 30.</li><li><strong>HTN Screening:</strong></li><li>Proper sized cuff.</li><li>Std – 12 x 23cms.</li><li>Large – 15 x 33.</li><li>Thigh – 18 x 30.</li><li>B.P @ all visits.</li><li>P.E more in class II.</li><li>BMI &gt; 35 aspirin 150mg from 12 weeks till birth + 1 another moderate risk factor.</li><li><strong>Mental health screening:</strong></li><li>BMI &gt; 30 Risk – so do screening of mental health in antenatal period</li></ul>
<h3><em><strong>A/N depression:</strong></em></h3>
<ul><li>Obese – 33%.</li><li>Over weight – 28%.</li><li>(N) weight – 22%.</li></ul>
<h3><em><strong>P/N depression:</strong></em></h3>
<ul><li>Obese – 13%.</li><li>Over weight – 11%.</li><li>(N) weight – 9%.</li><li><strong>Chromosomal screening:</strong></li><li>TVS for NT (if difficult TAS)</li><li>NiPT non – specific.</li><li>Invasive procedure doesn’t    risk of miscarriages in BMI 30 – 40</li><li>Loss rate in BMI &gt; 48%.</li><li><strong>Structural Screening:</strong></li><li>Difficult in obese</li><li><strong>Fetal monitoring:</strong></li><li>SFH – after 24 hours to assess growth routinely.</li><li>SFH – difficult after BMI 35 so assess by USG.</li><li>USG for fetal presentation.</li><li>FHR by pinard stethoscope/ Doppler USG.</li><li>Risk of postdates and still birth BMI &gt; 35 after 37 weeks.</li><li><strong>Labo</strong><strong>u</strong><strong>r Planning:</strong></li><li><em><strong>MDT</strong></em><em>:</em></li><li>Midwife.</li><li>Obstetrician</li><li>Anaesthetist.</li><li>Multiparous low risk in Midwifery led unit.</li><li>Active management of 3rd stage.</li><li>IOL chances of LSCS and macrosomia.</li><li>Elective induction @ 37 weeks or after 37 weeks on individual basis.</li><li>LSCS due to obesity =&gt; MDT.</li><li>C/S in obese – 50%.</li><li>Macrosomia – consider IOL.</li></ul>
<h3><strong>NICE:</strong></h3>
<ul><li>BMI &gt;35 – Consultant led unit.</li><li>30 – 35 – individualized management.</li></ul>
<h3><strong>VBAC:</strong></h3>
<ul><li>BMI &gt; 30 – individualized plan (54% success of VBAC in obese, 70% in (N) BMI).</li><li>Class III obesity –   risk of rapture.</li></ul>
<h3><strong>IPC:</strong></h3>
<ul><li>Class I, II not an indication for CLU.</li><li>Informed choice of women either MLU/ CLU.</li><li>Class III continuous midwife care.</li><li>BMI &gt;40 I/V line.</li></ul>
<h3><strong>LSCS:</strong></h3>
<ul><li>Individualized circumstances</li><li>scar on skin.</li><li>Supra pannus transverse.</li><li>Supra Pannus vertical</li><li>Supra pannus scars increase chances of blood loss, Pain, respiratory morbidity.</li><li>Risk of infection not known.</li></ul>
<p>Wound infection &gt; BMI 30 – prophylactic A/B.</p>
<ul><li>Negative pressure dressing.</li><li>2cm Fat =&gt; stretching to reduce infection.</li></ul>
<h3><strong>PNC:</strong></h3>
<ul><li>Breast feeding &gt; 30 =&gt; appropriate specialist advice.</li><li>Weight reduction support.</li><li>B.F in obesity:</li><li>Delay lactogenesis – impaired prolactin response to suckling.</li><li>Lower initiation.</li><li>Earlier cessation.</li><li>Dietary advice by trained professional.</li><li>Referral to weight loss management services.</li></ul>
<h3><strong>Bariatric Surgery:</strong></h3>
<ul><li>C/C for 12 – 18m0 after surgery.</li><li>CLU as it is high risk.</li><li>Nutritional surveillance/ screening:</li><li>Iron.</li><li>Folate.Micro – nutritional</li><li>B – 12.</li><li>Fat soluble.</li><li>Vitamins.</li><li>Fats.Macro – nutritional</li><li>Proteins.</li></ul>
<h3><strong>An</strong><strong>aesthesia Complic</strong><strong>ation in Obese Women:</strong></h3>
<ul><li>Cardiac arrest 25% due to anaesthesia.</li><li>75 % in obese.</li><li>Difficult intubation.</li><li>Higher de-saturation.</li><li>Induction and recovery time.</li></ul>
<p>BMI @ booking &gt; 30 kg/m2</p>
<ul><li><strong>Fetal position assessment </strong>during labour – by USG</li><li><strong>Fetal monitoring</strong> during labour</li><li>With no medical condition =&gt; as per NICE Guideline on fetal monitoring in labor</li><li>Monitoring depends upon women’s preferences and obstetric indications.</li><li><strong>Position During Labor:</strong></li><li><em><strong>Depends upon</strong></em></li><li>1. Women’s preferences</li><li>2. Women’s mobility</li><li>3. Comorbidities</li><li>4. Current weight</li></ul>
<p><em><strong>Reduced mobility</strong></em><em><strong>adequate mobility</strong></em></p>
<p>Left lateral as per guideline on        in 2nd stage of labornormal women</p>
<ul><li><strong>Equipment needed</strong> in labor with BMI &gt; 30</li><li>1. Birthing beds – That can take safe load of 250kg</li><li>2. Sized appropriate</li><li>Surgical, obstetric and anesthetic equipment</li><li>B.P cuffs</li><li>Operating tables.</li><li>Lifting and lateral transfer</li><li>Anti – embolic stockings</li><li>Wheel chairs</li><li>Monitoring and measuring equipment.</li><li><strong>Referral to suitable obs</strong><strong>tetric</strong><strong> Unit:</strong></li><li>If BMI &gt; 50 @ booking</li><li>Refer as early as possible during ANC.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-026', 'chap-mm-08-01', '26.HEADACHE IN PREGNANCY', 'Detailed medical reference and study guide on 26.HEADACHE IN PREGNANCY.', 26, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5b79f4dd', 't-mm-08-026', 'html', '<ul><li>85 different types of headaches are there</li><li>90 % headaches are Migraine and Tension type.</li></ul>
<h3><strong>History:</strong></h3>
<ul><li>Duration.</li><li>Severity.</li><li>Frequency.</li><li>Location.</li><li>Fx.</li><li>Association with pregnancy.</li><li>Red flag feature assessment.</li></ul>
<h3><strong>Examination:</strong></h3>
<ul><li>B. P<strong>Fundoscopy:</strong></li><li>Neurological          Papilledema, raised ICP</li><li>Examination.<strong>CNS – Examination:</strong></li><li>Proteinuria- Pupil reaction.</li><li>Clonus- Visual acuity.</li><li>Eye movement CN (6).</li><li>Speech, swallowing.</li><li>Tone, power, reflexes coordination.</li><li>Planter response.</li><li>Gait assessment.</li></ul>
<h3><strong>Causes of Headache:</strong></h3>
<h3><strong>Primary </strong><strong>Secondary</strong></h3>
<ul><li>Migraine.1. HTN.</li><li>Tension.2. SAH.</li><li>3. Drugs nifedipine.</li><li>4. post Dural.</li><li>5. Stroke.</li><li>6. Meningitis.</li><li>7. Caffeine withdrawal.</li><li>8. Anemia.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9e7bf593', 't-mm-08-026', 'heading', '9. ICH.', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3c7b85a1', 't-mm-08-026', 'heading', '10. AVM.', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-32b00d93', 't-mm-08-026', 'html', '<ul><li>11. Tumors enlargement.</li><li>12. Bleeding in tumor.</li><li>13. Mets.</li></ul>
<h3><strong>Red Flag Features:</strong></h3>
<ul><li>Thunder clap:</li><li>Rapid peaking in seconds and minutes (SAH).</li><li>Sudden shape headache</li><li>become vitally unstable</li><li>Focal Neurological Symptoms:</li><li>Limb weakness, Aura – &lt;5min, &gt;1hour.</li><li>Non – Focal CVT:</li><li>Cognitive disturbance.</li><li>Abnormal Neurological Examination.</li><li>Change in Frequency/ characteristics.</li><li>Postural Headache.</li><li>Headache awakening the patient.</li><li>Headache with physical exertion.</li><li>Jaw claudication;</li><li>Age &gt; 50, Giant cell arteritis.</li><li>Fever meningitis.</li><li>Neck stiffness.</li><li>New onset headache:</li><li>HIV.</li><li>CA.</li><li><strong>Post Dural puncture Headache</strong>:</li><li>0.5 – 2% of epidurals.</li><li>Accidental puncture – 70 – 80% experience headache.</li><li>Peak @24 – 48hours last for 7 – 10 days. May last up to 6weeks.</li><li><strong>Treatment:</strong></li><li>Conservative – hydration, analgesic.</li><li>Epidural blood patch – 60 – 90% cure.</li><li><strong>Migraine:</strong></li><li>With Aura – worsen in pregnancy.</li><li>Without Aura – improves.</li></ul>
<p><em><strong>Aura:</strong></em>  reversible phenomenon of visual sensation, motor power, Balance and speech (5 – 6min).</p>
<h3><strong>Treatment:</strong></h3>
<p><em><strong>1</strong></em><em><strong>st</strong></em><em><strong> line –</strong></em> avoidance of triggers.</p>
<ul><li>Rest hydration, regular meals, relaxation.</li><li><strong>Paracetamol</strong></li><li><strong>2</strong><strong>nd</strong><strong> line:</strong></li><li>5HT1 – receptor Agonists triptans sumatriptan.</li><li><em><strong>NSAIDS.</strong></em></li><li>After informed discussion of Pt.</li></ul>
<p>Prophylaxis if 3 – 4 episodes/months.</p>
<ul><li>Propranolol – 20 – 40mg TDS.</li><li>Amitriptyline 25 – 50mg.</li></ul>
<h3><strong>Migraine:</strong></h3>
<ul><li>2 times risk of pre-eclampsia.</li><li>4 times risk of Myocardial infarction</li><li>17 times risk of stroke.</li><li><strong>Idiopathic I</strong><strong>ntracranial</strong><strong> HTN:</strong></li><li>0.9/100,000.</li><li>Male: Female.</li><li>1: 8.</li><li>Obese women 19/100,000</li><li>Generalized, non-throbbing, aggregated by Valsalva   i-e coughing + eye movements.</li><li>Diplopia 38%, visual loss 31%, Retro bulbar 6th nerve palsy.</li></ul>
<h3><strong>MDT:</strong></h3>
<ul><li>Ophthalmologist.</li><li>Neurologist.</li><li>Obstetrician.</li><li>Anaesthetist.</li></ul>
<h3><strong>Diagnosis by Dandy criteria:</strong></h3>
<ul><li>Exclude other causes by CT.</li><li>I/C pressure on lumber puncture &gt; 20cm of water</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Weight loss or limit weight gain maximum 20 pounds in pregnancy.</li><li>Monitoring of visual field &amp; visual acuity – risk of optic nerve infarction.</li><li>Therapeutic LP.       Limit visual loss &amp;</li><li>Acetazolamide 5mg B.D    improve headache.</li><li>Steroids.       - S/A – Safe.</li><li>G/A – risky -         pressure</li></ul>
<h3><strong>Surgical:</strong></h3>
<ul><li>Optical nerve fenestration.</li><li>Lumbo peritoneal shunting.</li><li><strong>Cereb</strong><strong>ral Venous Thrombosis:</strong></li><li>3rd  and 4 weeks PP, worst ever headache.</li></ul>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-53d26a94', 't-mm-08-026', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6afe5c07', 't-mm-08-026', 'html', '<ul><li>Most common site cerebral cortical veins.</li></ul>
<h3><strong>S/S:</strong></h3>
<ul><li>Headache 80 – 90%.</li><li>Papilledema, focal deficient, altered consciousness, seizures, neurological signs, psychosis.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>MRV.</li><li>CT – not sensitive detects 30% of CVT.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Prompt referral to neurologist.</li><li>LMWH – 6m0.</li><li>Endovascular therapy if coma.</li><li>F/U MRV 3 – 6m0.</li><li>Thrombophilia Screening.</li><li><strong>Cluster Headache:</strong></li><li>Watery red eye.</li><li>Dropping eyelids.</li><li>Severe throbbing pain.</li><li>Multiple attacks over few weeks, then symptoms free for years or months.</li><li>Attacks @ same time of the day daily.</li><li>Awaken the person from sleep.</li><li><strong>Post</strong><strong>erior</strong><strong> Reversible Encephalopathy Syndrome (PRES):</strong></li></ul>
<p>Clinical – Radiological – neurological entity associated with Pre – eclampsia due to Failed Autoregulation.</p>
<p>Clinical=&gt;nausea, vomiting, seizures, altered mental state and headache.</p>
<p>Radiological=&gt;edema in posterior circulation of brain.</p>
<p>Neurological=&gt;altered sensorium</p>
<h3><strong>PRES without HTN:</strong></h3>
<ul><li>SLE.</li><li>Sepsis</li><li>Immunosuppressants drug use.</li><li>Nephrotic syndrome.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>As severe PE + delivery of baby.</li><li><strong>Reversible cerebral vasoconstriction Syndrome:</strong></li><li>More in PP period</li><li>Worst headache</li><li>Recurrent, Sudden, Severe headache over 1 – 3weeks.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>Take expert opinion, ca – channel blocker, high dose steroid, mgso4.</li></ul>
<h3><strong>Imaging in Pregnancy:</strong></h3>
<ul><li>CT recommended fetal expose &lt; 0.005Mgy (accepted in pregnancy cumulative dose 50Mgy).</li><li>MRI recommended</li><li>Gadolinium recommended</li><li>Contrast media containing element iodine not recommended.</li><li>If used Neonatal thyroid function should be checked.</li></ul>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-027', 'chap-mm-08-01', '27.LIVER MASSES IN PREGNANCY', 'Detailed medical reference and study guide on 27.LIVER MASSES IN PREGNANCY.', 27, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-007f3976', 't-mm-08-027', 'html', '<h3><strong>Liver </strong><strong>Imaging in pregnancy</strong></h3>
<ul><li>Contrast enhanced MRI.</li><li>USG:</li><li>Contrast enhanced ultrasound (CEUS) using microbubbles contrast agents – safe.</li><li>CT can be done</li><li>Nuclear medicine scan Tech 99m RBC 100% specific.</li><li>Tumor makers non – specific.</li><li>Biopsy – definitive – avoided in pregnancy.</li></ul>
<h3><strong>Hepatic </strong><strong>Hema</strong><strong>n</strong><strong>gioma</strong><strong>: </strong></h3>
<ul><li>Well circumscribed</li><li>Up to 20cm.</li><li>Size     in pregnancy.</li><li>Benign 2 – 20%</li><li>Asymptomatic &lt; 5cm.</li><li>10cm symptomatic + rapidly increasing.</li><li>Risk of haemorrhage if size &gt;10 cm.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>Surgical excision/ radiological embolization after pregnancy.</li></ul>
<h3><strong>Focal</strong><strong> nodular Hyperplasia:</strong></h3>
<ul><li>3%, benign.</li><li>Nodule present in 78%,</li><li>84% has diameter &gt; 5cm.</li><li>Central stellate Scar radiating peripherally.</li><li>Well circumscribed – pseudo capsule.</li><li>Size increase in pregnancy.</li><li>Surgical resection.</li></ul>
<p><strong>Hepatic Adenomas</strong> rare, occurs in women with COC use.</p>
<p>Highly vascular lesions revealed by CT and MRI</p>
<h3><strong>Lesion:</strong></h3>
<ul><li>Solitary 32%</li><li>Multiple 45%</li><li>Adenomatosis 23%</li><li><strong>Postpartum:</strong></li></ul>
<p>Hormone levels decrease leading to loss of blood supply and degenerative changes and Risk of Haemorrhage</p>
<h3><strong>Complications:</strong></h3>
<ul><li>Risk of catastrophic Hge 27.2% lifetime.</li><li>Rupture – 15.8% - highest in 3rd , maternal Mortality 44%, fetal 38%.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6fc2329a', 't-mm-08-027', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ac0fba39', 't-mm-08-027', 'html', '<h3><strong>Treatment:</strong></h3>
<ul><li>Embolization in emergency.</li><li>Surgical resection &gt; 5cm in non – pregnant stage.</li></ul>
<h3><strong>HCC:</strong></h3>
<ul><li>Rising in Asia due to rising Hep B or C.</li><li>αFP &gt; 1000mg/mol</li><li>aggressive.</li><li>Cause infertility.</li></ul>
<h3><strong>Acute Hge in pregnancy:</strong></h3>
<ul><li>Embolization (if diagnosed before surgery).</li><li>Liver packing, intra-operatively.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-028', 'chap-mm-08-01', '28. ACUTE KIDNEY INJURY IN PREGNANCY', 'Detailed medical reference and study guide on 28. ACUTE KIDNEY INJURY IN PREGNANCY.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ebde2055', 't-mm-08-028', 'html', '<ul><li>1.4% of obstetric admission.</li><li>e GFR – Not reliable.</li><li>Serum creatinine decreases in pregnancy by 35 µmol/l.</li><li>Average = 53 µmol /l.</li><li>Abnormal &gt;90 µmol/l =&gt; investigate.</li><li>40% AKI – unrecognized.</li><li>Most common cause = Pre-eclampsia.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Fluid status Assessment.</li><li>Medication review.</li><li>Fluid replacement.</li><li>Diagnostic work – up.</li><li>Involvement of nephrologist if initial management is failed.</li></ul>
<h3><strong>Drug dosage Adjustment:</strong></h3>
<ul><li>Antibiotics.</li><li>Anticoagulants.</li><li>Insulin.</li><li>Opiates.</li><li>If GFR &lt; 30.</li><li>NSAIDS =&gt; C/I in:</li><li>AKI.</li><li>CKD.</li><li>PTE.</li><li>Volume depletion.</li><li>Asthma.</li></ul>
<p>Urea – teratogenic &gt;17mmol/l =&gt; despite medical treatment need Renal replacement therapy.</p>
<ul><li><strong>Pre – Eclampsia</strong><strong>:</strong></li><li>Leads to AKI in 1.5 – 2% cases.</li></ul>
<h3><strong>Biopsy shows:</strong></h3>
<ul><li>Endotheliosis.</li></ul>
<h3><strong>Mgso4: </strong></h3>
<ul><li>Renal execration.</li><li>If Urine output &lt;20ml/hour or creatinine &gt;90 then</li><li>Give only 50% dose of Mgso4.</li><li>Mgso4 level monitoring 4 – 6 hourly.</li><li>Maintain levels 2 – 3.5mol/lit.</li></ul>
<p>Post-partum diuresis (normal).</p>
<p>36 – 48 hours.</p>
<p>Before diuresis, oliguria is normal.</p>
<p>40ml/4 hours (N).</p>
<p>In immediate PP Period.</p>
<h3><strong>HELLP:</strong></h3>
<ul><li>Cause AKI – 3 – 15%.</li><li>Postpartum all parameters deteriorate for 48 hours.</li><li>Then recover</li><li>If don’t recover after 48 hours &amp; AKI predominate along with platelets consumption.</li><li>Consider TTP.</li><li><strong>Biopsy:</strong></li><li>Endotheliosis + Thrombotic microangiopathy.</li></ul>
<h3><strong>Difference between HELLP &amp; TTP.</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-079bee13', 't-mm-08-028', 'html', '<table><tbody><tr><td><strong>Feature</strong></td><td><strong>HELLP</strong></td><td><strong>TTP/HUS</strong></td><td><strong>AFLP</strong></td></tr><tr><td>Incidence</td><td>1/100<br/>10 – 30% of severe PE</td><td>1/25,000</td><td>3/100,000</td></tr><tr><td>Gestation</td><td>AP – 70%<br/>PP – 30%</td><td>TTP – 2nd, 3rd<br/>Hus – PP &gt;75%</td><td>Biopsy shows tubular</td></tr><tr><td>Thrombocytopenia</td><td>&lt;10x109 – rare</td><td>Profound</td><td>Free fatty acid</td></tr><tr><td>LFT’S</td><td>transaminases</td><td>Normal transaminases<br/>Pre hepatic Bilirubin</td><td>Deposition</td></tr><tr><td>AKI</td><td>3 – 15%</td><td>30 – 80%</td><td>14%</td></tr><tr><td>Coagulopathy</td><td>20%</td><td>Elevated anti – Thrombin &amp; Fibrinogen.</td><td>3.5% Require renal replacement<br/>- Low glucose<br/>- Raised ammonia<br/>Production - vomiting</td></tr><tr><td>ADAMTS - 13</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>complement</td><td>preset</td><td>Cause HUS<br/>Treatment:<br/>Eculizumab</td><td>&nbsp;</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6b48eac3', 't-mm-08-028', 'html', '<ul><li><strong>T</strong><strong>T</strong><strong>P Pentad</strong></li><li>Microangiopathic haemolytic anemia (   Hb and Retics)</li><li>Thrombocytopenia</li><li>Fever</li><li>Renal impairment (AKI)</li><li>Neurological manifestations</li><li>Headache</li><li>Irritability</li><li>Drowsiness</li><li>Seizures</li><li>Coma</li><li><strong>SLE:</strong></li><li>20 – 49% - renal involvement.</li><li>16% renal disease activation in pregnancy.</li><li>10% of lupus nephrites develop ARF in pregnancy.</li><li><strong>Obstructive Nephropathy:</strong></li><li>Pelvicalyceal system + ureteral dilatation are normal in pregnancy.</li><li>Pathological if:</li><li>Dilatation of urethra distal to Brim.</li><li>Ureteric jet absents.</li><li>Obstruction don’t disappear by positioning the women on all four.</li><li><strong>Drugs:</strong></li><li>Penicillin</li><li>Cephalosporins</li><li>PPI</li></ul>
<h3>Common drugs and their effects on kidneys:</h3>
<ul><li>Naproxen – AKI.</li><li>Indomethacin nephrotoxicity – nephritis, hyperkalemia.</li><li>Fenoprofen – nephritis.</li><li>Meloxicam – very little renal effects.</li></ul>
<h3><strong>Adverse Effects of NSAIDS:</strong></h3>
<h3><em><strong>GI:</strong></em></h3>
<ul><li>Dyspepsia</li><li>Ulceration.</li><li>Bleeding</li><li>Colonic stricture</li></ul>
<h3><em><strong>Renal:</strong></em></h3>
<ul><li>AKI</li><li>Hyperkalemia 10 – 46%.</li><li>Na retention.</li><li>Interstitial nephritis.</li><li>Papillary necrosis.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-029', 'chap-mm-08-01', '29.ASTHMA IN PREGNANCY', 'Detailed medical reference and study guide on 29.ASTHMA IN PREGNANCY.', 29, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-315b8899', 't-mm-08-029', 'html', '<ul><li>Commonest chronic condition 4 – 12%.</li></ul>
<h3><strong>Breathlessness:</strong></h3>
<ul><li>If RR is &gt; 24 (normal 12 – 20).</li></ul>
<h3><strong>Causes</strong><strong> of </strong><strong>breathlessness</strong><strong>:</strong></h3>
<ul><li>Anxiety.</li><li>Hyperventilation.</li><li>Respiratory diseases:</li><li>Asthma</li><li>Chest infection.</li><li>VTE – embolism.</li><li>AF embolism.</li><li>pneumothorax.</li><li>CVS:</li><li>Arrhythmias</li><li>IHD</li><li>Cardiomyopathy.</li><li>Endocrine disorders:</li><li>DM + DKA.</li><li>Thyrotoxicosis.</li><li>Hematological:</li><li>Anemia.</li><li>Hge.</li><li>Renal diseases.</li></ul>
<h3><strong>Effect of Pregnancy on Asthma:</strong></h3>
<ul><li>Unchanged/ worsen/ improve.</li><li>Severe – worsen 60%.Depend upon</li><li>Mild – worsen 10%.severity.</li><li>Worsening 24 – 36 weeks.</li><li>Commonest triggering factor.</li><li>Viral infections.</li><li>Non-compliant to treatment = 29%.</li><li>Cortisol</li><li>Progesterone</li><li>F2α | Worsen.</li></ul>
<p><strong>1/5</strong><strong>th</strong><strong>:</strong> Exacerbation in labour/ delivery.</p>
<ul><li>Ergometrine, prostaglandins =&gt; bronchospasm</li><li>F2α = intra myometrial can be given avoid I/V, I/M</li><li>Avoid NSAIDS</li></ul>
<h3><strong>MDT:</strong></h3>
<ul><li>Respiratory physician and Obstetrician.</li><li>Step 3 treatment and above.</li><li>Mod – severe disease.</li></ul>
<h3><strong>Effect of Asthma on Pregnancy:</strong></h3>
<ul><li>Pre-eclampsia</li><li>IUGR</li><li>PTL</li><li>Low birth</li></ul>
<p>Steroids =&gt; cleft lip = 0.3%.</p>
<h3><strong>Management:</strong></h3>
<ul><li>Acute – admission.</li><li>OPD – step wise management</li></ul>
<p><em><strong>Step 1</strong></em><em><strong>:</strong></em><em><strong> </strong></em><strong>(Mild intermittent)</strong></p>
<ul><li>Inhalation B2 Agonist.</li><li>Short acting:</li><li>Salbutamol</li><li>Terbutaline.</li></ul>
<p><em><strong>Step 2:</strong></em><em><strong> </strong></em>(<strong>Regular preventer)</strong></p>
<ul><li>Inhalation steroid</li><li>Add 200 – 800mcg.</li><li>Beclomethasone.</li><li>Budesonide.</li><li>400 appropriate.</li></ul>
<p><em><strong>Step 3:</strong></em><em><strong> (initial add on)</strong></em></p>
<ul><li>Add LABA long acting B2 Agonist</li><li>Salmeterol.</li><li>Formoterol.</li></ul>
<h3><strong>Long acting B</strong><strong>2</strong><strong> Agonist</strong></h3>
<p>Good controlsub optionalno response</p>
<p>ContinueLABA- Stop LABA</p>
<p>+-   Steroid</p>
<p>Dose of    inhaled steroid to still uncontrol.800mcg/day.</p>
<p>1. Add leukotriene</p>
<p>2. Theophylline</p>
<p>(Drug level monitoring.)</p>
<p><em><strong>Step 4:</strong></em><em><strong> </strong></em><strong>(</strong><strong>Persistent poor control</strong><strong>)</strong></p>
<ul><li>Inhaled steroid up to 200mcg/lit.</li><li>Add 4th Drug:</li><li>Theophylline</li><li>B2 – Agonist.</li><li>Leukotriene receptor Blockers.</li></ul>
<p><em><strong>Step 5:</strong></em><em><strong> </strong></em><strong>(</strong><strong>Continuous/ Frequent use of oral steroids</strong><strong>)</strong></p>
<ul><li>Oral steroids.</li><li>Maintain high dose steroids.</li><li>Refer to specialist.</li></ul>
<h3><strong>Drugs of Asthma:</strong></h3>
<ul><li>All drugs safe in pregnancy + B.F:</li><li>Steroids – cleft lip or palate &lt; 0.3%.</li><li>Anti IgE:</li><li>Biological therapy not suitable in pregnancy.</li><li>Given in specialist center.</li><li>Montelukast:</li><li>Limited date.</li></ul>
<h3><strong>Avoid in Asthma:</strong></h3>
<ul><li>Labetalol – HTN.</li><li>Ulipristal acetate – EC.</li><li>Ergometrine – PPH.</li><li>NSAIDS – pain.</li><li>F2α – intra myometrial can be given but no I/V or I/M</li></ul>
<p>WHO recommended 6m0 B.F to reduce childhood asthma.</p>
<h3><strong>Pain Relief:</strong></h3>
<ul><li>Offer all options as in normal healthy women.</li></ul>
<h3><strong>Prostaglandin:</strong></h3>
<p>Prostaglandin F2 alpha – contraindicated</p>
<ul><li>Cause bronchospasm.</li></ul>
<p>Prostaglandin E1 and E2 – safe for IOL</p>
<p>E1 – an option for PPH.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
