INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d06c31c8', 't-mm-08-036', 'html', '<ul><li>Risk of fetal loss but same PTB rate.</li><li>I/O normal looking appendix =&gt; Remove as it is histological diagnosis.</li></ul>
<h3><strong>Chronic appendicitis:</strong></h3>
<ul><li>Walled off appendix, appendicular mass.</li><li>Conservative treatment. [no surgery]</li></ul>
<h3><strong>Anesthesia management/ Pre –op/ Surgical Management:</strong></h3>
<ul><li>GA riskier, regional is preferred.</li><li>Tocolysis NR (GA has oncolytic effect).</li><li>Steroid @ 24 – 34 weeks.</li><li>CTG during late .</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
