INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-68cfc5c2', 't-mm-08-036', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d4867f5d', 't-mm-08-036', 'html', '<h3><strong>Abnormal FHR:</strong></h3>
<ul><li>Correct hypovolemia.Not corrected</li><li>Correct hypotension.with conservative</li><li>Ensure left lateral tilt.treatment =&gt; C/S</li><li>Oxygenation.</li><li>Analgesia:</li><li>Opiates safe</li><li>NSAIDS up to 32 weeks.</li><li>VTE prophylaxis during admission ace to GTG.</li><li>A/B given as per protocol.</li><li>Anti D when there is uterine manipulation.</li><li>Minimal uterine &amp; cx manipulation intraoperatively.</li></ul>
<h3><strong>Simultaneous C/S:</strong></h3>
<ul><li>Perforated appendix/ Maternal sepsis requiring maternal resuscitation.</li><li>37 + obstetric indication.</li><li>Not done routinely.</li></ul>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-037', 'chap-mm-08-01', '35.2. B – BILIARY COLIC/ CHOLECYSTITIS', 'Detailed medical reference and study guide on 35.2. B – BILIARY COLIC/ CHOLECYSTITIS.', 37, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e65f44d4', 't-mm-08-037', 'html', '<ul><li>1 – 6/1000.</li><li>90% due to gall stones.</li><li>2nd most common (more in pregnancy due to   cholesterol secretion + super saturation of of bile).</li><li>Late Gestations – appendicitis and cholecystitis similar presentation.</li><li>LFTS to rule out obstructive jaundice.</li><li>USG 95% Sensitive.</li></ul>
<h3><strong>Management Biliary colic:</strong></h3>
<ul><li>Adequate analgesia, anti-emetics.</li><li>Lap chole after resolution of acute episode.</li></ul>
<h3><strong>Stone in CBD:</strong></h3>
<ul><li>ERCP for diagnosis and treatment.</li></ul>
<h3><strong>Acute </strong><strong>cholecystitis</strong><strong>:</strong></h3>
<ul><li>NPO and antibiotics.</li><li>Fluids I/V.</li><li>Definitive cholecystectomy after acute resolution.</li><li>Perforation, focal/ generalized peritonitis =&gt; urgent surgery.</li></ul>
<p>Readmission without surgery = 4.7 times.</p>
<p>Readmission with surgery = 0.4 times than (N).</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-038', 'chap-mm-08-01', '35.3. C – BOWEL OBSTRUCTION', 'Detailed medical reference and study guide on 35.3. C – BOWEL OBSTRUCTION.', 38, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a5c147b7', 't-mm-08-038', 'html', '<ul><li>1/500</li></ul>
<h3><strong>Causes:</strong></h3>
<ul><li>Adhesions.</li><li>Bowel displacement + distortion due to Gravid uterus.</li><li>Ogilvie syndrome = pseudo-obstruction – functional colonic obstruction due to pregnancy/ delivery by C/S.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>S/E</li><li>RFTS</li><li>X – RAY erect abdominal [avoid]</li><li>USG – safe</li><li>MRI – safe</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>NPO, bowel decompression.</li><li>Senior surgeon involvement.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-039', 'chap-mm-08-01', '35.4. D – PANCREATITIS', 'Detailed medical reference and study guide on 35.4. D – PANCREATITIS.', 39, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-50f9fa34', 't-mm-08-039', 'html', '<ul><li>Rare 3/19000.</li><li>70% due to gall stones.</li><li>Lipase more sensitive for diagnosis than amylase</li><li>surgical inputs.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-040', 'chap-mm-08-01', '35.5. E – URETERIC OBSTRUCTION & PYELONEPHRITIS', 'Detailed medical reference and study guide on 35.5. E – URETERIC OBSTRUCTION & PYELONEPHRITIS.', 40, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
