INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-64c3397f', 't-mm-08-045', 'html', '<h3><strong>Differences between Gestational transient Thyrotoxicosis GTT and Graves’ hyperthyroid disease:</strong></h3>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-22afcf0a', 't-mm-08-045', 'html', '<table><tbody><tr><td><strong>Features</strong></td><td><strong>GTT</strong></td><td><strong>Graves’ hyperthyroid</strong></td></tr><tr><td><strong>1.</strong> incidence</td><td>1 – 5%</td><td>0.05 – 1.3%</td></tr><tr><td><strong>2.</strong> Symptoms before pregnancy</td><td>No</td><td>Often</td></tr><tr><td><strong>3.</strong> Symptoms of HG (Nausea vomiting)</td><td>Yes</td><td>No</td></tr><tr><td><strong>4.</strong> Personal or FH of thyroid disease</td><td>No</td><td>Yes 50%</td></tr><tr><td><strong>5.</strong> Goiter</td><td>No</td><td>Diffuse goiter 90%</td></tr><tr><td><strong>6.</strong> Signs of eye disease</td><td>No</td><td>Yes 20%</td></tr><tr><td><strong>7.</strong> fT3 care</td><td>Normal 85%</td><td>&nbsp;</td></tr><tr><td><strong>8.</strong> TRAb</td><td>(N)</td><td>&nbsp;</td></tr><tr><td><strong>9.</strong> Serial Monitoring of TFT’s</td><td>Improve</td><td>Remain same without treatment</td></tr><tr><td><strong>10.</strong> Treatment</td><td>Supportive care</td><td>Anti - thyroid drugs</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-082af6ff', 't-mm-08-045', 'image', '/uploads/content-images/maternal_mind_book/image107.png', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c1ea3a10', 't-mm-08-045', 'html', '<h3><strong>Post – Natal Care:</strong></h3>
<ul><li>Autoimmunity in post – natal period is associated with</li><li>Graves’ relapse</li><li>New onset Graves’</li><li>Treatment in post – natal period</li><li>Antithyroid drugs in 2 or 3 divided doses</li><li>Both CMZ and PTU can be given</li><li>Monitoring of child’s growth who are breast feeding.</li><li>Safe maximum doses in lactation</li></ul>
<p>CMZ = 20mg, PTU = 450mg daily</p>
<p>Transfer of CMZ in milk = 0.1 – 0.2% and PTU 0.007% - 0.077%</p>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-046', 'chap-mm-08-01', '38.3. THYROID NODULE AND THYROID CANCER', 'Detailed medical reference and study guide on 38.3. THYROID NODULE AND THYROID CANCER.', 46, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0b2a2d0f', 't-mm-08-046', 'html', '<ul><li>Incidence</li><li>Non iodine deficient areas = 1%</li><li>Mild – mod iodine deficient areas = 15 – 21%</li><li>Newly diagnosed or enlarging module</li><li>Refer to specialist</li><li>USG thyroid is safe, effective and sensitive.</li><li>Suspicion of malignancy on USG</li><li>FNAC @ any gestation</li><li>Enlarged thyroid or nodule.</li><li>Refer to ENT surgeon/ Endocrinologist</li><li>Review by obstetric anesthetist</li><li>Surgery is required rarely except</li><li>Rapidly enlarging</li><li>Airway compression</li><li>Rapidly progressive disease</li><li>Perform surgery in between 14 – 22weeks if required</li><li>Avoid radioactive agents.</li><li>Incidence of cancer in pregnancy 11 in 100,000</li><li>Rate of progression, survival and recurrence is same as non-pregnant.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-08-047', 'chap-mm-08-01', '38.4. POST – PARTUM THYROIDITIS PPT', 'Detailed medical reference and study guide on 38.4. POST – PARTUM THYROIDITIS PPT.', 47, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-af974224', 't-mm-08-047', 'html', '<ul><li>Development of thyroid dysfunction within 12 months of pregnancy in a previously euthyroid women and excluding other thyroid condition</li></ul>
<p>Incidence = 5 – 10% in unselected women</p>
<ul><li>Risk is more with other autoimmune conditions 30 – 50% risk in women with positive TPOAb</li></ul>
<h3><strong>Presentation:</strong></h3>
<ul><li>Classical form = triphasic 20 – 40%</li><li>Thyrotoxic – 2 – 6m0 PP</li><li>Transient hypothyroid  3 -12m0 PP</li><li>Euthyroid</li><li>Only thyrotoxicosis 20 – 30%</li><li>Isolated hypothyroid 40 – 50%</li><li>Permanent hypothyroidism= 50%</li></ul>
<h3><strong>R</strong><strong>isk</strong><strong> factor for permanent hypothyroidism:</strong></h3>
<ul><li>+ TPOAb</li><li>Maternal age</li><li>History of pregnancy loss</li><li>Thyroid hypoechogenicity on USG</li><li>Severe hypothyroidism</li><li>Risk of replace in future pregnancies 70%</li><li>Some relationship between positive TPOAb, PPT and PP depression, but no proven role of levothyroxine prophylaxis in TPOAb to prevent PP depression.</li><li>Raised TPOAb – more symptoms.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Routine testing for PPT is not recommended</li><li>Risk factors for PPT + Symptoms of thyrotoxicosis then do perform thyroid function tests</li><li>Perform serial TFT’s every 6 weeks along with symptom assessment to confirm diagnosis</li><li>Exclude other etiologies by</li><li>Thyrotoxicosis – TRAb testing</li><li>Graves’ disease – isotopes scans.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f420e1fb', 't-mm-08-047', 'html', '<table><tbody><tr><td><strong>Features</strong></td><td><strong>Graves’ disease</strong></td><td><strong>PPT</strong></td></tr><tr><td>1. Thyrotoxicosis symptoms moss commonly @</td><td>6m0 PP</td><td>3m0 PP</td></tr><tr><td>2. Ophthalmopathy</td><td>Present</td><td>Absent</td></tr><tr><td>3. TRAb</td><td>Present</td><td>Absent</td></tr><tr><td>4. Large goiter with bruit</td><td>Present</td><td>--</td></tr><tr><td>5. Ratio of T4:T3</td><td>--</td><td>RAISED</td></tr><tr><td>6. Uptake of radioactive isotopes</td><td>&nbsp;</td><td>Low</td></tr><tr><td>7. USG</td><td>Diffuse hypoechoic and heterogeneous texture, increased    blood flow</td><td>Non – homogenous hypoechogenic texture, reduced    blood flow</td></tr><tr><td>8. Histopathology</td><td>- Patchy infiltrate<br/>- Follicular cell hyperplasia</td><td>Lymphocytic infiltrate is diffuse</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
