INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-001', 'chap-mm-09-01', '1. PERINATAL INFECTIONS', 'Detailed medical reference and study guide on 1. PERINATAL INFECTIONS.', 1, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2ab1132a', 't-mm-09-001', 'html', '<p><strong>DNA Viruses:</strong><strong> </strong>All are Double standard DNA viruses except PARVO virus.</p>
<ul><li>VZV.</li><li>HSV</li><li>HPV</li><li>HEP B</li><li>Adenovirus</li><li>Parvovirus</li></ul>
<h3><strong>RNA viruses:</strong></h3>
<ul><li>Mumps</li><li>Measure</li><li>Rubella</li><li>Toga</li></ul>
<h3><strong>Protozoa: </strong></h3>
<ul><li>Malaria, Toxoplasmosis.</li></ul>
<h3><strong>Spirochete:</strong></h3>
<ul><li>Syphilis</li></ul>
<h3><strong>Zika Virus: </strong></h3>
<ul><li>Microcephaly:</li><li>Contraception:</li><li>3m0 – Both partners are traveler.</li><li>3m0 – male partner is traveler.</li><li>2m0 – female partner is traveler.</li></ul>
<h3><strong>Hep B:</strong></h3>
<ul><li>In all cases give HEP B vaccination + immunoglobulin EXCEPT:</li><li>When e antibodies positive because risk of transmission is low just give vaccination is given.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-002', 'chap-mm-09-01', '1.1.GBS IN PREGNANCY', 'Detailed medical reference and study guide on 1.1.GBS IN PREGNANCY.', 2, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-868bcf76', 't-mm-09-002', 'html', '<ul><li>in UK 0.5/100.</li><li>antenatal screening is done @ 35 – 37 in singleton, 32 – 34 in twins.</li><li>Incidence of GBS carriage = 20-40% of bowel flora.</li></ul>
<h3><strong>Incidence of GBS:</strong></h3>
<ul><li>Overall = 0.57/1000.</li><li>Without risk factor = 0.2/ 1000.</li><li>In previous pregnancy = 0.9/ 1000.</li><li>If GBS in current pregnancy = 2.3/ 1000.</li><li>Pyrexia &gt; 38 = 5.3/ 1000.</li></ul>
<h3><strong>EONNS:</strong></h3>
<ul><li>Early onset Neonatal sepsis &lt; 7 days</li><li>89% within 24hours.</li><li>97% within 12 hours.</li></ul>
<p>Mortality of EONNS = 10.6% overall</p>
<ul><li>&gt;37 weeks = 5.7%</li><li>&lt;37 weeks = 18.3%</li><li>&lt;35 weeks = 22%</li></ul>
<h3><strong>Late:</strong></h3>
<ul><li>7 and above days.</li><li>17 – 25% screen positive @ 35 – 37 weeks will be negative @ delivery.</li><li>5 – 7% screen negative will be positive @ birth.</li><li>No screening on maternal request.</li><li>GBS carriage PROM =&gt; category 2/3 C/S if required.</li></ul>
<h3><em><strong>Antenatal A</strong></em><em><strong>ntibiotics</strong></em><em><strong>:</strong></em></h3>
<ul><li>GBS bacteriuria (Antenatal + IAP).</li><li>Membrane sweeping is not C/I.</li></ul>
<h3><strong>Commonest Cause GBS:</strong></h3>
<ul><li>streptococcus agalactiae.</li><li>E – Coli.</li><li>Meningitis = 11.8%.</li><li>Pneumonia = 7.8%.</li><li>Focal infection = 1%.</li></ul>
<h3><strong>Risk Factor for GBS:</strong></h3>
<ul><li>Previous baby GBS.</li><li>GBS carriage.</li><li>Pre – term.</li><li>Prolong rupture of membranes &gt; 18 hours.</li><li>Suspected maternal infection.</li><li>Pyrexia &gt; 380C.</li></ul>
<h3><strong>Indications of GBS IAP (80% Effective):</strong></h3>
<ul><li>Previous baby with invasive GBS.</li><li>GBS bacteriuria 105cfu/ml in current pregnancy.</li><li>GBS on vaginal swab in current pregnancy.</li><li>Pyrexia &gt; 380F (Broad spectrum A/B).</li><li>Chorioamnionitis (Broad Spectrum A/B) @ PTL.</li><li>GBS carriage in previous pregnancy either IAP or screening @ 35 – 37 weeks.</li><li>Repeat colonization = 50%.</li><li>Repeat GBS = 0.9/ 1000.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-12665bd9', 't-mm-09-002', 'image', '/uploads/content-images/maternal_mind_book/image108.png', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a541be2c', 't-mm-09-002', 'html', '<h3><strong> intrapartum antibiotic prophylaxis (IAP)</strong></h3>
<ul><li>Benzyl penicillin 3g stat followed by 1.5g 4hourly till delivery.</li><li>clindamycin 900g stat then 8 hourly till delivery (resistance = 16%)</li><li>Vancomycin 1g – 12 hourly, if severe allergy to Benzyl Penicillin (Angioedema, urticaria anaphylaxis, RDS).</li><li>Cefuroxime 1.5g stat then 750g – 8 hourly if mild allergy to Benzyl Penicillin</li><li>Pt refuses IAP =&gt; Observe baby for 12 hours.</li><li>Avoid – Ampicillin =&gt; G – negative sepsis.</li></ul>
<h3><strong>Urgent Help if bab</strong><strong>y:</strong></h3>
<ul><li>Inconsolable cry, listlessness.</li><li>Floppy, difficult feeding.</li><li>Abnormal temperature.</li><li>380C, &lt; 360C.</li><li>Rapid breathing.</li><li>Change in skin color.</li><li>Penicillin +within 1</li><li>Gentamycin.hour.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
