INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-008', 'chap-mm-09-01', '1.7.CYTOMEGALOVIRUS', 'Detailed medical reference and study guide on 1.7.CYTOMEGALOVIRUS.', 8, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d028e6c2', 't-mm-09-008', 'html', '<ul><li>Most common congenital infection – 0.5%</li><li>40 – 60% seropositive.</li><li>37% Neonates born with infection.</li><li>10% have clinical manifestation.</li><li>40% transmission in 1st, 2nd .</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a5a2d5ba', 't-mm-09-008', 'image', '/uploads/content-images/maternal_mind_book/image120.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
