INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0c097bb2', 't-mm-09-008', 'image', '/uploads/content-images/maternal_mind_book/image121.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-81da4f57', 't-mm-09-008', 'html', '<ul><li>P0 infection cause miscarriage.</li><li>Transmission increases with Gestation.</li><li>Infectivity decreases with Gestation.</li><li>Transmission by saliva, body fluids</li></ul>
<h3><em><strong>Screening:</strong></em></h3>
<ul><li>Symptomatic women or USG suggestive of CMV other causes of placental insufficiency ruled out.</li></ul>
<p>=&gt; IgG or IgM alone are unreliable</p>
<p>=&gt; positive IgG and IgM with low avidity show       recent infection: 3-4 months</p>
<p>=&gt; high avidity suggests old infection &gt;3 months</p>
<h3><strong>Assessment of fetal infection:</strong></h3>
<ul><li><em><strong>USG</strong></em></li><li>20% detection.</li><li>Unreliable, serial USG 2 – weeks.</li><li><em><strong>Amniocent</strong></em><em><strong>esis</strong></em><em><strong>:</strong></em></li><li>6 – 8 weeks after infection &amp; after 20 weeks GA.</li><li>Positive CMV</li><li>Quantitative DNA</li></ul>
<h3><strong>Positive</strong><strong> on Amniocentesis or USG</strong></h3>
<p>counselling regarding risk of symptomatic disease.</p>
<ul><li>Sensorineural deafness 12%, Leading cause of non – genetic deafness.</li><li>CP – 8%.</li><li>5 – 20% symptomatic infants.</li></ul>
<h3><strong>Infants can have</strong><strong>:</strong></h3>
<ul><li>Jaundice, petechial rash Hepatosplenomegaly, microcephaly, SGA.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Asymptomatic fetus mild to moderate disease:</li><li>Expectant.</li><li>Detailed Examination of ear and eyes after birth and postnatal t/m and lifelong follow up of affected neonate.</li><li>Examination of placenta.</li><li>Symptomatic:</li><li>Mild, mod, severe disease.</li><li>Top</li><li>Post mortem examination.</li><li>Examination of placenta.</li><li><em><strong>MRI </strong></em><em><strong>+</strong></em><em><strong>:</strong></em></li></ul>
<p>B/L periventricular calcifications.</p>
<ul><li>@ 28 – 32 weeks.</li><li>Repeat 3 – 4 weeks if needed.</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
