INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-69b81d36', 't-mm-09-021', 'html', '<ul><li>Obstetric hemorrhage is the 3rd leading cause of maternal mortality</li><li>10% of direct deaths.</li><li>4000 cases/ 1 year in Uk.</li></ul>
<h3><strong>Reducing risks of Transfusion (Tx)</strong><strong>:</strong></h3>
<ul><li><strong>Optimization of Hb:</strong></li><li>11 g/dl in 1st .</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ad14f45b', 't-mm-09-021', 'image', '/uploads/content-images/maternal_mind_book/image136.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bbfb3457', 't-mm-09-021', 'html', '<ul><li>10.5 g/dl in 2nd &amp; 3rd .</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3fed5813', 't-mm-09-021', 'image', '/uploads/content-images/maternal_mind_book/image137.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-385d6f69', 't-mm-09-021', 'html', '<ul><li>10 g/dl – PP.</li><li>Microcytic or hypochromic – oral iron for 2 weeks</li><li>Check Hb</li><li>Check compliance if no rise in Hb</li><li>Further Test if compliant</li><li><strong>Hb</strong><strong> </strong><strong>in </strong><strong>Singleton</strong>       <strong>  In </strong><strong>Twins:</strong></li><li>@ Booking.- @ Booking.</li><li>@ 28 weeks- @ 20-24 weeks.- @28 weeks.</li><li>Antenatal iron + folic acid reduces anemia by 50%.</li><li>1st line oral iron</li><li>Parenteral Iron:</li><li>Not tolerated/ absorbed.</li><li>Approaching Term.</li><li>PT compliance is poor.</li><li>rHuEPo – clinical trials – not recommended</li><li>Active management of 3rd stage of labor.</li><li>Delivery of women @ risk of loss &gt; 1000ml =&gt; where blood bank available, and ICU available.</li></ul>
<h3><strong>Principles of TX:</strong></h3>
<ul><li>Valid consent + documentation.</li><li><strong>Grouping, screening &amp; cross matching @ booking + 28week:</strong></li><li>&lt; 3 days old sample should be used for cross matching.</li><li>Pts @ risk of TX =&gt; weekly samples to rule out production of new Antibodies.</li><li>ABO-, RH-v, Kell-ve (in pregnancy &amp; PP).</li><li>Pts with antibodies refer to FMU.</li><li>Specific Antibodies in Maternal blood =&gt; cross match blood with negative antigen.</li><li>CMV-ve.</li><li>Autologous blood Tx not recommended.</li></ul>
<h3><strong>O</strong><strong>bstetric</strong><strong> H</strong><strong>aemorrhage</strong><strong>: </strong></h3>
<ul><li>blood &amp; blood products.</li></ul>
<h3><strong>Blood:</strong></h3>
<ul><li>O-ve, Kell-ve.</li><li>Later on – Group specific.</li><li>Early intervention to minimize loss</li></ul>
<h3><strong>FFP:</strong></h3>
<ul><li>12 – 15ml/ kg after 6units of blood.</li><li>Target PT/ APTT Should &lt;1.5 of normal.</li></ul>
<h3><strong>Cryo</strong><strong>precipitates</strong><strong>:</strong></h3>
<ul><li>25units pools</li><li>target fibrinogen should be &lt;1.5.</li></ul>
<h3><strong>FFP</strong><strong> &amp; Cryo:</strong></h3>
<ul><li>Same group, no Anti D required.</li><li>If not available then different ABO with Anti A, Anti B activity.</li></ul>
<h3><strong>Plt:</strong></h3>
<ul><li>Target should be &gt; 75 x 109.</li><li>Group compatible – If not available HLA matched plt.</li><li>Anti D required 250 IU for 5units of Plt within 6 weeks</li><li>Always use new BT sets.</li></ul>
<h3><strong>IOCS – is recommended:</strong></h3>
<ul><li>If loss &gt; 20% of volume, or women who refuse blood products (Jehovah’s witness).</li><li>Consent – written, documented.</li><li>MDT should perform + IOCS.</li><li>RH-ve women non sensitized.</li><li>IOCS – cord blood positive – 1500IU Anti D.</li><li>Keilhauer Test 30 – 40 min after Transfusion.</li><li>Use of leukocytes depletion filter – remove amniotic fluid cells but not Fetal cells – so Anti D need to be given</li></ul>
<h3><strong>Factor vIIa:</strong></h3>
<ul><li>Consider – but don’t delay surgery/ embolization.</li><li>Off – license.</li><li>Given after discussion with hematologist.</li></ul>
<h3><strong>Fibrinogen </strong><strong>concentrate – recommended:</strong></h3>
<ul><li>Levels in pregnancy 3.5 – 5.5</li><li>Off license.</li><li>Only in clinical trial.</li></ul>
<h3><strong>Anti-Fibrinolytic:</strong></h3>
<ul><li><em><strong>I/ Partum anemia.</strong></em></li></ul>
<p>Hb &lt; 7 = clinical decision.</p>
<ul><li><strong>P/P</strong> anemia = clinical decision.</li></ul>
<h3><strong>Jehovah’s </strong><strong>witness:</strong></h3>
<ul><li>Consent/ refusal documented.</li><li>Optimization of Hb.</li><li>Early intervention, uses of pharmacological, surgical treatment.</li><li>IOCS has role.</li><li>Blood sparing + techniques (clotting factor) are acceptable.</li><li>“no blood” wristband.</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
