INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-175668ee', 't-mm-09-023', 'html', '<ul><li>30% of twins.</li><li>Blastocyst transfer stage in IVF =&gt; MC twins.</li><li>80% Bidirectional channels – No complications but   risk of IUD.</li><li>Determine Chorionicity @ 11 – 13+6 weeks.</li><li>Not sure =&gt; photograph + 2nd opinion.</li><li>Still not sure =&gt;urgent referral to expert sonologist</li><li>Risk of 2nd  loss + neurodevelopmental morbidity.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
