INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-028', 'chap-mm-09-01', '15. VACCINATION IN PREGNANCY', 'Detailed medical reference and study guide on 15. VACCINATION IN PREGNANCY.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-013aa2b5', 't-mm-09-028', 'html', '<ul><li><strong>Types of immunity.</strong></li><li><em><strong>1. </strong></em><em><strong>Innate:</strong></em></li><li>Weak, Rapid response – in minutes.</li><li>Less specialized.</li><li>1st line of defense.</li></ul>
<h3>Components:</h3>
<ul><li>Monocytes, macrophages, epithelial cells, neutrophils</li><li><em><strong>2. </strong></em><em><strong>Adaptive:</strong></em></li><li>Strong, Slow response.</li><li>Specialized.</li></ul>
<h3>Components:</h3>
<ul><li>Lymphocytes &amp; their products.</li><li>Cytokines, antibodies.</li><li><strong>Types of Vaccines:</strong></li><li><em><strong>1. </strong></em><em><strong>Killed:</strong></em></li><li>Inferior to live, vaccine    safe in</li><li>Large doses required.     Pregnancy</li><li>Booster required.</li><li><em><strong>2. </strong></em><em><strong>Live:</strong></em>- C/I in pregnancy</li><li>Superior.- Given in</li><li>Single dose.consultation</li><li>Low dose.with Infectious</li><li>Booster not required.  disease specialist.</li></ul>
<h3><em><strong>3. </strong></em><em><strong>Purified Macro Molecules:</strong></em></h3>
<ul><li><strong>Inactive toxins:</strong></li><li>DPT – given in pregnancy @ 28 – 32 weeks.</li><li><strong>Conjugate vaccines:</strong></li><li>Hemophiluscan be given in</li><li>Influenza.Pregnancy under</li><li>Neisseriaspecial</li><li>Meningitidisconditions</li><li>Streptococcus</li><li>pneumoniae</li><li><strong>Sub unit:</strong></li><li>Hep B.</li></ul>
<h3><strong>Vaccination C/I in pregnancy:</strong></h3>
<ul><li>BCG.</li><li>Measles.</li><li>Mumps.</li><li>Rubella – avoid conception for 28 days.</li><li>varicella – avoid pregnancy for 28 days.</li><li>HPV</li></ul>
<h3><strong>Vaccines specifically indicated:</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b7316c96', 't-mm-09-028', 'heading', '1. DPT – 28 – 32weeks.', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-603319f6', 't-mm-09-028', 'html', '<ul><li>2. Influenza and COVID-19</li><li>@ any stage to all women.</li><li>Esp October – January.</li><li>Don’t give live influenza.</li></ul>
<p>3. Inactive polio.</p>
<p>(P – T – O)</p>
<h3><strong>Vaccines given in special circumstances:</strong></h3>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-99d0e658', 't-mm-09-028', 'html', '<table><tbody><tr><td><strong>Vaccines</strong></td><td><strong>Indications</strong></td></tr><tr><td>Hep A</td><td>1.  Long term liver disease.<br/>Hemophilia.<br/>Poor sanitary condition.<br/>Living near to sewage.<br/>Living with primates.<br/>Drug abusers.</td></tr><tr><td>Hep B</td><td>1. Sex workers.<br/>2. Living with Hep B positive.<br/>3. Drug abusers.<br/>4. Multiple sex partners.<br/>5. Regular transfusions.<br/>6. Liver disease or CKD.<br/>7. Travelling to endemic areas.</td></tr><tr><td>Meningococcal</td><td>1. Asplenia.<br/>2. Immune suppression.<br/>3. Complement deficiency.<br/>4. High risk endemics travel.<br/>5. University students &lt; 25 years of age<br/>6. Contact with infected individuals.</td></tr><tr><td>Pneumococcal</td><td>1. Asplenia.<br/>2. SCD.<br/>3. Splenectomy.<br/>4. HIV.</td></tr><tr><td>Typhoid</td><td>1. Travel to endemics.</td></tr><tr><td>Rabies</td><td>- Post exposure prophylaxis recommended<br/>- Pre – exposure prophylaxis – where risk of exposure to rabies is substantial.</td></tr><tr><td>Yellow fever</td><td>- High case fatality.<br/>- Given when travel is un avoidable.</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-23819d0c', 't-mm-09-028', 'html', '<p><strong>Breast Feeding:</strong><strong> </strong>after vaccination</p>
<ul><li>Not C/I not any precautions.</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-029', 'chap-mm-09-01', '16. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART', 'Detailed medical reference and study guide on 16. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART.', 29, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-65472e11', 't-mm-09-029', 'html', '<table><tbody><tr><td><strong>Condition</strong></td><td><strong>Incidence</strong></td><td><strong>Recommendations</strong></td></tr><tr><td>OHSS<br/>Risk of VTE<br/>PIH<br/>PTL</td><td>Mild – 33%.<br/>Mod – severe 3.1 – 8%.<br/>Risk of VTE = 0.7 – 10%.<br/>Upper body &amp; arterial system after resolution of OHSS.</td><td>Establish evidence based local protocols.<br/>Admission to nominated centers.<br/>Reporting to HEFA severe &amp; critical.</td></tr><tr><td>Miscarriages</td><td>15 – 20%</td><td>Manage as spontaneous miscarriage.<br/>Women should have access to specialist counselor before, during &amp; after ART.</td></tr><tr><td>Ectopic</td><td>1.4%</td><td>Same as miscarriage<br/>Careful inspection of adnexa on USG.<br/>Be mindful of heterotopic pregnancy</td></tr><tr><td>PIH – more if<br/>Age &gt; 35 years<br/>BMI &gt; 30.<br/>PCOS<br/>Multiple pregnancy</td><td>2% more than natural conception<br/>More in egg donation.<br/>Sperm donation or<br/>Embryo donation.</td><td>Risk assessment @ booking.<br/>Aspirin 75mg from 12 weeks if risk Factor positive (not on basis of ART).</td></tr><tr><td>GDM – more in PCOS</td><td>1%</td><td>ART not an indication of OGTT</td></tr><tr><td>VTE</td><td>Highest in 1st</td><td>Alone ART is not an indication for prophylaxis.<br/>Risk assessment.</td></tr><tr><td>Subclinical hypothyroidism</td><td>&nbsp;</td><td>Treatment of subclinical hypo    es risk of miscarriage in ART pregnancies (limited evidence).</td></tr><tr><td><strong>Fetal complications</strong></td></tr><tr><td>Structural Anomalies</td><td>30 – 40%     risk</td><td>&nbsp;</td></tr><tr><td>Oligospermia =&gt; Autosomal translocation or inversion 4.6 – 13.7%<br/>Microdeletion = 5 – 15%.</td><td>Absolute risk<br/>More in ICSI 6.5 – 7%</td><td>No additional surveillance.</td></tr><tr><td>IUGR:<br/>ART minor risk Factor for SGA</td><td>&nbsp;</td><td>No additional surveillance.</td></tr><tr><td>S. B</td><td>2.4-fold</td><td>Delivery @ Term IOL or C/Section</td></tr><tr><td>PTL</td><td>11.2% iatrogenic</td><td>No additional surveillance.</td></tr><tr><td><strong>Placental complications</strong></td></tr><tr><td>Placenta Previa</td><td>More in blastocyst stage Transfer than @ cleavage stage.</td><td>No additional surveillance</td></tr><tr><td>Placenta Accreta</td><td>&nbsp;</td><td>No additional surveillance</td></tr><tr><td>Abruption</td><td>&nbsp;</td><td>No additional surveillance</td></tr><tr><td>Vasa Previa</td><td>&nbsp;</td><td>If low lying placenta @ anomaly scan than TVS with Doppler to rule out Vasa Previa should be under taken.</td></tr></tbody></table>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-da1f75a8', 't-mm-09-029', 'html', '<p>Table 41. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART</p>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-030', 'chap-mm-09-01', '17.IMAGING IN PREGNANCY', 'Detailed medical reference and study guide on 17.IMAGING IN PREGNANCY.', 30, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c668d6bd', 't-mm-09-030', 'html', '<h3><strong>Ionizing radiations:</strong></h3>
<ul><li>1. x – ray</li><li>2.CT.</li><li>3.X RAYs &amp; Gamma RAYS =&gt; ionize the tissue =&gt; alter structure =&gt; by 2 ways.</li><li>Stochastic effect =&gt; development of carcinogenesis.</li><li>Deterministic effect =&gt; loss of tissue function because of cell death.</li></ul>
<p><em><strong>ALARA</strong></em><em><strong> Principle </strong></em></p>
<ul><li>As low as reasonably achievable</li><li>To minimize effect of ionizing radiations</li><li>Shielding   50% risk.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bb6f477d', 't-mm-09-030', 'html', '<table><tbody><tr><td><strong>Gest</strong><strong>ational</strong><strong> age</strong></td><td><strong>&lt; 50</strong><strong>mG</strong><strong>y</strong><br/><strong>&lt; 5 Rad</strong></td><td><strong>50 – 100 mGy</strong><br/><strong>5 – 10 Rad</strong></td><td><strong>&gt;100mGy</strong><br/><strong>&gt;Rad</strong></td><td><strong>Est</strong><strong>imated</strong><strong> threshold dose.</strong></td></tr><tr><td>0 – 2</td><td>No effect</td><td>No effect</td><td>No effect</td><td>50 – 100mGy</td></tr><tr><td>3 – 4</td><td>No effect</td><td>No effect</td><td>Spontaneous miscarriage</td><td>200mGy</td></tr><tr><td>5 – 10</td><td>No effect</td><td>No effect</td><td>Congenital anomaly (skeletal, Ophthalmic Genital tract)<br/>FGR</td><td>200 – 250</td></tr><tr><td>11 – 17</td><td>No effect</td><td>No effect</td><td>-    IQ or Retardation.<br/>-  Microcephaly (dose dependent).</td><td>60 – 310<br/>200</td></tr><tr><td>18 – 27</td><td>No effect</td><td>No effect</td><td>IQ    - not at diagnostic doses</td><td>&nbsp;</td></tr><tr><td>&gt; 27</td><td>No effect</td><td>No effect</td><td>Not applicable @ discharge medicine.</td><td>&nbsp;</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2fbbd54b', 't-mm-09-030', 'html', '<p>CT has better findings in diagnosing fetal skeletal dysplasia than MRI.</p>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f70888b0', 't-mm-09-030', 'html', '<table><tbody><tr><td><strong>Measurement</strong></td><td><strong>Trade Unit</strong></td><td><strong>Int Unit</strong></td></tr><tr><td><strong>Exposure </strong><br/>No of Ions by x – ray or Gamma – rays/ kilogram of air.</td><td>Roentgen</td><td>Coul umb</td></tr><tr><td><strong>Dose</strong><br/>amount of Energy<br/>Deposited per kg of tissue.</td><td>Rad</td><td>Gray</td></tr><tr><td><strong>Relative effective dose</strong><br/>Amount of radiation deposited per kg of tissue normalized for biological effectiveness.</td><td>Roentgen</td><td>Sievert</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-fecd7e2c', 't-mm-09-030', 'html', '<ul><li><strong>Use of contrast enhance accuracy</strong>.</li><li>Commonly used contrast in CT is iodine containing =&gt; Maternal effects.</li><li>Also, cross placenta but no fetal effects in animal’s studies.</li></ul>
<h3><strong>Types of Examination: </strong><strong>Fetal Radiation dose:</strong></h3>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-babb869b', 't-mm-09-030', 'html', '<table><tbody><tr><td><em><strong>Very low dose</strong></em> - &lt; 0.1mGy<br/>Cx spine x – ray (two view)<br/>CXR (two view)<br/>X ray extremities<br/>Mamogram two view.<br/>Head &amp; neck CT.</td><td>&lt; 0.001<br/>0.0005 – 0.1.<br/>&lt; 0.001<br/>0.001– 0.01.<br/>0.001– 0.01.</td></tr><tr><td><em><strong>Low – moderate dose</strong></em> – 0.01 – 10mGy<br/>Abdominal x – ray<br/>Lumber spine<br/>CT chest or pulmonary angiography<br/>Technetium as bone scintigraphy<br/>Pulmonary digital subtraction angiogram<br/>CT – pelvimetry</td><td>0.1 – 3.0<br/>1 – 10<br/>0.1 – 0.5<br/>4 – 5<br/>0.5<br/>&lt; 1</td></tr><tr><td><em><strong>Higher doses –</strong></em> 10 – 50mGy<br/>Abdominal – CT<br/>Pelvic CT.<br/>F – FDG PET/ CT whole body</td><td>1.3 – 35.<br/>10 – 50.<br/>10 – 50.</td></tr></tbody></table>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-2ae38dae', 't-mm-09-030', 'html', '<h3><strong>USG:</strong></h3>
<ul><li>Thermal effect.</li><li>Mechanical effect.</li></ul>
<p>Tissue damage by these (2) effects,   in Doppler,     in B – mode.</p>
<h3><strong>Cavitation:</strong></h3>
<ul><li>Inertial – transient.</li><li>Non inertial – stable.</li></ul>
<p>More effect if exposure exceeds 60 min.</p>
<h3><strong>MRI:</strong></h3>
<ul><li>Challenging in obstetrics – to perform and interpret due to fetal movements, MRI better than USG, Safe at any Gestation.</li></ul>
<h3>Gadolinium contrast:</h3>
<ul><li>Improve imaging – crosses placenta and fetal circulation and excreted in amniotic fluid =&gt; risk of fibrosis in nephrogenic system (not) statistically significant.</li><li>Risk of SB and neonatal death.</li><li>Risk of rheumatological, inflammatory skin diseases.</li></ul>
<p><em><strong>Avoid –</strong></em> Gadolinium in pregnancy.</p>
<h3><strong>Nuclear imaging:</strong></h3>
<ul><li>Thyroid scan, bone scan, Renal scan, V/P scan.</li><li>Most commonly use “isotope – tech 99)</li><li>Gamma rays emitted t/2 = 6 hours.</li><li>“rad iodine 13” t/2 = 8 days.</li><li>Cause fetal hypothyroidism in 10 – 12 weeks.</li><li>“F – FDG” in PET CT.</li></ul>
<p><em><strong>Avoid –</strong></em> Rad Iodine in pregnancy</p>
<p>Tech 99 &amp; F – FDG can be used =&gt; in thyroid scan use Tech 99 in place of radio Iodine.</p>
<h3><strong>V/P Scan/ CTPA:</strong></h3>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-38e6331d', 't-mm-09-030', 'html', '<table><tbody><tr><td><strong>Parameter</strong></td><td><strong>CTPA</strong></td><td><strong>V/P scan</strong></td></tr><tr><td>Availability</td><td>more</td><td>less</td></tr><tr><td>Fetal radiation exposure</td><td>&nbsp;</td><td>- Childhood cancers.</td></tr><tr><td>Identification of pathology.</td><td>more   pneumonia 5-7%.<br/>Pulmonary edema 2-6%.</td><td>Limited.</td></tr><tr><td>CA breast</td><td>20mGy<br/>10mGy before Age 35    es<br/>CA breast 13.6%.</td><td>none</td></tr></tbody></table>', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-73c3601d', 't-mm-09-030', 'html', '<h3><strong>Neurological imaging in Intracranial lesions:</strong></h3>
<p>CVACT/MRI &amp; angiogram</p>
<p>SCHCT without contrast</p>
<p>CVT central venousMRI &amp; MRV or CT &amp; CTV</p>
<p>Thrombosis</p>
<p>Arterial dissectionMRI, duplex scanning, MRA+CTA</p>
<p>Pituitary tumorMRI.</p>
<p>Chorioangioma CT or MRI.</p>
<p>Post reversible MRI</p>
<p>Encephalopathy</p>
<p>syndrome</p>
<p>Idiopathic I/C HTNMRI or MRA</p>
<h3><strong>Breast Mass</strong><strong>es: </strong></h3>
<ul><li>2 weeks =&gt; MDT.</li><li>USG + Biopsy =&gt; Malignancy positive =&gt; Mammography.</li><li>Further staging – CT, MRI + gadolinium.</li></ul>', 9) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-031', 'chap-mm-09-01', '18.MANAGEMENT OF PREGNANCY AFTER TRACHYLECTOMY', 'Detailed medical reference and study guide on 18.MANAGEMENT OF PREGNANCY AFTER TRACHYLECTOMY.', 31, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-16f7333e', 't-mm-09-031', 'html', '<h3><strong>Trachelectomy</strong><strong>:</strong></h3>
<ul><li>Removal of CX + surrounding tissues (parametrial/ upper vagina).</li><li>Neo Cervix formation by joining vagina and isthmus (or CX).</li><li>Insertion of cerclage.</li></ul>
<h3><strong>Risks:</strong></h3>
<ul><li>Spontaneous conception 61%.</li><li>Time from surgery to conception 31m0.</li><li>Live birth 62%.</li><li>Miscarriages:</li><li>1st  16% (15 – 20%) normal pregnancies.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3b175640', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image139.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-4810dc3d', 't-mm-09-031', 'html', '<ul><li>2nd  7% (4%).</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-cd9fd043', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image140.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e257c1b6', 't-mm-09-031', 'html', '<ul><li>Term delivery 54.8%.</li><li>Pre – Term 30 – 40% up to (45%).</li></ul>
<p>More cervix is excised =&gt; more risk of PTL</p>
<ul><li>10mm – risk of PTL.</li></ul>
<h3><strong>Contraception:</strong></h3>
<ul><li>POP – ineffective due to loss of CX and mucous plug.</li><li>IUCD – difficulty in insertion due to isthmic stenosis (insertion of foleyscatheter for 3days after surgery).</li><li>COC, implants, - UKMEC (2).</li></ul>
<p>Interval 2 – 3m0 between surgery and pregnancy =&gt;   risk of PTL.</p>
<p>6m0 C/C is recommended after surgery.</p>
<h3><strong>ANC:</strong></h3>
<ul><li>MDT – consultant led care.</li><li>Vaginal progesterone, 200mg, B.D, 12 – 36weeks.</li><li>Fortnightly serial scan of isthmic length by expert.</li><li>No need of another cerclage.</li><li>Urine examination and vaginal swabs for culture and sensitivity booking then @ 16 – 24 weeks. Repeat tests if clinically indicated.</li><li>Antibiotic cover if infection noted.</li><li>Avoid vaginal examination – unnecessary.</li><li>Avoid sexual inter course from 20 weeks as it    es infections.</li><li>Avoid exercise, weight lifting in 2nd .</li></ul>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-07b8297f', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image141.emf', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d0a16731', 't-mm-09-031', 'html', '<ul><li>Avoid elective dental work in pregnancy as it    es PTL.</li><li>A/B + steroids if PPROM.</li><li>EL – ISCS @ 37 weeks.</li><li>Planned + Pre labour C/S is recommended</li><li>Lower segment not formed so upper segment c section</li><li>Transverse incision/ classical incision.</li></ul>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-032', 'chap-mm-09-01', '19.MULTIFETAL PREGNANCY REDUCTION (MFPR) & SELECTIVE TERMINATION (ST)', 'Detailed medical reference and study guide on 19.MULTIFETAL PREGNANCY REDUCTION (MFPR) & SELECTIVE TERMINATION (ST).', 32, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e668c61c', 't-mm-09-032', 'html', '<ul><li>Incidence of twins and higher order from 10.1 to 15.8/1000 after ART.</li><li>IVF results 1/5 multiple pregnancies.</li><li>IVF doubles the risk of monozygocity especially in late blastocyst stage.</li></ul>
<h3><strong>Cerebral palsy</strong><strong>:</strong></h3>
<ul><li>1/400 in singleton.</li><li>1/100 in twins.</li><li>1/30 in triplets, 1/12 pregnancies.</li><li>1/10 in quadruplet, 4/10 pregnancies.</li></ul>
<h3><strong> </strong><strong>ST:</strong></h3>
<ul><li>Clause E – termination of abnormal fetus.</li></ul>
<h3><strong>MFPR:</strong></h3>
<ul><li>Clause C – Termination of 1 or 2 normal Fetus.</li></ul>
<h3><strong>Pre – requisites:</strong></h3>
<ul><li>Should be in fetal medicine unit.</li><li>Assessment:</li><li>Chorionicity before 14 weeks.</li><li>Documentation/ labelling of position, size Chorionicity, placental location and anatomic features.</li><li>All women with triplets or higher order pregnancies are offered MFPR.</li><li>Referral within 5 days of request.</li><li>Reduction before 16 weeks (11 – 14weeks) is offered.</li></ul>
<h3><strong>P</strong><strong>rocedures </strong><strong>that are</strong><strong> independent</strong><strong> of</strong><strong> </strong><strong>Chorionicity</strong><strong>  </strong></h3>
<h3><strong>[1</strong><strong>st</strong><strong> </strong><strong>  ST]</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ba8ee3f0', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a1d798ad', 't-mm-09-032', 'html', '<h3><strong>MFPR or ST.</strong></h3>
<ul><li>Between 11 – 14 weeks – 2 reasons:</li><li>Spontaneous miscarriages have occurred.</li><li>Anatomical survey is done including NT.</li></ul>
<p>Injection of 15% kcl, Intracardiac, 0.5 – 2ml till Asystole is confirmed.</p>
<ul><li>Choice of embryo depends on:</li><li>NT.</li><li>CRL – small twin.</li><li>Location of sac.</li><li>Markers of aneuploidy.</li><li>Technically approach able and furthest away from CX</li></ul>
<h3><strong>[3</strong><strong>rd </strong><strong> </strong><strong>S</strong><strong>T</strong></h3>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0221c846', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-98e7b82d', 't-mm-09-032', 'html', '<p>Don’t do MFPR after 16 weeks, only ST in 3rd</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c36429b6', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-feb44bf5', 't-mm-09-032', 'html', '<ul><li>Safest time is after 32 weeks – less chance of miscarriage and PTL (severe).</li><li>Prophylactic steroid before 32 weeks.</li><li>Intracardiac injection of KCL (5 – 10ml) or lidocaine (10 – 30ml) 1%.</li><li>Repeat diagnosis if differentiating features are absent.</li></ul>
<h3><strong>[Diagnosis and termination by same specialist]  </strong></h3>
<h3><strong>Procedures for </strong><strong>monochorionic</strong><strong> fetuse</strong><strong>s:</strong></h3>
<h3><em><strong>Radiofrequency ablation:</strong></em></h3>
<ul><li>RFA 15 – 27weeks.</li><li>17G RFA needle @ I/fetal portion of cord.</li><li>Energy applied @ RFA needle till temperature of 1100 for 3 min.</li><li>Done for MCDA twins for anomaly or SGA.</li></ul>
<p>Procedure of choice in MFPR @ earlier gestations. Also, for ST in Acardiac twin in TRAP.</p>
<h3><em><strong>Bipolar diathermy cord coagulation:</strong></em></h3>
<ul><li>18 – 27 weeks.</li><li>Intra Amniotic 2.7mm or 3.3mm S/C port is placed under L/A.</li><li>30 – 50 w diathermy for 60 sec till no flow in cord</li><li>Cord should be &lt; 12mm.</li></ul>
<h3><em><strong>Intra Fetal laser ablation:</strong></em></h3>
<ul><li>Intra-abdominal aortopelvic vessels.</li><li>ND – Yag laser.</li><li>When free loop of cord is not visible like TRAP.</li></ul>
<h3><em><strong>Su</strong></em><em><strong>ture Ligation – after 26 weeks:</strong></em></h3>
<ul><li>When cord is thick for RFA or diathermy or ablation.</li></ul>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-033', 'chap-mm-09-01', '20. ANTENATAL CORTICOSTEROID', 'Detailed medical reference and study guide on 20. ANTENATAL CORTICOSTEROID.', 33, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-302d83e3', 't-mm-09-033', 'html', '<h3><strong>ANTENATAL:</strong></h3>
<ul><li>PERINATAL INFECTIONS</li><li>GBS IN PREGNANCY</li><li>CHICKEN POX IN PREGNANCY</li><li>HIV IN PREGNANCY</li><li>HERPES SIMPLEX IN PREGNANCY</li><li>MALARIA IN PREGNANCY</li><li>COVID-19 IN PREGNANCY</li><li>CMV IN PREGNANCY</li><li>LISTERIA IN PREGNANCY</li><li>TOXOPLASMOSIS IN PREGNANCY</li><li>RUBELLA</li><li>SYPHILIS IN PREGNANCY</li><li>PARVOVIRUS IN PREGNANCY</li><li>HEMOPHLIS INFLUENZA IN PREGNANCY</li><li>MATERNAL SEPSIS DURING AND FOLLOWING PREGNANCY</li><li>OBSTETRIC CHOLESTASIS</li><li>REDUCED FETAL MOVEMENTS</li><li>SMALL FOR GESTATIONAL AGE</li><li>CARE OF LATE INTRAUTERINE FETAL DEATH AND STILL BIRTH</li><li>PLACENTA PREVIA</li><li>BLOOD TRANSFUSION IN OBSTETRIC</li><li>MULTIPLE PREGNANCIES</li><li>MONOCHORIONIC TWINS</li><li>POLYHYDRAMNIOS IN SINGLETON</li><li>ANTEPARTUM HAEMORRHAGE</li><li>VASA PREVIA</li><li>ANTENATAL CARE OF UNCOMPLICATED PREGNANCIES</li><li>VACCINATION IN PREGNANCY</li><li>ANC OF SINGLETON PREGNANCY CONCEIVED USING ART</li><li>IMAGING IN PREGNANCY</li><li>MANAGEMENT OF PREGNANCY AFTER TRAACHYLECTOMY</li><li>MULTIFETAL PREGNANCY REDUCTION</li><li>ANTENATAL CORTICOSTEROIDS</li><li>CERVICAL CERCLAGE</li></ul>
<h3><strong>Benefits:</strong></h3>
<h3><strong>If given </strong><strong>within</strong><strong> 7 </strong><strong>days</strong><strong> of preterm birth</strong></h3>
<p>Perinatal and neonatal death</p>
<p>RDS</p>
<ul><li><strong>If given in planned c section between 37-38+6 weeks </strong></li><li>NICU admission for RDS</li><li>Uncertainty in RDS reduction</li><li>Uncertainty in TTN reduction</li><li>Uncertainty in overall NNU admission</li></ul>
<h3><strong>Risks:</strong></h3>
<p>Hypoglycemia to neonate</p>
<p>Potential developmental delay</p>
<h3><strong>Steroid talk:</strong></h3>
<ul><li>Discussion before offering or considering steroid.</li></ul>
<p>Should involve women in discussion</p>
<p>Informed decision of women should be there</p>
<p>It is Gestation related</p>
<ul><li>Discussion should be based on following points</li></ul>
<p>Table 42. ANTENATAL CORTICOSTEROID</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c1e73547', 't-mm-09-033', 'html', '<table><tbody><tr><td><strong>Gestation</strong></td><td><strong>Benefits</strong></td><td><strong>Risks</strong></td><td><strong>Uncertainties </strong></td></tr><tr><td>22 – 34+6 weeks</td><td><strong>Highly likely:</strong><br/>NND<br/>Perinatal death<br/>RDS<br/><strong>Likely</strong><br/>Interventricular haemorrhage<br/>Developmental delay<br/>Benefits are more if birth occurs 24 – 48 hours after treatment<br/>Respiratory morbidity reduction is likely if birth occurs within 7 days of treatment.</td><td><strong>Likely:</strong><br/>Affect maternal OGTT up to 5 days<br/>Birth weight if birth occurs after 7 days.<br/><strong>May:</strong><br/>Psychiatric diagnosis and Behavioral problem in children</td><td>Long term harms<br/>Risks/ benefits in multiple pregnancies.</td></tr><tr><td>35 – 36+6 weeks</td><td><strong>Likely:</strong><br/>Respiratory support</td><td><strong>Likely:</strong><br/>Neonatal hypoglycemia<br/><strong>May    :</strong><br/>Psychiatric and behavioral diagnosis</td><td>Benefits are unlikely if birth is after 7 days.</td></tr><tr><td>Planned C/S<br/>@ 37 – 39weeks</td><td><strong>May    :</strong><br/>NNU admission with respiratory morbidity</td><td><strong>May   :</strong><br/>Educational attainment @ school</td><td>Reduction in:<br/>RDS<br/>TTN<br/>Overall NNU admission<br/>Short term hypoglycemia<br/>Benefits are unlikely if birth occurs after 7 days.</td></tr><tr><td>Rescue course if treatment &gt;7 days</td><td><strong>Likely</strong><strong>    </strong><strong>:</strong><br/>Need for respiratory support</td><td><strong>Likely    :</strong><br/>Birth weight<br/>Head circumference<br/>Length<br/>Neonatal B.P</td><td>Dose dependent effects.</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7833e173', 't-mm-09-033', 'html', '<h3><strong>Recommendations of Steroids:</strong></h3>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-40185bcf', 't-mm-09-033', 'html', '<table><tbody><tr><td>Before 24 weeks</td><td>Discuss</td></tr><tr><td>24 – 34+6 weeks where preterm is anticipated</td><td>Discuss and offer</td></tr><tr><td>35 – 36+6</td><td>Consider the balance of risks and benefits</td></tr><tr><td>Twins and triplets</td><td>Targeted steroid same as singleton<br/>Only targeted used</td></tr><tr><td>Diabetes Mellitus</td><td>Not a contraindication<br/>Additional insulin and close monitoring<br/>Steroid discussion with women or her carer @ 37 – 38+6 weeks about the risk and benefits, corticosteroids are associated with neonatal hypoglycemia.</td></tr><tr><td>Hypertension</td><td>Offer after discussion in case of planned early birth<br/>Offer to SGA, FGR babies if birth is expected earlier but inform regarding lack of evidence.</td></tr><tr><td>PPROM</td><td>Offer if birth is expected to be preterm<br/>Limited evidence to recommend repeat courses, however further courses may reduce need for neonatal respiratory support.</td></tr></tbody></table>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-89e4be81', 't-mm-09-033', 'html', '<h3><strong>Dose and route of Steroids:</strong></h3>
<ul><li>Dexamethasone Phosphate, I/M:</li><li><strong>24 mg</strong></li></ul>
<p>2 doses4 doses</p>
<p>12 mg6 mg</p>
<p>24 hours apart12 hours apart</p>
<ul><li>Betamethasone sodium Phosphate/ Acetate mix, I/M:</li></ul>
<p>24mg total</p>
<p>2 doses</p>
<p>24 hours apart</p>
<h3><strong>How long after Administration is a course more effective:</strong></h3>
<ul><li>After 48 hours of dose, Neonatal death is reduced.</li><li>After 24 hours of 1st dose, benefits seen</li><li>Most effective in reducing RDS if birth occurs between 24 hours to 7 days of 2nd dose.</li></ul>
<h3><strong>Contraindications of Steroid:</strong></h3>
<ul><li>Systemic infections</li><li>In case of serious concerns, birth should not be delayed to administer steroid.</li></ul>
<h3><strong>Repeat Course of Steroids:</strong></h3>
<p>No reduction in serious morbidity or long-term benefits to babies instead risk of low birth weight and reduced length</p>
<p>Limited evidence to recommend repeat course of steroid.</p>
<p>Repeat course reduce need for neonatal respiratory support</p>
<p>Repeat courses should not exceed three.</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-09-034', 'chap-mm-09-01', '21. CERVICAL CERCLAGE', 'Detailed medical reference and study guide on 21. CERVICAL CERCLAGE.', 34, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9ac07918', 't-mm-09-034', 'html', '<h3><strong>Definitions</strong><strong>:</strong></h3>
<ul><li><em><strong>History indicated Cerclage:</strong></em></li></ul>
<p>Cerclage as a result of factors in a women’s obstetric or gyaecological history which     the risk of spontaneous 2nd  loss or preterm birth.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-002b7b8b', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-4bb53b47', 't-mm-09-034', 'html', '<p>Prophylactic cerclage</p>
<p>Offer @ 11 – 14 weeks.</p>
<ul><li><em><strong>Ultrasound indicated cerclage:</strong></em></li></ul>
<p>Cerclage is inserted as a therapeutic measure in cases of cervical length shortening seen on transvaginal ultrasound.</p>
<p>Prophylactic length is measured between 14 – 24 weeks by TVS and with an empty bladder</p>
<p>Done if cervical length is &lt;25m @ gestation &lt;24 weeks.</p>
<ul><li><em><strong>Emergency cerclage/ Physical exam indicated cerclage:</strong></em></li></ul>
<p>Insertion of cerclage as salvage measure in case of premature cervical dilatation with exposed fetal membranes in vagina</p>
<p>Pt can present with vaginal discharge, bleeding or sensation of pressure</p>
<p>Can be applied up to 27+6 weeks</p>
<h3><strong>Types of Cerclage:</strong></h3>
<ul><li><em><strong>Transvaginal (McDonald):</strong></em></li><li>Suture placed @ cervical isthmus junction without bladder mobilization.</li><li><em><strong>High transvaginal cerclage (</strong></em><em><strong>Shirodkar</strong></em><em><strong>)</strong></em></li><li>Purse string suture placed following bladder mobilization, to allow insertion above the level of cardinal ligaments.</li><li><em><strong>Transabdominal Cerclage:</strong></em></li><li>Suture performed via laparotomy or laparoscopy, placing the suture @ cervico isthmic junction.</li><li><em><strong>Occlusion Cerclage:</strong></em></li><li>Occlusion of external OS by placement of a continuous non-absorbable suture.</li><li>Purpose is the retention of mucus plug.</li></ul>
<h3><strong>Recommendations of Cervical Cerclage:</strong></h3>
<ul><li><strong>History indicated</strong></li></ul>
<p>3 or more preterm birth or 2nd  miscarriages.</p>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a2b7a3b8', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a68119b7', 't-mm-09-034', 'html', '<p>It reduces perinatal death</p>
<p>No benefit of this cerclage to those who has previous cervical surgery or uterine anomalies</p>
<p>It is unknown that the characteristics of previous events are helpful or not (painless dilatation, rupture of membranes, prior cervical surgery).</p>
<ul><li><strong>Ultrasound indicated:</strong></li></ul>
<p>Not affected to those who has incidental short length in late 2nd  without risk factors.</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-811bd079', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7190c98a', 't-mm-09-034', 'html', '<p>Offered to those who had one or more preterm birth or 2nd loss along with cervical length &lt;25mm measured @ &lt;24weeks.</p>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-1c987984', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-dd0136a9', 't-mm-09-034', 'html', '<p>Not offered to those who has cervical funneling without short cervical length &lt;25mm</p>
<p>USG surveillance of cervical length is offered to those who have previous preterm birth or 2nd  loss, by TVS with empty bladder and @ 16 – 24weeks, every 2 – 4weeks.</p>', 9) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-1be92f77', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 10) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-96abec1c', 't-mm-09-034', 'html', '<ul><li>Other women where cervical length need to be measured are either high risk or intermediate risk.</li></ul>
<h3><strong>High Risk:</strong></h3>
<ul><li>Previous PPROM &lt; 34 weeks</li><li>Previous use of cerclage</li><li>Known uterine variant</li><li>Intrauterine adhesions</li><li>History of trachelectomy</li></ul>
<h3><strong>Intermediate Risk:</strong></h3>
<ul><li>Previous C/S at full dilatation</li><li>LLETZ with excision depth &gt;1cm, more</li><li>than 1 procedure or more than 1 cone biopsy.</li></ul>
<h3><strong>Multiple Pregnancy:</strong></h3>
<ul><li>not offered either cerclage</li></ul>
<h3><strong>Raised BMI:</strong></h3>
<ul><li>BMI &gt;25, cerclage is effective in those who has cervical length &lt;25mm</li></ul>
<h3><strong>Transabdominal Cervical Cerclage:</strong></h3>
<ul><li>Consider and discuss in women with failed or unsuccessful transvaginal cerclage</li><li>Can be performed pre conceptually or in early pregnancy. Pre conceptually performed cerclage is more effective than antenatal cerclage. It is not associated with subfertility</li><li>Can be performed laparoscopically</li><li>Laparoscopy should be considered where possible as it has fewer complication.</li><li>In case of delayed miscarriage or fetal death, decision of TOP is difficult up to 18 weeks suction curettage or dilatation and curettage can be performed via stitch.</li><li>&gt;18 weeks, stitch can be opened via posterior colpotomy. Failed colpotomy can led to hysterotomy or C/S. decision should be aided by senior obstetrician.</li></ul>
<h3><strong>Emergency Cerclage:</strong></h3>
<ul><li>Individualized decision by taking into account the risks and benefits.</li><li>Women’s decision should be aided by senior obstetrician</li><li>It can prolong pregnancy up to 34 weeks</li><li>It can reduce chance of birth by 2-fold before 34 weeks.</li><li>Advanced dilatation of cervix &gt; 4cm or membrane prolapse beyond external os appears to be associated with higher cerclage failure.</li><li>Not justified beyond 24 weeks due to</li><li>potential risk of iatrogenic membrane rupture and subsequent preterm.</li></ul>
<h3><strong>Contraindications of cerclage:</strong></h3>
<ul><li>1. active preterm labour</li><li>2. clinical Chorioamnionitis</li><li>3. continuing vaginal bleeding.</li></ul>', 11) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-509b680f', 't-mm-09-034', 'heading', '4. PPROM', 12) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5637f608', 't-mm-09-034', 'html', '<ul><li>5. Evidence of fetal defects</li><li>6. Lethal fetal defects</li><li>7. Fetal death</li></ul>
<h3><strong>Risk of cervical cerclage:</strong></h3>
<ul><li>Small risk of intraoperative bladder damage, cervical trauma, membrane rupture, bleeding.</li><li>Cervical trauma/ laceration in case of labour with suture in place.</li><li>High vaginal cerclage needs anaesthesia for insertion and removal.</li><li>No association with PPROM, Chorioamnionitis IOL or C/S (except Emergency cerclage).</li><li>No association with preterm birth or 2nd  loss (except emergency cerclage).</li></ul>', 13) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-3fc5edfe', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 14) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0214b171', 't-mm-09-034', 'html', '<ul><li>Risks and benefits should be discussed with women, both verbal and written information should be given before insertion of cerclage.</li></ul>
<h3><strong>Investigation before cerclage insertion:</strong></h3>
<ul><li>1. History indicated cerclage.</li><li>1st  USG</li></ul>', 15) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-05d4d925', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 16) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-0c1612dc', 't-mm-09-034', 'html', '<ul><li>Aneuploidy screening</li></ul>', 17) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-af1a435d', 't-mm-09-034', 'heading', '2. USG indicated or emergency cerclage anomaly scan.', 18) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8833ae48', 't-mm-09-034', 'heading', '3. CRP + TLC count if clinical picture exists.', 19) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8e866132', 't-mm-09-034', 'html', '<ul><li>TLC cut off &lt;14,000/micro liter</li><li>CRP cut off &lt;4 mg/dl</li><li>4. Amniocentesis</li><li>Not before ultrasound or history indicated cerclage</li><li>Can be done before emergency cerclage in cases where there is clinical suspicion of Intra amniotic infection.</li><li>5. Amnioreduction</li><li>No data exists</li><li>6. Genital Screening</li><li>Not undertaken routinely</li></ul>
<h3><strong>Operative issues:</strong></h3>
<ul><li>Can be performed safely as day case procedure</li><li><em><strong>Tocolysis:</strong></em></li><li>Consider on individual basis</li><li>Not routinely</li><li><em><strong>Antibiotics before cerclage</strong></em></li><li>Surgeon’s choice</li><li><em><strong>Anaesthesia</strong></em></li><li>Decision by operating team along with women</li><li><em><strong>Suture material</strong></em></li><li>Non absorbable suture, surgeon’s discretion.</li><li><em><strong>Type of cerclage:</strong></em></li><li>Depends on surgeon’s choice</li><li>High/ low cerclage has similar outcome.</li><li>Try to place suture in cervix as high as possible</li><li>No difference between two possible string or single suture. It’s surgeon’s discretion.</li><li>Occlusion suture in addition to primary suture not applied routinely</li></ul>
<h3><strong>Bed Rest:</strong></h3>
<ul><li>Not recommended routinely</li></ul>
<h3><strong>Sexual intercourse:</strong></h3>
<ul><li>Abstinence not recommended routinely.</li></ul>
<h3><strong>Post cerclage serial USG for cervical length:</strong></h3>
<ul><li>Not done routinely</li><li>Selected USG indicated cerclage cases to offer timely steroid and in utero transfer.</li></ul>
<h3><strong>Fetal </strong><strong>fibronectin</strong><strong>:</strong></h3>
<ul><li>Not recommended routinely</li><li>High negative predictive value can reassure the women.</li></ul>
<h3><strong>Progesterone supplementation:</strong></h3>
<ul><li>Not recommended routinely</li></ul>
<h3><strong>Arabian pessary or progesterone</strong></h3>
<ul><li>None of them is more effective than cerclage</li></ul>
<h3><strong>Removal of Cerclage:</strong></h3>
<ul><li>1. @ 36+1 – 37weeks before labour</li><li>2. Women presenting in active labour, remove cerclage to prevent cervical trauma.</li><li>3. Abdominal cerclage need not to be removed. Deliver by C/S and leave cerclage in place.</li></ul>
<h3><strong>PPROM and Cerclage removal:</strong></h3>
<ul><li>PPROM between 24 – 34 weeks + No infections =&gt; Delayed removal by 48 hours.</li><li>Delayed removal until labour ensures or birth indicated is associated with an     risk of maternal/fetal sepsis and is not recommended.</li></ul>', 20) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
