INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-014', 'chap-mm-10-01', '3.3.WOMAN ON LONG TERM SYSTEMIC STEROIDS', 'Detailed medical reference and study guide on 3.3.WOMAN ON LONG TERM SYSTEMIC STEROIDS.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-7a856ecc', 't-mm-10-014', 'html', '<h3><strong>Stress Dose Steroids:</strong></h3>
<p>Women with adrenal insufficiency</p>
<p>Taking long term steroid</p>
<ul><li>Prednisolone 5mg daily or more for &gt; 3 months.</li><li>Continue regular oral steroid.</li><li>Give stress steroids</li><li><em><strong>1. </strong></em><em><strong>In Labo</strong></em><em><strong>u</strong></em><em><strong>r:</strong></em></li><li>Hydrocortisone 50mg I/V or I/m</li><li>Every 6 hours till delivery</li><li>And 6 hours after birth.</li></ul>
<h3><em><strong>2. In planned C/S:</strong></em></h3>
<ul><li>100mg Hydrocortisone I/V before induction of anesthesia</li><li>50mg 6 hours after birth.</li></ul>
<h3><em><strong>3. In Emergency C/S:</strong></em></h3>
<ul><li>50mg hydrocortisone I/V (if women have received 50mg in labor).</li><li>50mg 6 hours after birth.</li></ul>
<p>No need of stress dose in women who are taking topical or inhalational steroids.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-015', 'chap-mm-10-01', '3.4.BLEEDING DISORDERS', 'Detailed medical reference and study guide on 3.4.BLEEDING DISORDERS.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9659c075', 't-mm-10-015', 'html', '<h3><strong>Analgesia and Anesthesia:</strong></h3>
<p>Discuss benefits and risks of regional anesthesia</p>
<p>Take into accent</p>
<ul><li>1. Overall risk of bleeding</li><li>2. Availability of corrective treatment</li><li>3. Therapeutic and prophylactic anticoagulation</li><li>4. Risk of bleeding with technique used</li><li>5. Difficulty of needle sitting or insertion</li><li>6. Risk of general anesthesia</li><li>7. Risk of no analgesia or non-regional analgesia (comparative risk).</li><li><em>(Table on next page)</em></li></ul>
<h3><strong>Table: Modifying the birth plan according to maternal platelet count in women with immune thrombocytopenic purpura or gestational thrombocytopenia:</strong></h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-fc162d13', 't-mm-10-015', 'html', '<table><tbody><tr><td><strong>Maternal platelet count</strong></td><td><strong>Maternal care</strong></td></tr><tr><td>Platelet count<br/>above 80×109/l</td><td>Treat the woman as healthy for the purpose of considering<br/>regional analgesia and anaesthesia</td></tr><tr><td>Platelet count 50 to<br/>80×109/l</td><td>Before considering regional analgesia and anaesthesia, take into<br/>account:<br/>• clinical history<br/>• the woman\'s preferences<br/>• Anaesthetic expertise</td></tr><tr><td>Platelet count<br/>below 50×109/l</td><td>Avoid regional analgesia and anaesthesia under most circumstances</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-1d021ecc', 't-mm-10-015', 'html', '<h3><strong>Birth Plan:</strong></h3>
<ul><li>Babies @ risk of bleeding in ITP.</li></ul>
<h3><strong>Maternal care:</strong></h3>
<p>platelet count weekly after 36 weeks.</p>
<p>Birth in obstetric led unit with high dependency care for neonate.</p>
<p>MDT after platelets &lt; 50 including hematologist.</p>
<p>Consider giving steroid or immunoglobulins to raise platelet if count is &lt; 50.</p>
<p>Platelet count @ time of admission.</p>
<h3><strong>Neonatal care:</strong></h3>
<p>Inform neonatal team</p>
<h3>Don’t do:</h3>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bb6d92b6', 't-mm-10-015', 'heading', '1. FBS', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-f19350ca', 't-mm-10-015', 'html', '<ul><li>2. Ventouse delivery</li></ul>
<h3>Caution doing:</h3>
<ul><li>1. Mid – cavity or rotational Forceps.</li><li>Fetal scalp electrodes.</li></ul>
<p>Measure platelets in umbilical cord blood</p>
<p>C/S may not protect baby form bleeding</p>
<h3><strong>3</strong><strong>rd</strong><strong> stage of Labor:</strong></h3>
<p>ed risk of primary and secondary hemorrhage</p>
<p>Active management of 3rd stage.</p>
<p>Avoid I/M uterotonics</p>
<p>Individualized postpartum care plan by MDT including hematologist to include</p>
<ul><li>1. Measurement of blood loss</li><li>2. Monitoring of obstetric complication</li><li>3. Monitoring of hematological parameters.</li></ul>
<p>Avoid NSAIDS</p>
<p>Before discharge inform women about secondary PPH</p>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-016', 'chap-mm-10-01', '3.5.SUB ARACHNOID HAEMORRHAGE OR AV MALFORMATIONS OF THE BRAIN', 'Detailed medical reference and study guide on 3.5.SUB ARACHNOID HAEMORRHAGE OR AV MALFORMATIONS OF THE BRAIN.', 16, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-445b193c', 't-mm-10-016', 'html', '<p>Risk assessment by MDT including an expert in neurovascular conditions in pregnancy.</p>
<ul><li>Involve women in decision making.</li></ul>
<h3><strong>Low risk:</strong></h3>
<ul><li>Fully treated CV malformation</li><li>Intracranial bleeding of unknown cause</li><li>2years ago.</li></ul>
<h3><strong>Mode of birth and 2</strong><strong>nd</strong><strong> stage of labor:</strong></h3>
<ul><li>According to women’s preference and obstetric indications.</li></ul>
<h3><strong>High Risk:</strong></h3>
<ul><li>Untreated or partially treated CV malformation that has bled previously</li><li>Large aneurysm 7mm or more</li><li>Complex AV malformation</li><li>Cavernoma with high-risk features</li><li>Intracranial bleeding within past 2 years.</li></ul>
<h3><strong>Mode of Birth:</strong></h3>
<ul><li>C/S after discussion with women</li><li>In case of vaginal delivery</li><li>(1) offer regional analgesia</li><li>(2) explain benefits and risk of an assisted 2nd stage of labor compared with active pushing alone.</li><li>Avoid regional anaesthesia in case of genetic predisposition to multiple vascular malformations or unknown genetic history.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-017', 'chap-mm-10-01', '3.6.RENAL DISEASE', 'Detailed medical reference and study guide on 3.6.RENAL DISEASE.', 17, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-09b06c75', 't-mm-10-017', 'html', '<ul><li>Risk assessment by MDT Including a clinician with expertise in managing renal conditions pregnancy.</li><li>Intrapartum care by MDT including midwife obstetrician and obstetric anesthetist in following renal conditions.</li><li>CKD stage 4,5.</li><li>Active kidney disease</li><li>Progressive kidney disease</li><li>Monitoring during labour</li><li>1 hourly – HR</li><li>hourly:</li><li>1) B.P</li><li>2) RR and Chest Auscultation</li><li>3) Intake/ Output balance</li><li>4) SPo2</li><li>5) RFT’s every 24 hours during intrapartum period in all women with CKD because prolonged labor may lead to dehydration and AKI</li></ul>
<h3><strong>Fluid Balance:</strong></h3>
<ul><li>Individualized plan for managing fluid balance.</li><li>Additional monitoring to avoid both dehydration and pulmonary edema.</li><li>In case of dehydration give fluid bolus of 250ml of crystalloids. Monitor urine output after 1 hour of bolus. Give another bolus if needed.</li></ul>
<p>RFT’s and fluids balance monitoring until AKI is resolved.</p>
<ul><li>Avoid nephrotoxic drugs.</li></ul>
<h3><strong>Monitoring after birth:</strong></h3>
<ul><li>Monitoring 4 hourly for 24 hours.</li><li>B.P</li><li>HR</li><li>RR</li><li>Chest Auscultation</li><li>Intake and output of fluids.</li><li>Oxygen saturation</li><li>Postpartum assessment of RFT’s and follow up of women with persistent disease.</li></ul>
<h3><strong>Timing and mode of Delivery:</strong></h3>
<ul><li>Planning of intrapartum care during pregnancy in collaboration with expert especially in patients with nephritis, vasculitis or glomerulonephritis and renal transplant.</li><li>Involve transplant surgeon in care plan of patients with renal transplant.</li></ul>
<h3><strong>CKD</strong></h3>
<ul><li>Stage 1 + nephrotic range proteinuriaStage 2 + stable renal functionStage 3 + stable renal functionStage 4 + stable renal functionPlanned birth @ 40 weeksStage 1 + nephrotic range proteinuriaStage 2 + stable renal functionStage 3 + stable renal functionStage 4 + stable renal functionPlanned birth @ 40 weeksStage 1 + nephrotic range proteinuriaStage 2 + stable renal functionStage 3 + stable renal functionStage 4 + stable renal functionPlanned birth @ 40 weeksStage 1 + nephrotic range proteinuriaStage 2 + stable renal functionStage 3 + stable renal functionStage 4 + stable renal functionPlanned birth @ 40 weeks</li><li>Stage 1 +</li><li>Stable renal function +</li><li>Non – nephrotic range</li><li>proteinuria</li><li>protein: creatinine</li><li>&lt; 300mg/mmol</li><li>Renal Transplant</li><li>Women’s preferences</li><li>and obstetric indications.</li><li>Stage 5Stage 4Stage 3b + deteriorationDiscuss with MDTPlan @ 38 weeks if she is at &gt; 34 weeks.Prolong at least at 34 weeks. If it is before 34 weeks and discuss option of dialysis in order to prolong till 34 weeks.Stage 5Stage 4Stage 3b + deteriorationDiscuss with MDTPlan @ 38 weeks if she is at &gt; 34 weeks.Prolong at least at 34 weeks. If it is before 34 weeks and discuss option of dialysis in order to prolong till 34 weeks.Stage 5Stage 4Stage 3b + deteriorationDiscuss with MDTPlan @ 38 weeks if she is at &gt; 34 weeks.Prolong at least at 34 weeks. If it is before 34 weeks and discuss option of dialysis in order to prolong till 34 weeks.Stage 5Stage 4Stage 3b + deteriorationDiscuss with MDTPlan @ 38 weeks if she is at &gt; 34 weeks.Prolong at least at 34 weeks. If it is before 34 weeks and discuss option of dialysis in order to prolong till 34 weeks.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-018', 'chap-mm-10-01', '3.7.OBESITY', 'Detailed medical reference and study guide on 3.7.OBESITY.', 18, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-019', 'chap-mm-10-01', '3.8.WOMAN WITH OBSTETRIC COMPLICATIONS OR NO ANTENATAL CARE', 'Detailed medical reference and study guide on 3.8.WOMAN WITH OBSTETRIC COMPLICATIONS OR NO ANTENATAL CARE.', 19, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9029c3a1', 't-mm-10-019', 'html', '<ul><li>More anxious</li><li>Need information regarding birth plan, risks and benefits of options of care</li><li>Involve them in decision making</li><li>Provide information about care in labor and mode of birth according to personalized circumstances and local/ national guidance.</li></ul>
<h3><strong>Recognize following risk/ Concerns:</strong></h3>
<ul><li>Pyrexia</li><li>Sepsis</li><li>Breach presentation</li><li>Suspected SGA</li><li>Suspected LGA</li><li>Previous C/S</li><li>No ANC</li><li>If any of above is observed, escalate the care as needed.</li><li>Observe following parameters</li><li>1 hourly – pulse</li><li>4 hourly – B.P, Temperature</li><li>Record urine output.</li><li>Adjust observations when needed.</li></ul>
<h3><strong>Observations of women with.</strong></h3>
<ul><li>Temp &gt; 380C one reading.</li><li>Temp &gt; 37.50C on two readings 1 hour apart</li><li>Sepsis or suspected sepsis</li><li>APH</li></ul>
<p>Follow the table</p>
<h3>Table 50. Routine maternal observations for women in labour with fever, suspected sepsis, sepsis or intrapartum haemorrhage:</h3>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c6a75b25', 't-mm-10-019', 'html', '<table><tbody><tr><td><strong>Maternal observations</strong></td><td><strong>Fever</strong></td><td><strong>Suspected sepsis – </strong><strong>concern</strong><strong> </strong><strong>insufficient</strong><strong> </strong><strong>for </strong><strong>antibiotic</strong><strong> </strong><strong>treatment</strong></td><td><strong>Sepsis</strong><strong> </strong><strong>or</strong><strong> </strong><strong>suspected sepsis – on </strong><strong>antibiotic</strong><strong> </strong><strong>treatment</strong></td><td><strong>Intrapartum</strong><strong> </strong><strong>haemorrhage</strong></td></tr><tr><td>Pulse</td><td>Hourly</td><td>Hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least hourly</td></tr><tr><td>Blood pressure</td><td>4-hourly, and hourly in the second stage</td><td>4-hourly, and hourly in the second stage</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly, and at least hourly in the second stage</td></tr><tr><td>Respiratory rate</td><td>4-hourly</td><td>4-hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly</td></tr><tr><td>Temperature</td><td>Hourly</td><td>Hourly</td><td>Hourly</td><td>At least 4-hourly</td></tr><tr><td>Level of consciousness (AVPU)</td><td>Hourly</td><td>Hourly</td><td>Every 30 minutes</td><td>Hourly</td></tr><tr><td>Oxygen saturation</td><td>4-hourly</td><td>4-hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly</td></tr><tr><td>Urine</td><td>Record output</td><td>Record output</td><td>Record output, hourly if catheterized</td><td>Record output, hourly if catheterized</td></tr></tbody></table>', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-020', 'chap-mm-10-01', '3.9.PYREXIA', 'Detailed medical reference and study guide on 3.9.PYREXIA.', 20, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-126158ea', 't-mm-10-020', 'html', '<ul><li>Paracetamol for pyrexia</li><li>Don’t delay investigations of sepsis</li><li>Fetal monitoring + in line with sepsis or suspected sepsis.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-021', 'chap-mm-10-01', '3.10.SEPSIS', 'Detailed medical reference and study guide on 3.10.SEPSIS.', 21, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-022', 'chap-mm-10-01', '3.11.INTRA – PARTUM HAEMORRHAGE', 'Detailed medical reference and study guide on 3.11.INTRA – PARTUM HAEMORRHAGE.', 22, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-bb8d59ae', 't-mm-10-022', 'html', '<ul><li><strong>Causes:</strong></li><li>Placenta previa</li><li>Placental abruption</li><li>Vasa previa</li><li>Uterine rupture</li><li>Most of the times no cause</li></ul>
<h3><strong>History:</strong></h3>
<ul><li>Amount of blood loss</li><li>Pain</li><li>Previous surgery</li><li>Any other concern</li><li>Previous scan to check localization of placenta</li><li><strong>Examination:</strong></li></ul>
<h3><strong>Blood loss:</strong></h3>
<ul><li>characteristics of blood</li><li>Colour</li><li>Presence of clots</li><li>Amniotic fluid</li></ul>
<h3><strong>Physical examination:</strong></h3>
<ul><li>Vital signs</li><li>Abdominal palpation</li><li>Speculum examination</li><li>Vaginal examination if previa has been excluded</li><li>FHR</li></ul>
<h3><strong>Management</strong></h3>
<ul><li>Start CTG</li><li>Blood group and CBC</li><li>MDT Senior obstetricianSenior obstetric anesthetistSenior midwifeLabour ward coordinatorMDT Senior obstetricianSenior obstetric anesthetistSenior midwifeLabour ward coordinatorMDT Senior obstetricianSenior obstetric anesthetistSenior midwifeLabour ward coordinatorMDT Senior obstetricianSenior obstetric anesthetistSenior midwifeLabour ward coordinatorJust a showNot a show</li></ul>
<p>Manage as normal labour</p>
<ul><li><strong>Unstable:Escalate obstetric haemorrhage protocol.Immediate resuscitationI/V fluidsCBC + Cross matchClotting studiesUse of amniotomy or oxytocinExpedite birth transfer to obstetric unit if not already inUnstable:Escalate obstetric haemorrhage protocol.Immediate resuscitationI/V fluidsCBC + Cross matchClotting studiesUse of amniotomy or oxytocinExpedite birth transfer to obstetric unit if not already in</strong><strong>Unstable:</strong>Escalate obstetric haemorrhage protocol.Immediate resuscitationI/V fluidsCBC + Cross matchClotting studiesUse of amniotomy or oxytocinExpedite birth transfer to obstetric unit if not already in<strong>Unstable:</strong>Escalate obstetric haemorrhage protocol.Immediate resuscitationI/V fluidsCBC + Cross matchClotting studiesUse of amniotomy or oxytocinExpedite birth transfer to obstetric unit if not already in<strong>Vitally stable:I/V accessFHR monitoring by CTGMaternal monitoringVitally stable:I/V accessFHR monitoring by CTGMaternal monitoring</strong><strong>Vitally stable:</strong>I/V accessFHR monitoring by CTGMaternal monitoring<strong>Vitally stable:</strong>I/V accessFHR monitoring by CTGMaternal monitoring</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-023', 'chap-mm-10-01', '3.12.BREACH PRESENTATION IN LABOUR', 'Detailed medical reference and study guide on 3.12.BREACH PRESENTATION IN LABOUR.', 23, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-09931a29', 't-mm-10-023', 'html', '<h3><strong>Discuss:</strong></h3>
<ul><li>Risks and benefits of vaginal birth vs C/S</li><li>Serious risks to mother in C/S</li><li>Serious risk to baby in vaginal birth</li><li>Benefits of C/S in reducing the risk to baby are greater in early labor</li><li>Empower her to make a choice between continuing labor and C/S</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-024', 'chap-mm-10-01', '3.13.LARGE FOR GESTATIONAL AGE BABIES', 'Detailed medical reference and study guide on 3.13.LARGE FOR GESTATIONAL AGE BABIES.', 24, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-5f20f5a0', 't-mm-10-024', 'html', '<h3><strong>Discuss:</strong></h3>
<ul><li>Suspicion of LGA IS UNCERTAIN until baby is born</li><li>Risk and benefits of vaginal birth VS C/S</li><li>Higher chances of maternal problems in C/S</li><li>Higher chances of risks to baby as well as to mother with vaginal birth</li><li>In vaginal birth there is a risk of shoulder dystocia, brachial plexus injury, instrumental birth and perineal trauma.</li><li>Offer a choice to continue labor or C/S.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-025', 'chap-mm-10-01', '3.14.WOMEN WITH NO ANTENATAL CARE', 'Detailed medical reference and study guide on 3.14.WOMEN WITH NO ANTENATAL CARE.', 25, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8a0839f0', 't-mm-10-025', 'html', '<ul><li>Obstetric led care</li><li>Arrange interpreter if needed and encourage her to speak language whatever she is comfortable, Interpreter must be professional</li><li>Alert neonatal team, if relevant, anesthetist</li><li>Take full medical, psychological and social history</li><li>Try to find out the reason of no ANC offer support of her choice.</li><li>Contact with her GP, Medical/ Social services for more information</li><li>Explore possible vulnerability or safeguarding concerns sensitively like:</li><li>1. Young maternal age</li><li>2. Maternal mental health</li><li>3. Maternal learning disability</li><li>4. Maternal substance misuse</li><li>5. Domestic violence</li><li>6. Sexual abuse</li><li>7. Homelessness</li><li>8. Human trafficking</li><li>9. Undocumented migrant status</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-cbed7c61', 't-mm-10-025', 'heading', '10. FGM.', 2) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b40c0092', 't-mm-10-025', 'html', '<ul><li><strong>Assessment</strong></li></ul>
<h3><em><strong>Baby – USG Assessment:</strong></em></h3>
<ul><li>Viability</li><li>Presentation</li><li>Estimated gest age</li><li>Possibility of multiple pregnancy</li><li>Placental site</li></ul>
<h3><em><strong>Mother:</strong></em></h3>
<ul><li>CBC to rule out anemia</li><li>Hemoglobinopathies</li><li>Blood group + Rh status</li><li>Atypical red cell Antibodies</li><li>Random blood glucose</li><li>Asymptomatic bacteriuria</li><li>HIV, HeP B and syphilis</li></ul>
<p>Offer rapid HIV testing to women who are at risk of infection like suspected sexual abuse, I/V drugs abusers or immigrant of high prevalence</p>
<ul><li>Explain to women that when and why information regarding her pregnancy may need to be shared with other agencies.</li><li>Safeguarding concerns =&gt; refer to safeguarding services</li><li>Inform to healthcare professionals such as GP, Health visitors and paedriatic teams and social care professionals.</li></ul>', 3) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-026', 'chap-mm-10-01', '3.15.  PREVIOUS C/S', 'Detailed medical reference and study guide on 3.15.  PREVIOUS C/S.', 26, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ac185520', 't-mm-10-026', 'html', '<h3><strong>Discuss:</strong></h3>
<ul><li>Risks and benefits of VBAC vs C/S</li><li>Vaginal birth is associated with a small chance of uterine rupture instrumental birth.</li><li>Emergency C/S has higher chance of heavy</li><li>bleeding needing blood transfusion, infection, Complications in future pregnancies, longer hospital stay.</li><li>Little difference of outcome of baby in VBAC vs C/S</li><li>Support full range of analgesia</li><li>Regional analgesia increases chances of instrumental birth but reduces chances of another C/S</li><li>No need of continuous CTG and routine amniotomy.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-027', 'chap-mm-10-01', '3.16. LABOR AFTER 42 WEEKS OF PREGNANCY', 'Detailed medical reference and study guide on 3.16. LABOR AFTER 42 WEEKS OF PREGNANCY.', 27, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-ce00c0d5', 't-mm-10-027', 'html', '<ul><li>Offer continuous CTG</li><li>Support her decisions.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-028', 'chap-mm-10-01', '4. FETAL MONITORING DURING LABOUR', 'Detailed medical reference and study guide on 4. FETAL MONITORING DURING LABOUR.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-6af1f34a', 't-mm-10-028', 'html', '<ul><li>FHR monitoring is a guidance tool on fetal condition and not a diagnostic test.</li><li>Findings of FHR monitoring should be assessed along with clinical picture</li><li>Decisions are based on clinical picture along with FHR monitoring but never alone on FHR findings.</li><li>Women’s decision should be respected</li><li>Maintain one to one support</li><li>Increased intervention with continuous CTG as compared to intermittent auscultation.</li></ul>
<h3><strong>Initial assessment during labour:</strong></h3>
<ul><li>Assessment of risks</li><li>Review ANC record</li><li>Women’s preferences and method of fetal assessment discussed with her during antenatal period.</li><li>Discuss with women that risk assessment is a continuous process so, FHR monitoring tool may change during the course of labour.</li></ul>
<h3><strong>Intermittent Auscultation – IA:</strong></h3>
<ul><li>Offer to low risk women</li><li>Use either pinard stethoscope or Doppler USG</li><li>Carry out Intermittent Auscultation after a palpated contraction</li><li>For 1 min</li><li>Every 15 min in 1st stage and every 5 min in 2nd stage</li><li>Record o Partogram as single rate</li><li>Record accelerations and decelerations if heard.</li><li>Palpate maternal pulse and record 1 hourly and more oftenly if there are any concerns.</li><li>Ensure differentiation between the maternal and fetal heartbeat.</li><li>No fetal heart beat =&gt; urgent real time USG assessment.</li><li>Concerns about differentiating between fetal and maternal heart rates =&gt; seek help and consider changing the method of FHR monitoring.</li><li>In 2nd stage it is easier to mistakenly auscultate maternal rather than FHR</li><li><strong>IA</strong></li><li>No concernsContinue IANo concernsContinue IANo concernsContinue IANo concernsContinue IA</li><li>20 beats    in FHR on Partogram</li><li>FHR more from start of labor</li><li>Decelerations</li><li>IA more frequently (carry out IA after 3 consecutive contractions)</li><li>Carry out full review.</li><li>FHR concerns are confirmed</li><li>Summon help</li><li>Continuous CTG and explain to women and her companion</li><li>Transfer to Obstetric unit</li></ul>
<p>20 min CTG trace is normalAbnormal</p>
<p>Women want cCTG- Continue cCTG</p>
<ul><li>Review clinically</li></ul>
<p>Continue cCTG</p>
<h3><strong>Continuous Cardiotocography – </strong><strong>c</strong><strong>CTG:</strong></h3>
<ul><li>Use the following advice only in labour and not in antenatal period</li><li>While interpreting how baby is copying with labour take in to account fetal, maternal and labour factors along with CTG</li><li>Low threshold for escalation in presence of antenatal and intrapartum risk factors.</li></ul>
<h3><strong>Indications of CTG</strong></h3>
<ul><li><em><strong>3. Ongoing risk Assessment3. Ongoing risk Assessment</strong></em><em><strong>3. </strong></em><em><strong>Ongoing risk Assessment</strong></em><em><strong>3. </strong></em><em><strong>Ongoing risk Assessment</strong></em><em><strong>2. MDT Decision2. MDT Decision</strong></em><em><strong>2. </strong></em><em><strong>MDT Decision</strong></em><em><strong>2. </strong></em><em><strong>MDT Decision</strong></em></li><li><strong>1. Contractions &gt;5 in 10min or longer than 2 min.2. Abnormal IAIntrapartum hemorrhage 1. Contractions &gt;5 in 10min or longer than 2 min.2. Abnormal IAIntrapartum hemorrhage </strong>1. Contractions &gt;5 in 10min or longer than 2 min.2. Abnormal IAIntrapartum hemorrhage 1. Contractions &gt;5 in 10min or longer than 2 min.2. Abnormal IAIntrapartum hemorrhage <em><strong>1. </strong></em><em><strong>Antenatal, Risk Factors</strong></em></li><li>Non – cephalic FGRNon – cephalic FGRNon – cephalic FGRNon – cephalic FGRMaternal Risk factorFetal Risk Factor</li><li>Previous C/S</li><li>Full thickness uterine scar</li><li><em><strong>Maternal Risk FactorsFetal Risk FactorsOngoing Risk AssessmentMaternal Risk FactorsFetal Risk FactorsOngoing Risk Assessment</strong></em><em><strong>Maternal Risk Factors</strong></em><em><strong>Fetal Risk Factors</strong></em><em><strong>Ongoing Risk Assessment</strong></em><em><strong>Maternal Risk Factors</strong></em><em><strong>Fetal Risk Factors</strong></em><em><strong>Ongoing Risk Assessment</strong></em></li><li>Meconium PyrexiaSepsis or chorioamnionitisAbnormal pain reported by womenBlood stained liquorMaternal tachycardia HR &gt; 120 on 2 occasions 30 min apart.Severe HTN &gt; 160/110 single reading or &gt; 140/90 on 2 occasions 30 min apartConfirmed delay in 1st stage Regional analgesiaUse of oxytocinMeconium PyrexiaSepsis or chorioamnionitisAbnormal pain reported by womenBlood stained liquorMaternal tachycardia HR &gt; 120 on 2 occasions 30 min apart.Severe HTN &gt; 160/110 single reading or &gt; 140/90 on 2 occasions 30 min apartConfirmed delay in 1st stage Regional analgesiaUse of oxytocinMeconium PyrexiaSepsis or chorioamnionitisAbnormal pain reported by womenBlood stained liquorMaternal tachycardia HR &gt; 120 on 2 occasions 30 min apart.Severe HTN &gt; 160/110 single reading or &gt; 140/90 on 2 occasions 30 min apartConfirmed delay in 1st stage Regional analgesiaUse of oxytocinMeconium PyrexiaSepsis or chorioamnionitisAbnormal pain reported by womenBlood stained liquorMaternal tachycardia HR &gt; 120 on 2 occasions 30 min apart.Severe HTN &gt; 160/110 single reading or &gt; 140/90 on 2 occasions 30 min apartConfirmed delay in 1st stage Regional analgesiaUse of oxytocinSGA Gestation &gt; 42 weeksoligohydramniosPolyhydramniosRFM in 24 hoursSGA Gestation &gt; 42 weeksoligohydramniosPolyhydramniosRFM in 24 hoursSGA Gestation &gt; 42 weeksoligohydramniosPolyhydramniosRFM in 24 hoursSGA Gestation &gt; 42 weeksoligohydramniosPolyhydramniosRFM in 24 hours</li><li>Hypertension needing medication</li><li>Prolonged ruptured membranes</li><li>Any vaginal loss &gt; show</li><li>Suspected sepsis</li><li>DM requiring medication.</li></ul>
<h3><strong>Features of CTG:</strong></h3>
<ul><li>Contractions – by tocodynamometer</li><li>Base line FHR</li><li>Variability</li><li>Decelerations.</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
