INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-10-030', 'chap-mm-10-01', '6.BREECH PRESENTATION', 'Detailed medical reference and study guide on 6.BREECH PRESENTATION.', 30, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-df583fa2', 't-mm-10-030', 'html', '<ul><li>3 – 4% @ Term</li><li>20 – 32% undetected</li><li>Detection by abdominal examination = 70%</li><li>Recurrence of Breech – 9.9%</li><li>offer ECV to all women (except with C/I)</li><li>Explain Risk/ benefits of ECV</li><li>Women declining ECV =&gt; Offer vaginal Breech delivery Risk, benefits Vs elective C/S risk, benefits</li></ul>
<h3><strong>Perinatal Mortality:</strong></h3>
<ul><li>SVD = 1/1000</li><li>Vaginal Breech = 2/1000</li><li>C/S = 0.5/1000</li></ul>
<h3><strong>C/S is Recommended in:</strong></h3>
<ul><li>Hyper extended Neck</li><li>EFW &gt; 3.8</li><li>EFW &lt; 10th centile</li><li>Footling Breech</li><li>Antenatal fetal compromise</li><li>Unavailability of experienced breech Birth attendant.</li><li>Expert/ Skilled birth attendant</li><li>Not available – refer to unit where TBA is available</li><li>No unit available</li><li>C – Section.</li></ul>
<h3><strong>Planned Vaginal Birth:</strong></h3>
<ul><li>Risk 0f</li><li>Short term complications</li><li>Low APGAR</li><li>No    risk of long-term complications.</li></ul>
<h3><strong>Breech in labour:</strong></h3>
<ul><li>Need for emergency C/S = 45%</li></ul>
<h3><em><strong>1</strong></em><em><strong>st</strong></em><em><strong> stage: </strong></em></h3>
<ul><li>check for risk factor, expertise, available USG for EFW, leg and neck position – women preferences.</li></ul>
<h3><em><strong>II</strong></em><em><strong>0</strong></em><em><strong> Stage:</strong></em></h3>
<ul><li>Vaginal birth</li><li>C/S =&gt; 2 hours after passive II0 stage.</li><li>IOL avoided</li><li>Augmentation for slow progress with epidural &lt; 4 contraction/10min is considered</li><li>Continuous Fetal monitoring improve outcome.</li><li>FBS avoided</li><li>Positions = according to women’s preferences</li><li>Semi recurrent</li><li>All four</li><li>Dorsal lithotomy</li></ul>
<h3><strong>Delivery:</strong></h3>
<ul><li>Without traction hands off</li><li>Avoid or minimize tactile stimulation because it results in extension of arm and neck making delivery more difficult.</li></ul>
<h3><strong>Assisted Delivery if:</strong></h3>
<ul><li>5min from delivery of breech to head OR &gt; 3min umbilicus to Head.</li><li>Poor tone</li><li>Color change</li><li>Poor fetal condition</li><li>Extended arms/ neck</li></ul>
<h3><strong>Delivery of head:</strong></h3>
<ul><li>Forceps</li><li>M – S Veit Maneuver</li></ul>
<p>Avoid burns Marchel’s Maneuver.</p>
<h3><strong>Pre Term</strong><strong> Breech:</strong></h3>
<ul><li>Elective CS if birth is planned for maternal/ fetal compromise.</li><li>Pre – term Breech in labor =&gt; vaginal birth</li><li><strong>Head entrapm</strong><strong>ent</strong></li><li><em><strong>C/section</strong></em> – J shape or invented T</li><li><em><strong>Vaginal Birth</strong></em> – cervical incisions 2,6,10 ‘O clock with or without tocolysis</li></ul>
<h3><strong>Twins’</strong><strong> 1</strong><strong>st</strong><strong> Breech:</strong></h3>
<ul><li>Locked Twin 1/817</li><li>Elective CS &gt; 37weeks.</li><li>In labour – emergency CS – Not recommended</li><li>Assess clinically</li><li><em><strong>2</strong></em><em><strong>nd</strong></em><em><strong> Breech</strong></em> 40% incidence</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
