INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-d3f3d080', 't-mm-10-034', 'html', '<h3><strong>I</strong><strong>ntrapartum</strong><strong>:</strong></h3>
<ul><li>1. Prolong 1st stage</li><li>2. Secondary arrest</li><li>3. Prolong 2nd stage</li><li>4. Oxytocin augmentation</li><li>5. Assisted vaginal delivery.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Difficulty with delivery of face and chin</li><li>Turtle neck sign</li><li>Failure of restitution</li><li>Failure of shoulder to descend</li><li>Axial traction can be used</li><li>Lateral and any other avoided =&gt; nerve avulsion injury</li></ul>
<h3><strong>Prevention</strong></h3>
<ul><li>IOL</li><li>Don’t prevent in non-diabetic macrosomia</li><li>Prevent SD in diabetic macrosomia</li><li>Elective C/S consider in DM + EFW &gt; 4.5kg</li></ul>
<h3><strong>Post-natal Management of women/ New Born:</strong></h3>
<h3><strong>Maternal risks:</strong></h3>
<ul><li>PPH 11%</li><li>Perineal tear (3rd/4th degree) 38%</li><li>Vaginal, cervical laceration</li><li>Bladder rupture</li><li>Uterine rupture</li><li>Symphysial separation</li><li>Sacra iliac joint dislocation</li><li>Lateral femoral cutaneous neuropathy</li></ul>
<h3><strong>Fetal risks:</strong></h3>', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
