INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-87c7215e', 't-mm-10-036', 'html', '<p><strong>Caput:</strong> S/C extra periosteal serosanguineous fluid collection</p>
<p><strong>Cephalohematoma:</strong> sup periosteal, well defined, commonly don’t cross midline</p>
<p><strong>Subgaleal:</strong> or <strong>subapon</strong><strong>eurotic</strong><strong> H</strong><strong>aemorrhage</strong>, Cross midline due to multiple attempts of vacuum, fluctuant mass.</p>
<p><strong>Extradural chignon:</strong> Temporary swelling @ vacuum cup application site.</p>
<h3><strong>Maternal Outcomes:</strong></h3>', 6) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-cd232480', 't-mm-10-036', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>Vacuum</strong></td><td><strong>Forceps</strong></td><td><strong>Sequential</strong></td></tr><tr><td>Episiotomy</td><td>50 – 60</td><td>90%</td><td>&nbsp;</td></tr><tr><td>VV tear</td><td>10%</td><td>20 %</td><td>&nbsp;</td></tr><tr><td>OASI</td><td>1 – 4%</td><td>8 – 12%</td><td>17.4%</td></tr><tr><td>PPH</td><td>10 – 40%</td><td>10 – 40%</td><td>&nbsp;</td></tr><tr><td>Incontinence</td><td>Common @ 6 weeks improve with time</td></tr></tbody></table>', 7) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e1b80959', 't-mm-10-036', 'html', '<h3><strong>Fetal Outcomes:</strong></h3>', 8) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e2f652b8', 't-mm-10-036', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>Vacuum</strong></td><td><strong>Forceps</strong></td><td><strong>Sequential</strong></td></tr><tr><td>Cephal haematoma</td><td>1 – 12%</td><td>__</td><td>&nbsp;</td></tr><tr><td>Facial/ Scalp laceration</td><td>10%</td><td>10%</td><td>&nbsp;</td></tr><tr><td>Retinal Haemorrhage</td><td>17 – 38%</td><td>Less than vacuum</td><td>&nbsp;</td></tr><tr><td>Jaundice</td><td>5 – 15%</td><td>5 – 15%</td><td>&nbsp;</td></tr><tr><td>Subgaleal Haemorrhage</td><td>3 – 6/1000</td><td>__</td><td>&nbsp;</td></tr><tr><td>ICH / Subdural</td><td>5-15/10,000</td><td>5-15/10,000</td><td>2 – 3 times more</td></tr><tr><td>Cervical spine injury</td><td>__</td><td>Rare due to Kelland</td><td>&nbsp;</td></tr><tr><td>Skull fracture</td><td>__</td><td>Rare</td><td>&nbsp;</td></tr><tr><td>Fascial Nerve pulse</td><td>__</td><td>Rare</td><td>&nbsp;</td></tr><tr><td>Fetal death</td><td>Very rare</td><td>Very rare</td><td>&nbsp;</td></tr></tbody></table>', 9) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-dd13dc4c', 't-mm-10-036', 'html', '<ul><li>Malpractice litigation – failure to discontinue</li><li>Serious neonatal injuries – excessive pulls &gt;3 with forceps and prolong application - &gt;12min.</li><li>Paired cord sample after all attempts @ AVB</li><li>Incident reporting: failed AVB, SD, PPH, OASI, Neonatal problems</li><li><strong>ODON Device</strong> under trial</li><li>Head dis-impaction before/ in advance C/S =&gt; GPP</li><li>Episiotomy – discuss</li><li>routine – Nulliparous and Forceps.</li></ul>
<h3><strong>Care after AVB:</strong></h3>
<ul><li>Single dose of Ampicillin and clavulanic acid =&gt; Recommended after AVB</li><li>Hygiene</li><li>NSAIDs and Paracetamol routinely</li><li>Risk of urinary retention so inform regarding Bladder emptying</li><li>Urinary retention =&gt; post-void volume</li><li>Physiotherapy @ 3m0 offer to reduce urinary incontinence (38 – 31%)</li><li>Indwelling catheter 6 – 12 hours after AVB in regional anesthesia.</li><li>Post – traumatic stress disorder (PTSD) assessment of symptoms @ 1m0 and referral to skilled professionals.</li></ul>
<h3><strong>Future Birth:</strong></h3>
<ul><li>More chances of spontaneous labour after AVB (80% after AVB and 30% after 2nd stage C/S).</li><li>3RD AND 4th degree tear individual care plan in upcoming deliveries.</li></ul>', 10) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-b80fb749', 't-mm-10-036', 'heading', '13. INDUCTION OF LABOUR: IOL', 11) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-1f8a11a4', 't-mm-10-036', 'html', '<ul><li>1/5 pregnancies need IOL</li><li>2/3 give birth without intervention</li><li>15% need AVB</li><li>22% end up in C/S</li><li>Most women go into labour by 42 weeks</li><li>@ 38 weeks all women should be offered information regarding</li></ul>
<p>1. Risk of pregnancies that last longer than 42 weeks.</p>
<p>2. Expectant management</p>
<p>3. Membranes stripping</p>
<ul><li>Method</li><li>benefits of spontaneous labour</li><li>Uncomfortable, pain</li><li>Possible bleeding</li></ul>', 12) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
