INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-e4e23721', 't-mm-11-013', 'html', '<ul><li><strong>Antipsychotics</strong></li><li><em><strong>Antipsychotics are:</strong></em></li></ul>
<p>Diabetogenic: Offer OGTT in pregnancy</p>
<p>Weight: Advice regarding diet and exercise</p>
<p>Prolactin levels: Can cause infertility, if raise prolactin, then offer prolactin sparring drugs</p>', 4) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-809e061e', 't-mm-11-013', 'image', '/uploads/content-images/maternal_mind_book/image156.png', 5) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
