INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-11-014', 'chap-mm-11-01', '6.8. EATING DISORDERS', 'Detailed medical reference and study guide on 6.8. EATING DISORDERS.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-8e20a4ee', 't-mm-11-014', 'html', '<p>6 – fold     in perinatal mortality</p>
<p>Association with psychiatric disorder</p>
<p>Relapses in pregnancy</p>
<p>Fetal growth abnormalities</p>
<p>Feeding problems</p>
<p>anorexia has highest mortality among all psychiatric disorders.</p>
<h3><strong>Management:</strong></h3>
<ul><li>1. Discuss healthy eating and its benefits</li><li>2.Offer support regarding nutrition</li><li>3.Psychological intervention</li><li>4.Growth scans</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-11-015', 'chap-mm-11-01', '6.9. SLEEP PROBLEMS', 'Detailed medical reference and study guide on 6.9. SLEEP PROBLEMS.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-93840f1a', 't-mm-11-015', 'html', '<h3><strong>Discuss:</strong></h3>
<ul><li>Sleep hygiene</li><li>Avoid caffeine</li><li>Reduce bedtime activity</li><li>Healthy bed timing</li><li><strong>Medication:</strong></li><li>Promethazine in severe or chronic sleep problem</li></ul>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-11-016', 'chap-mm-11-01', '6.10.DRUG MISUSE', 'Detailed medical reference and study guide on 6.10.DRUG MISUSE.', 16, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-c70baf91', 't-mm-11-016', 'html', '<h3><strong>Alcohol:</strong></h3>
<p>If suspected use AUDIT test</p>
<p><em><strong>AUDIT</strong></em><em><strong> test</strong></em><em><strong>:</strong></em><em><strong> </strong></em>Is a 10-item screening tool developed by WHO to assess alcohol consumption, drinking behaviors and alcohol related problems.</p>
<p>Offer detoxification</p>
<p>Manage in collaboration with mental health and substance misuse services</p>
<p>Anomaly scan</p>
<p>Identify risk of accidental overdose</p>
<p>Offer treatment and support after child birth</p>
<p>Neonatal assessment to rule out congenital abnormalities and neonatal adaption syndrome.</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-11-017', 'chap-mm-11-01', '7.POST PARTUM CONTRACEPTION', 'Detailed medical reference and study guide on 7.POST PARTUM CONTRACEPTION.', 17, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-9e18774d', 't-mm-11-017', 'html', '<p>Less than six weeks postpartum</p>
<p>Postpartum women who are &lt; 48 hours postpartum can use Cu-IUDs (MEC Category 1).</p>
<p>Breastfeeding women who are &lt; 48 hours postpartum can generally use LNG-IUDs (MEC Category 2).</p>
<p>Breastfeeding women who are &lt; 6 weeks postpartum can generally use POPs and LNG and ETG implants (MEC Category 2).</p>
<p>Breastfeeding women who are ≥ 4 weeks postpartum can use the progesterone vaginal rings without restrictions (MEC Category 1)</p>
<p>Postpartum women who are ≥ 4 weeks postpartum can use Cu-IUDs and LNG-IUDs without restriction (MEC Category 1).</p>
<p>Postpartum women who are ≥ 21 days to 42 days postpartum without other risk factors for venous thromboembolism (VTE) can generally use CHCs (MEC Category 3).</p>
<p>Six weeks to less than six months postpartum</p>
<p>Breastfeeding women who are ≥ 6 weeks to &lt; 6 months postpartum can use POPs, POIs, and LNG and ETG implants without restriction (MEC Category 1).</p>
<p>Postpartum women who are &gt; 42 days postpartum can use CHCs without restriction (MEC Category 1).</p>
<p>Recommendations against some contraceptive methods</p>
<p>Postpartum women who are ≥ 48 hours to &lt; 4 weeks postpartum generally should not have an LNG-IUD inserted (MEC Category 3).</p>
<p>Breastfeeding women who are &lt; 6 weeks postpartum generally should not use POIs (depot medroxyprogesterone acetate or norethisterone enanthate) (MEC Category 3).</p>
<p>Breastfeeding women &lt; 6 weeks postpartum should not use CHCs (MEC Category 4).</p>
<p>Breastfeeding women ≥ 6 weeks to &lt; 6 months postpartum generally should not use CHCs (MEC Category 3).</p>
<p>Postpartum women who are &lt; 21 days postpartum and do not have other risk factors for VTE generally should not use CHCs (MEC Category 3).</p>
<p>Postpartum women who are &lt; 21 days postpartum with other risk factors for VTE should not use CHCs (MEC Category 4).</p>
<p>Postpartum women who are ≥ 21 days to 42 days postpartum with other risk factors for VTE generally should not use CHC (MEC Category 3).</p>
<p>Recommendations on emergency contraception</p>
<p>Breastfeeding women can use LNG for emergency contraceptive pills (ECPs) without restriction (MEC Category 1).</p>
<p>Women who are breastfeeding can generally use ulipristal acetate for ECPs (MEC Category 2).</p>', 1) ON DUPLICATE KEY UPDATE content=VALUES(content), type=VALUES(type);
INSERT INTO topics (id, chapter_id, title, description, `order`, is_published, author, source) VALUES ('t-mm-11-018', 'chap-mm-11-01', '8.MATERNAL MORTALITY', 'Detailed medical reference and study guide on 8.MATERNAL MORTALITY.', 18, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-a4a43bef', 't-mm-11-018', 'html', '<ul><li><strong>WHO</strong><strong> definitions</strong></li></ul>
